window.BASAIR_QUESTIONS=window.BASAIR_QUESTIONS.concat([{"id":"s2-967","number":967,"surah":2,"verses":[200],"verseLabel":"البقرة: 200","question":"ما سرّ الانتقال من الخطاب إلى الغيبة في قوله تعالى: ﴿فَمِنَ النَّاسِ مَنْ يَقُولُ﴾؟","answer":"انتقل إلى الغيبة للتقسيم والحكم على أصناف الناس بعد خطاب الحجيج، وليعرض النموذجين للنظر والاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص249–252، تحت البقرة: 200، في الالتفات.","url":""}]},{"id":"s2-968","number":968,"surah":2,"verses":[200],"verseLabel":"البقرة: 200","question":"ما دلالة حذف مفعول ﴿آتنا﴾ في قولهم: ﴿رَبَّنَا آتِنَا فِي الدُّنْيَا﴾؟","answer":"حذف المفعول لأن همهم مطلق عطاء الدنيا أيًا كان، من غير تعيين خير صالح ولا طلب للآخرة؛ ففضح الحذف ضيق مقصدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص250–253، تحت البقرة: 200، في حذف مفعول الإيتاء.","url":""}]},{"id":"s2-969","number":969,"surah":2,"verses":[200],"verseLabel":"البقرة: 200","question":"ما مناسبة ختم وصفهم بقوله تعالى: ﴿وَمَا لَهُ فِي الْآخِرَةِ مِنْ خَلَاقٍ﴾؟","answer":"الخلاق النصيب من الخير؛ ولما حصروا دعاءهم في الدنيا قرر أن لا نصيب لهم في الآخرة التي لم يطلبوها ولم يعملوا لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص252–254، تحت البقرة: 200، في نفي الخلاق وتوكيده بـ﴿من﴾.","url":""}]},{"id":"s2-970","number":970,"surah":2,"verses":[201],"verseLabel":"البقرة: 201","question":"ما سرّ التعبير في قوله تعالى عن الفريق الثاني: ﴿وَمِنْهُمْ مَنْ يَقُولُ﴾، ولم يكرر ﴿ومن الناس﴾؟","answer":"الضمير يعيده إلى الناس المذكورين قبلها، ويجعل الفريقين داخل جماعة واحدة مع اختلاف الهمة والطلب؛ فبعد صاحب الدنيا وحدها يظهر صاحب الدعاء المتوازن. والإيجاز يقوي المقابلة ولا يقطعها بإعادة الاسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص243–250، تحت البقرة: 201، في المقابلة بين الفريقين.","url":""}]},{"id":"s2-971","number":971,"surah":2,"verses":[201],"verseLabel":"البقرة: 201","question":"ما سرّ التعبير في قوله تعالى: ﴿فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً﴾، وكرر لفظ ﴿حسنة﴾؟","answer":"كررت ﴿حسنة﴾ لأن حسنة الدنيا غير حسنة الآخرة في حقيقتها ومجالها؛ فطلبوا لكل دار ما يلائمها من الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص250–252، تحت البقرة: 201، في تكرار الحسنة.","url":""}]},{"id":"s2-972","number":972,"surah":2,"verses":[201],"verseLabel":"البقرة: 201","question":"ما دلالة تنكير ﴿حَسَنَةً﴾ في الدنيا والآخرة؟","answer":"التنكير للتعظيم والتعميم؛ أي آتنا أي حسنة نافعة جامعة في كل من الدارين، من غير حصر في نعمة بعينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص250–252، تحت البقرة: 201، في تنكير الحسنة.","url":""}]},{"id":"s2-973","number":973,"surah":2,"verses":[201],"verseLabel":"البقرة: 201","question":"ما دلالة تقديم الجار والمجرور في ﴿فِي الدُّنْيَا حَسَنَةً﴾ و﴿فِي الْآخِرَةِ حَسَنَةً﴾؟","answer":"ليقسم المطلوب بوضوح بين الدارين ويقابل دعاء الفريق السابق الذي حصر نفسه في الدنيا؛ فالمؤمن لا يهمل دنياه لكنه يضع كل خير في أفقه الصحيح. والتقديم يبرز سعة الدعاء وتوازنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص250–253، تحت البقرة: 201، في ترتيب المتعلقات.","url":""}]},{"id":"s2-974","number":974,"surah":2,"verses":[201],"verseLabel":"البقرة: 201","question":"ما فائدة قوله تعالى: ﴿وَقِنَا عَذَابَ النَّارِ﴾ بعد طلب حسنة الآخرة؟","answer":"طلب حسنة الآخرة يشمل الخير، ثم صرح بالوقاية من النار لعظمها، وليجمع الدعاء بين تحصيل النفع ودفع الضر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص251–254، تحت البقرة: 201، في الجمع بين جلب الخير ودفع الشر.","url":""}]},{"id":"s2-975","number":975,"surah":2,"verses":[202],"verseLabel":"البقرة: 202","question":"ما دلالة الإشارة إليهم بقوله تعالى: ﴿أُولَئِكَ لَهُمْ نَصِيبٌ﴾؟","answer":"اسم الإشارة للبعد يرفع منزلتهم ويربط الجزاء بصفات الدعاء الجامع والعمل السابق؛ أولئك المتميزون لهم نصيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص255–257، تحت البقرة: 202، في اسم الإشارة.","url":""}]},{"id":"s2-976","number":976,"surah":2,"verses":[202],"verseLabel":"البقرة: 202","question":"ما سرّ إفراد ﴿نَصِيبٌ﴾ مع أن المشار إليهم جماعة؟","answer":"لأن لكل واحد منهم نصيبًا يخصه بحسب كسبه، أو لأن النصيب اسم جنس يصدق على أنصبة كثيرة. فالجمع في الأشخاص لا يجعل الجزاء كتلة واحدة، بل حسابًا فرديًا عادلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص256–258، تحت البقرة: 202، في إفراد النصيب.","url":""}]},{"id":"s2-977","number":977,"surah":2,"verses":[202],"verseLabel":"البقرة: 202","question":"ما سرّ التعبير في قوله تعالى: ﴿مِمَّا كَسَبُوا﴾ بعد أن حكى دعاءهم؟","answer":"حتى لا يفهم أن النجاة والحسنتين تحصلان بمجرد الكلمات؛ لهم نصيب من دعائهم وعملهم وما قدموه من أسباب الخير. وربط العطاء بالكسب يجمع الرجاء بالمسؤولية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص256–259، تحت البقرة: 202، في ربط النصيب بالكسب.","url":""}]},{"id":"s2-978","number":978,"surah":2,"verses":[202],"verseLabel":"البقرة: 202","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَاللَّهُ سَرِيعُ الْحِسَابِ﴾؟","answer":"سرعة الحساب تطمئن إلى قرب الجزاء وعدم ضياع الكسب، وتبين أن كثرة الخلق لا تؤخر محاسبتهم؛ فلا يشغله حساب عن حساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص258–260، تحت البقرة: 202، في مناسبة الفاصلة.","url":""}]},{"id":"s2-979","number":979,"surah":2,"verses":[203],"verseLabel":"البقرة: 203","question":"ما سرّ وصف أيام منى بأنها ﴿أَيَّامٍ مَعْدُودَاتٍ﴾؟","answer":"وصفها بالمعدودات لقلة عددها وسرعة انقضائها، ترغيبًا في اغتنامها بالذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص267، تحت البقرة: 203.","url":""}]},{"id":"s2-980","number":980,"surah":2,"verses":[203],"verseLabel":"البقرة: 203","question":"ما سرّ التعبير في قوله تعالى في أحد الفريقين ﴿فمن تعجل﴾، وفي الآخر ﴿ومن تأخر﴾ لا: تأنى؟","answer":"التعجل والتأخر متقابلان في وقت الانصراف المحدد، أما التأني فصفة في طريقة الفعل لا يلزم منها البقاء إلى اليوم التالي.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص272، تحت البقرة: 203.","url":""}]},{"id":"s2-981","number":981,"surah":2,"verses":[203],"verseLabel":"البقرة: 203","question":"ما سرّ التعبير في قوله تعالى في أيام منى: ﴿أَيَّامٍ مَعْدُودَاتٍ﴾ كما قال عن الصيام: ﴿أَيَّامًا مَعْدُودَاتٍ﴾؟","answer":"في الموضعين تهوين للمدة وحث على اغتنام زمن قصير ينقضي سريعًا؛ إلا أن القرينة تحدد المقصود هنا بأيام التشريق وهناك بأيام الصيام. الوصف الواحد يجعل قلة الأيام سببًا للنشاط لا للتفريط.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص261–264، تحت البقرة: 203، في دلالة المعدودات والقرينة.","url":""}]},{"id":"s2-982","number":982,"surah":2,"verses":[203],"verseLabel":"البقرة: 203","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَنْ تَعَجَّلَ فِي يَوْمَيْنِ﴾، دون أن يقال: «بعد يومين»؟","answer":"لأن المتعجل ينفر في أثناء اليوم الثاني من أيام التشريق وبعد أداء ذكره ورميه، فـ﴿في﴾ أدق في تصوير الزمن الذي يقع فيه الخروج. ولم يجعل اليومين مجرد مدة تنتهي ثم يبدأ الفعل خارجها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص264–267، تحت البقرة: 203، في ظرفية اليومين.","url":""}]},{"id":"s2-983","number":983,"surah":2,"verses":[203],"verseLabel":"البقرة: 203","question":"ما سرّ تكرار ﴿فَلَا إِثْمَ عَلَيْهِ﴾ للمتعجل والمتأخر؟","answer":"رفع الإثم عن المتعجل والمتأخر ليزيل ما تعلق بهما من أوهام الجاهلية، ويقرر أن كلا الخيارين جائز إذا صاحبه التقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص265–270، تحت البقرة: 203، في تكرار نفي الإثم.","url":""}]},{"id":"s2-984","number":984,"surah":2,"verses":[203],"verseLabel":"البقرة: 203","question":"ما سرّ تقديم التعجل على التأخر؟","answer":"قدم التعجل لأنه الأصل الذي يحتاج إلى بيان الرخصة، ولأنه الأكثر وقوعًا وحاجة إلى رفع الحرج، ثم ذكر التأخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص267–270، تحت البقرة: 203، في ترتيب الخيارين.","url":""}]},{"id":"s2-985","number":985,"surah":2,"verses":[203],"verseLabel":"البقرة: 203","question":"ما دلالة قوله تعالى: ﴿لِمَنِ اتَّقَى﴾ بعد إباحة الخيارين؟","answer":"أي إن انتفاء الإثم وكمال الانتفاع بالنسك لمن اتقى المحظورات وأخلص؛ فليست الإباحة منفصلة عن التقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص269–272، تحت البقرة: 203، في قيد التقوى.","url":""}]},{"id":"s2-986","number":986,"surah":2,"verses":[203],"verseLabel":"البقرة: 203","question":"ما سرّ تكرار الأمر بالتقوى بعد قوله تعالى: ﴿لِمَنِ اتَّقَى﴾؟","answer":"كرر التقوى لأن الأولى قيد للخيارين، والثانية أمر عام يجمع أعمال الحج وما بعده، فانتقل من الحكم الجزئي إلى الأصل الجامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص271–274، تحت البقرة: 203، في عطف الأمر بالتقوى.","url":""}]},{"id":"s2-987","number":987,"surah":2,"verses":[203],"verseLabel":"البقرة: 203","question":"ما مناسبة ختم الآية بالحشر، ودلالة تقديم ﴿إليه﴾ في قوله: ﴿وَاعْلَمُوا أَنَّكُمْ إِلَيْهِ تُحْشَرُونَ﴾؟","answer":"ذكر الحشر ليصل أعمال الحج بالحساب، وقدم ﴿إليه﴾ للقصر: إلى الله وحده تجمعون، فيحمل العلم بذلك على التقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص273–275، تحت البقرة: 203، في تقديم المتعلق ومناسبة الحشر.","url":""}]},{"id":"s2-988","number":988,"surah":2,"verses":[4],"verseLabel":"البقرة: 204، المنافقون: 4","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة عن المنافق: ﴿يُعْجِبُكَ قَوْلُهُ﴾، وقوله تعالى في سورة المنافقون: ﴿تُعْجِبُكَ أَجْسَامُهُمْ﴾؟","answer":"في البقرة المقام في رجل يستر خصومته بحسن القول فكان القول موضع الإعجاب، وفي المنافقون وصف هيئات قوم حاضرين فكانت الأجسام موضع الإعجاب؛ لكل سياق مظهر خداعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص797–798، تحت المنافقون: 4، في المقارنة بالبقرة: 204.","url":""}]},{"id":"s2-989","number":989,"surah":2,"verses":[204],"verseLabel":"البقرة: 204","question":"ما مناسبة الانتقال من الدعاء والذكر إلى قوله تعالى: ﴿وَمِنَ النَّاسِ مَنْ يُعْجِبُكَ قَوْلُهُ﴾؟","answer":"بعد ذكر صنفي الداعين عرض صنفًا حسن كلامه وفسد عمله؛ ليحذر من الاغترار بالدعاء والقول من غير حقيقة في القلب والسلوك.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص276–280، تحت البقرة: 204، في تقسيم أصناف الناس.","url":""}]},{"id":"s2-990","number":990,"surah":2,"verses":[204],"verseLabel":"البقرة: 204","question":"ما سرّ التعبير في قوله تعالى: ﴿يُعْجِبُكَ قَوْلُهُ﴾، دون أن يقال: «يعجبك هو»؟","answer":"حصر مصدر الإعجاب في القول؛ أما الشخص وحقيقته فتكشفهما أفعاله التالية. والإضافة إلى ضميره توحي بصنعة كلام تخصه ويحسن عرضها، دون أن تكون مرآة لقلبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص279–282، تحت البقرة: 204، في إسناد الإعجاب إلى القول.","url":""}]},{"id":"s2-991","number":991,"surah":2,"verses":[204],"verseLabel":"البقرة: 204","question":"ما فائدة قوله: ﴿فِي الْحَيَاةِ الدُّنْيَا﴾؟","answer":"كلامه يروج حيث تخفى السرائر ويُحكم بالمظاهر، أما الآخرة فتنكشف فيها الحقيقة ولا ينفع التزيين. والقيد قد يدل أيضًا على أن حديثه كله محصور في مصالح الدنيا ولو تلون بعبارات صالحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص281–284، تحت البقرة: 204، في قيد الحياة الدنيا.","url":""}]},{"id":"s2-992","number":992,"surah":2,"verses":[204],"verseLabel":"البقرة: 204","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيُشْهِدُ اللَّهَ عَلَى مَا فِي قَلْبِهِ﴾؟","answer":"يبلغ في تزيين باطنه أن يجعل الله شاهدًا على صدقه، مع أن الله أعلم بكذبه؛ فصار أعظم اسم وسيلة لخداع الناس. والعبارة تكشف أن كثرة الأيمان والتدين اللفظي قد تزيد النفاق قبحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص282–286، تحت البقرة: 204، في دلالة الإشهاد.","url":""}]},{"id":"s2-993","number":993,"surah":2,"verses":[204],"verseLabel":"البقرة: 204","question":"ما دلالة إبهام قوله تعالى: ﴿عَلَى مَا فِي قَلْبِهِ﴾؟","answer":"أبهم ما في قلبه ليشمل ما يدعيه من الإخلاص والمحبة والخير، مع أن باطنه يخالف ظاهره.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص283–287، تحت البقرة: 204، في إبهام مكنون القلب.","url":""}]},{"id":"s2-994","number":994,"surah":2,"verses":[204],"verseLabel":"البقرة: 204","question":"ما دلالة وصفه بأنه ﴿أَلَدُّ الْخِصَامِ﴾؟","answer":"الألد شديد الخصومة المعوج عنها، و﴿ألد الخصام﴾ أبلغ في تمكن الجدل والعداوة منه؛ فهو يحسن القول ثم يبالغ في مقاومة الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص284–288، تحت البقرة: 204، في صيغة التفضيل وإضافة الخصام.","url":""}]},{"id":"s2-995","number":995,"surah":2,"verses":[205],"verseLabel":"البقرة: 205","question":"ما سرّ التعبير في قوله تعالى: ﴿ويهلك الحرث والنسل﴾ فجمع أصلَي حياة الناس؟","answer":"الحرث أصل الأقوات والأموال، والنسل أصل بقاء الإنسان والحيوان؛ فجمعهما ليصور فسادًا يستأصل مقومات الحياة والحاضر والمستقبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص277–289، تحت البقرة: 205.","url":""}]},{"id":"s2-996","number":996,"surah":2,"verses":[205],"verseLabel":"البقرة: 205","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِذَا تَوَلَّى﴾؛ هل المعنى انصرف أم تولى سلطة؟","answer":"يحتمل أن يكون ﴿تولى﴾ بمعنى انصرف عن مجلس القول فأظهر فساده، ويحتمل أن يكون تولى ولاية وسلطة فسعى بالإفساد؛ واللفظ يتسع للصورتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص288–291، تحت البقرة: 205، في احتمالي التولي.","url":""}]},{"id":"s2-997","number":997,"surah":2,"verses":[205],"verseLabel":"البقرة: 205","question":"ما سرّ التعبير في قوله تعالى: ﴿سَعَى فِي الْأَرْضِ﴾، دون أن يقال: «أفسد» مباشرة؟","answer":"﴿سعى﴾ يدل على الجد والاجتهاد والحركة المقصودة؛ فليس فساده عارضًا، بل يبذل وسعه في نشره في الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص289–293، تحت البقرة: 205، في اختيار السعي.","url":""}]},{"id":"s2-998","number":998,"surah":2,"verses":[205],"verseLabel":"البقرة: 205","question":"ما سرّ التعبير في قوله تعالى: ﴿فِي الْأَرْضِ لِيُفْسِدَ فِيهَا﴾ وكرر ﴿في﴾ والضمير؟","answer":"الأول يحدد مجال حركته الواسع، والثاني يصرح بأن غاية الحركة إيقاع الفساد في المجال نفسه؛ فليست الأرض مجرد طريق بل محل الأثر. والتكرار يحيط المشهد بالفساد حركةً ونتيجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص291–294، تحت البقرة: 205، في تكرار الظرف والتعليل.","url":""}]},{"id":"s2-999","number":999,"surah":2,"verses":[205],"verseLabel":"البقرة: 205","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيُهْلِكَ الْحَرْثَ وَالنَّسْلَ﴾ بعد ﴿لِيُفْسِدَ فِيهَا﴾؟","answer":"ذكر أولًا الغاية العامة ثم أبرز أفظع صورها، حتى لا يبقى الفساد مفهومًا مجردًا؛ إنه طعام يضيع وحياة تنقطع. فالتفصيل يحول الحكم الأخلاقي إلى أثر يراه القارئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص294–297، تحت البقرة: 205، في التفصيل بعد الإجمال.","url":""}]},{"id":"s2-1000","number":1000,"surah":2,"verses":[205],"verseLabel":"البقرة: 205","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَاللَّهُ لَا يُحِبُّ الْفَسَادَ﴾؟","answer":"لأن الإفساد المذكور مناقض لما يحبه الله ويرضاه؛ فنفي المحبة وعيد للمفسد وبيان أن حسن قوله لا يغير حقيقة عمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص296–298، تحت البقرة: 205، في بلاغة الفاصلة.","url":""}]},{"id":"s2-1001","number":1001,"surah":2,"verses":[206],"verseLabel":"البقرة: 206","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِذَا قِيلَ لَهُ اتَّقِ اللَّهَ﴾ بالبناء للمجهول؟","answer":"لأن العبرة بنصيحة الحق لا باسم ناصح معين؛ أيًّا كان من يذكره بالله يرفض التذكير. كما يوحي بأن الكلمة شائعة ينبغي أن تقال له من كل من رأى فساده.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص299–301، تحت البقرة: 206، في البناء للمفعول.","url":""}]},{"id":"s2-1002","number":1002,"surah":2,"verses":[206],"verseLabel":"البقرة: 206","question":"ما سرّ اقتصار النصيحة له على قوله: ﴿اتَّقِ اللَّهَ﴾؟","answer":"لأن التقوى أصل جامع يرده عن نفاق القول والكبر والإفساد؛ فالكلمة القصيرة تستدعي مراقبة الله في جميع ما خالفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص300–302، تحت البقرة: 206، في مباشرة الأمر بالتقوى.","url":""}]},{"id":"s2-1003","number":1003,"surah":2,"verses":[206],"verseLabel":"البقرة: 206","question":"ما الصورة في قوله: ﴿أَخَذَتْهُ الْعِزَّةُ بِالْإِثْمِ﴾؟","answer":"صوّرت عزة الكبر قوةً تقبض عليه وتسوقه ملتبسًا بالإثم؛ بدل أن يأخذ نفسه إلى الحق تأخذه الحمية إلى مزيد المعصية. والباء تربط عزته بالإثم الذي يحميه ويدافع عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص301–304، تحت البقرة: 206، في الاستعارة.","url":""}]},{"id":"s2-1004","number":1004,"surah":2,"verses":[206],"verseLabel":"البقرة: 206","question":"ما سرّ التعبير في قوله تعالى: ﴿فَحَسْبُهُ جَهَنَّمُ﴾؟","answer":"أي تكفيه جهنم جزاءً وردعًا، وفي التعبير تهكم بعزته التي ظنها كافية لحمايته؛ فالذي لم تكفه نصيحة التقوى تكفيه النار. وتقديم ﴿حسبه﴾ يوجه الوعيد إليه مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص303–306، تحت البقرة: 206، في أسلوب الكفاية.","url":""}]},{"id":"s2-1005","number":1005,"surah":2,"verses":[206],"verseLabel":"البقرة: 206","question":"ما سرّ وصف جهنم بقوله تعالى: ﴿وَلَبِئْسَ الْمِهَادُ﴾ مع أن المهاد موضع راحة؟","answer":"استعمل المهاد ـ وهو موضع التهيئة والراحة ـ على سبيل التهكم والمقابلة؛ فجهنم قرارهم، لكنها بئس القرار الذي لا راحة فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص305–307، تحت البقرة: 206، في الاستعارة والذم.","url":""}]},{"id":"s2-1006","number":1006,"surah":2,"verses":[207],"verseLabel":"البقرة: 207","question":"ما سرّ تصوير بذل النفس لله بالبيع في قوله تعالى: ﴿يَشْرِي نَفْسَهُ ابْتِغَاءَ مَرْضَاتِ اللَّهِ﴾؟","answer":"جعل المؤمن نفسه رأس مال يقدمه لله مقابل رضاه، فالمقابلة مع المنافق تظهر صفقة النجاة أمام صفقة الإفساد والخسران.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص289–302، تحت البقرة: 207.","url":""}]},{"id":"s2-1007","number":1007,"surah":2,"verses":[207],"verseLabel":"البقرة: 207","question":"ما سرّ التعبير في قوله تعالى: ﴿مرضات الله﴾ بالمصدر الميمي، لا: رضا الله؟","answer":"﴿مرضات﴾ تفيد طلب ما تتجدد به أسباب الرضا وبلوغه، وتناسب حركة البذل والابتغاء أكثر من الاسم المجرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص296، تحت البقرة: 207.","url":""}]},{"id":"s2-1008","number":1008,"surah":2,"verses":[207],"verseLabel":"البقرة: 207","question":"ما سرّ مقابلة المفسد بقوله تعالى: ﴿وَمِنَ النَّاسِ مَنْ يَشْرِي نَفْسَهُ﴾؟","answer":"وضع النموذجين جنبًا إلى جنب: الأول يبيع كلامًا جميلًا ليحفظ مصلحته ويفسد، والثاني يبذل نفسه لله ليصلح. فتظهر قيمة الإنسان لا بما يقوله عن قلبه، بل بما يضحي به في عمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص307–310، تحت البقرة: 207، في مقابلة الصنفين.","url":""}]},{"id":"s2-1009","number":1009,"surah":2,"verses":[207],"verseLabel":"البقرة: 207","question":"ما سرّ التعبير في قوله تعالى: ﴿يَشْرِي نَفْسَهُ﴾؛ هل يبيعها أم يشتريها؟","answer":"﴿يشري﴾ تأتي بمعنى يبيع، أي يبذل نفسه طالبًا رضا الله، وهو في الحقيقة يشتري لها النجاة بهذا البيع. واجتماع المعنيين في صورة الصفقة يكشف أنه يخسر الظاهر ليربح الباقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص308–312، تحت البقرة: 207، في دلالة الفعل من الأضداد.","url":""}]},{"id":"s2-1010","number":1010,"surah":2,"verses":[207],"verseLabel":"البقرة: 207","question":"ما سرّ التعبير في قوله تعالى: ﴿ابْتِغَاءَ مَرْضَاتِ اللَّهِ﴾، ولم يذكر ثمنًا دنيويًا؟","answer":"المصدر يصرح بأن الدافع والغاية طلب رضا الله وحده؛ فلا شهرة ولا غنيمة هي عوض النفس المبذولة. وأضاف المرضاة إلى الله ليقابل من كان قوله يعجب الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص310–313، تحت البقرة: 207، في التعليل بالمصدر.","url":""}]},{"id":"s2-1011","number":1011,"surah":2,"verses":[207],"verseLabel":"البقرة: 207","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَاللَّهُ رَءُوفٌ بِالْعِبَادِ﴾ بصيغة العموم؟","answer":"ختم بالرأفة بالعباد لأن من يبيع نفسه لله يحفظ للناس الخير ويدفع عنهم فساد الصنف السابق، ولأن الله برأفته دلهم على طريق النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص312–315، تحت البقرة: 207، في العدول إلى العموم والفاصلة.","url":""}]},{"id":"s2-1012","number":1012,"surah":2,"verses":[208],"verseLabel":"البقرة: 208","question":"ما سرّ تكرار النهي عن اتباع خطوات الشيطان بعد وروده في سياق الطعام؟","answer":"هناك حذر من استدراجه في الحلال والحرام، وهنا من تجزئة الدين؛ فتكرر التحذير لأن المنهج واحد وتتنوع أبواب خطواته.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص302–313، تحت البقرة: 208.","url":""}]},{"id":"s2-1013","number":1013,"surah":2,"verses":[208],"verseLabel":"البقرة: 208","question":"ما مناسبة نداء المؤمنين قبل قوله تعالى: ﴿ادْخُلُوا فِي السِّلْمِ كَافَّةً﴾؟","answer":"لأن الإيمان لا يغني عن الاستسلام الكامل لكل شرع الله؛ فاستدعى وصفهم ليطالبهم بمقتضاه ويحذرهم من التجزئة. والنداء يوجه إلى جماعة قد آمنت أن تكمل آثار إيمانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص299–303، تحت البقرة: 208، في توجيه الخطاب.","url":""}]},{"id":"s2-1014","number":1014,"surah":2,"verses":[208],"verseLabel":"البقرة: 208","question":"ما المراد بـ﴿السِّلْمِ﴾: الإسلام أم السلام؟","answer":"السِّلم يفسر بالإسلام والطاعة، ويفسر بالصلح والسلام؛ والمعنى الجامع الدخول الكامل في طاعة الله وترك مسالك الشيطان والفرقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص300–305، تحت البقرة: 208، في معاني السلم.","url":""}]},{"id":"s2-1015","number":1015,"surah":2,"verses":[208],"verseLabel":"البقرة: 208","question":"ما سرّ التعبير في قوله تعالى: ﴿ادْخُلُوا فِي السِّلْمِ﴾، دون أن يقال: «التزموا السلم»؟","answer":"صوّر السلم أو الإسلام فضاءً محيطًا يدخل فيه المؤمن بكليته، فلا يبقى جزء من حياته خارجه. وحرف ﴿في﴾ يجعل الالتزام حالة شاملة لا أوامر متناثرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص302–306، تحت البقرة: 208، في استعارة الدخول.","url":""}]},{"id":"s2-1016","number":1016,"surah":2,"verses":[208],"verseLabel":"البقرة: 208","question":"إلى ماذا تتعلق ﴿كَافَّةً﴾: بالمؤمنين أم بالسِّلم؟","answer":"يجوز أن تكون ﴿كافة﴾ حالًا من المخاطبين: ادخلوا جميعًا، ويجوز أن تتعلق بالسلم: ادخلوا في شرائعه كلها؛ والمعنيان متلازمان في كمال الانقياد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص303–307، تحت البقرة: 208، في موقع ﴿كافة﴾.","url":""}]},{"id":"s2-1017","number":1017,"surah":2,"verses":[208],"verseLabel":"البقرة: 208","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ﴾؟","answer":"علل النهي بعداوة ثابتة ظاهرة، وقدم ﴿لكم﴾ ليجعل الخطر شخصيًا مباشرًا: هو عدوكم أنتم. فمن تبع خطواته بعد ظهور عداوته فقد سلّم قياده لمن أعلن قصد إهلاكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص307–310، تحت البقرة: 208، في التوكيد والتقديم.","url":""}]},{"id":"s2-1018","number":1018,"surah":2,"verses":[209],"verseLabel":"البقرة: 209","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِنْ زَلَلْتُمْ﴾، دون أن يقال: «فإن عصيتم»؟","answer":"الزلل أصله انحراف القدم وسقوطها، فصوّر الخروج عن الطريق بعد الدعوة إلى دخوله كقدم تنزلق من الصراط. وفي اللفظ تحذير من الخطوة الصغيرة التي تبدأ بها المعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص310–312، تحت البقرة: 209، في استعارة الزلل.","url":""}]},{"id":"s2-1019","number":1019,"surah":2,"verses":[209],"verseLabel":"البقرة: 209","question":"ما دلالة تقييد الزلل بقوله تعالى: ﴿مِنْ بَعْدِ مَا جَاءَتْكُمُ الْبَيِّنَاتُ﴾؟","answer":"لأن الانحراف بعد الدليل ليس كخطأ الجاهل؛ جاءت الحجج إليهم واضحة حتى كأنها هي التي قصدتهم، ثم اختاروا الزلل. والقيد يقطع عذر الالتباس ويغلظ المسؤولية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص311–314، تحت البقرة: 209، في قيد مجيء البينات.","url":""}]},{"id":"s2-1020","number":1020,"surah":2,"verses":[209],"verseLabel":"البقرة: 209","question":"ما سرّ التعبير في قوله تعالى: ﴿فَاعْلَمُوا أَنَّ اللَّهَ عَزِيزٌ حَكِيمٌ﴾، ولم يصرح بالعقوبة؟","answer":"الأمر بالعلم تهديد أبلغ؛ العزيز لا يعجزه من زل، والحكيم يضع عقوبته في موضعها فلا تكون بطشًا بلا ميزان. وترك الجزاء مطويًا يفتح أمام النفس كل ما تقتضيه الصفتان.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص313–315، تحت البقرة: 209، في بلاغة التحذير.","url":""}]},{"id":"s2-1021","number":1021,"surah":2,"verses":[209],"verseLabel":"البقرة: 209","question":"ما سرّ ختم الآية بـ﴿عَزِيزٌ حَكِيمٌ﴾ دون ﴿غفور رحيم﴾؟","answer":"العزيز لا يعجزه عقاب من زل بعد البينات، والحكيم يضع عقوبته وحكمه موضعهما؛ فناسب الوعيد المقام، لا اسما المغفرة والرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص314–315، تحت البقرة: 209، في مناسبة الاسمين.","url":""}]},{"id":"s2-1022","number":1022,"surah":2,"verses":[210],"verseLabel":"البقرة: 210","question":"ما سرّ التعبير في قوله تعالى: ﴿هل ينظرون إلا أن يأتيهم الله في ظلل من الغمام﴾؟","answer":"تهديد بانتظار يوم القضاء وظهور آيات السلطان الإلهي على الوجه اللائق به، لا وصفًا يجيز تشبيه الله بخلقه؛ والغمام يزيد المشهد مهابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص313–325، تحت البقرة: 210.","url":""}]},{"id":"s2-1023","number":1023,"surah":2,"verses":[210],"verseLabel":"البقرة: 210","question":"ما سرّ التعبير في قوله تعالى: ﴿هَلْ يَنْظُرُونَ إِلَّا أَنْ يَأْتِيَهُمُ اللَّهُ﴾، والنظر غير الانتظار؟","answer":"﴿ينظرون﴾ هنا بمعنى ينتظرون، وفي الاستفهام إنكار وتهديد: ماذا بقي بعد البينات إلا مجيء الفصل الذي لا ينفع عنده الإيمان؟ صوّر إمهالهم كأنهم يتعمدون انتظار النهاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص310–312، تحت البقرة: 210، في الاستفهام والقصر.","url":""}]},{"id":"s2-1024","number":1024,"surah":2,"verses":[210],"verseLabel":"البقرة: 210","question":"ما دلالة قوله تعالى: ﴿أَنْ يَأْتِيَهُمُ اللَّهُ﴾، وكيف يفهم على الوجه اللائق بالله سبحانه؟","answer":"الآية من نصوص الصفات؛ نؤمن بأن الله يأتي يوم القيامة على الوجه اللائق بجلاله، من غير تكييف ولا تمثيل، كما نؤمن بسائر صفاته، ولا نقيس إتيانه على إتيان المخلوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص311–314، تحت البقرة: 210، في توجيه الإتيان.","url":""}]},{"id":"s2-1025","number":1025,"surah":2,"verses":[210],"verseLabel":"البقرة: 210","question":"ما سرّ التعبير في قوله تعالى: ﴿فِي ظُلَلٍ مِنَ الْغَمَامِ﴾؟","answer":"الغمام مما يتوقع منه الرحمة والمطر والظل، فإذا جاء في مقام القضاء صار المشهد أشد مفاجأة وهيبة؛ ما ظنوه غطاء أمن يحمل أمر الفصل. وجمع ﴿ظلل﴾ يصور طبقات تحيط بالمشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص312–314، تحت البقرة: 210، في صورة الغمام والجمع.","url":""}]},{"id":"s2-1026","number":1026,"surah":2,"verses":[210],"verseLabel":"البقرة: 210","question":"ما سرّ عطف ﴿وَالْمَلَائِكَةُ﴾ بعد ذكر الغمام؟","answer":"عطف الملائكة لأنهم يجيئون في ذلك المشهد تنفيذًا لأمر الله وإحاطة بأهوال القيامة، فزاد ذكرهم المشهد مهابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص313–315، تحت البقرة: 210، في عطف الملائكة.","url":""}]},{"id":"s2-1027","number":1027,"surah":2,"verses":[210],"verseLabel":"البقرة: 210","question":"ما سرّ التعبير في قوله تعالى: ﴿وَقُضِيَ الْأَمْرُ﴾ بالماضي مع أنه مستقبل؟","answer":"عبّر بالماضي لتحقق الوقوع حتى كأنه وقع وانتهى، وبنى الفعل للمجهول لأن العناية بحسم الأمر لا بذكر القاضي المعلوم. جملة قصيرة تغلق كل باب للتأجيل والمراجعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص314–315، تحت البقرة: 210، في العدول إلى الماضي والبناء للمجهول.","url":""}]},{"id":"s2-1028","number":1028,"surah":2,"verses":[210],"verseLabel":"البقرة: 210","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَإِلَى اللَّهِ تُرْجَعُ الْأُمُورُ﴾، ودلالة تقديم ﴿إلى الله﴾؟","answer":"تقديم ﴿إلى الله﴾ يفيد القصر: إليه وحده مرجع الأمور وحكمها، وهو مناسب لمشهد القضاء الذي تنقطع فيه دعاوى الاستقلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص314–315، تحت البقرة: 210، في تقديم المتعلق والفاصلة.","url":""}]},{"id":"s2-1029","number":1029,"surah":2,"verses":[211],"verseLabel":"البقرة: 211","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعد ما جاءته﴾ بزيادة ﴿من﴾؟","answer":"تؤكد ابتداء التبديل مباشرة بعد تحقق مجيء النعمة ووضوحها، فتجعل الجريمة واقعة بعد تمام الحجة لا قبلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص325، تحت البقرة: 211.","url":""}]},{"id":"s2-1030","number":1030,"surah":2,"verses":[211],"verseLabel":"البقرة: 211","question":"ما سرّ التعبير في قوله تعالى: ﴿سَلْ بَنِي إِسْرَائِيلَ﴾، مع أن النبي ﷺ يعلم خبرهم بالوحي؟","answer":"ليس السؤال لطلب علم يجهله، بل لإقامة الحجة عليهم واستدعاء اعترافهم بما شاهد أسلافهم من الآيات؛ فكأن تاريخهم شاهد حاضر يُنادى ليجيب. والأمر يفضح التناقض بين كثرة الأدلة وقلة الانتفاع بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص316–319، تحت البقرة: 211، في غرض الأمر بالسؤال.","url":""}]},{"id":"s2-1031","number":1031,"surah":2,"verses":[211],"verseLabel":"البقرة: 211","question":"ما سرّ التعبير في قوله تعالى: ﴿كَمْ آتَيْنَاهُمْ مِنْ آيَةٍ بَيِّنَةٍ﴾، ولم يذكر عدد الآيات؟","answer":"﴿كم﴾ خبرية للتكثير والتهويل، والعدد غير مقصود بقدر تصوير فيض الأدلة التي لا يمكن إنكارها. و﴿من آية﴾ تبين أن كل فرد مما أوتوه كان واضحًا في نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص318–321، تحت البقرة: 211، في ﴿كم﴾ الخبرية والتمييز.","url":""}]},{"id":"s2-1032","number":1032,"surah":2,"verses":[211],"verseLabel":"البقرة: 211","question":"ما دلالة وصف الآية بأنها ﴿بَيِّنَةٍ﴾؟","answer":"الآية البينة هي الحجة الواضحة التي لا مجال للشك فيها؛ فوصفها بذلك يبين أن التبديل لم يكن لضعف الدليل بل للعناد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص319–322، تحت البقرة: 211، في وصف الآية.","url":""}]},{"id":"s2-1033","number":1033,"surah":2,"verses":[211],"verseLabel":"البقرة: 211","question":"ما سرّ تسمية الآيات ﴿نِعْمَةَ اللَّهِ﴾ في قوله: ﴿وَمَنْ يُبَدِّلْ نِعْمَةَ اللَّهِ﴾؟","answer":"لأن الدليل والهداية نعمة أعظم من المنافع المادية؛ فمن حولها من طريق إيمان إلى سبب كفر فقد بدل وظيفة النعمة لا ذاتها. والصياغة تجعل رفض الحق كفرانًا بعد إحسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص321–324، تحت البقرة: 211، في الاستعارة وتسميتها نعمة.","url":""}]},{"id":"s2-1034","number":1034,"surah":2,"verses":[211],"verseLabel":"البقرة: 211","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿فَإِنَّ اللَّهَ شَدِيدُ الْعِقَابِ﴾؟","answer":"رتب شدة العقاب على التبديل بعد مجيء النعمة والآية البينة؛ فالعقوبة تشتد بقدر وضوح الحجة. وإظهار اسم الله يربي المهابة ويمنع أن يبدو الوعيد نتيجة آلية بلا حاكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص323–326، تحت البقرة: 211، في التعليل والفاصلة.","url":""}]},{"id":"s2-1035","number":1035,"surah":2,"verses":[212],"verseLabel":"البقرة: 212","question":"ما سرّ التعبير في قوله تعالى: ﴿زُيِّنَ لِلَّذِينَ كَفَرُوا الْحَيَاةُ الدُّنْيَا﴾ بالبناء للمجهول؟","answer":"لأن المقصود وصف وقوع التزيين عليهم وآثاره، وقد تكون أسبابه الشيطان والهوى وزخرف الدنيا بإذن الله الكوني؛ فحذف الفاعل ليشملها. وصيغة الماضي تصور تمكن الزينة في نفوسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص327–330، تحت البقرة: 212، في البناء للمفعول.","url":""}]},{"id":"s2-1036","number":1036,"surah":2,"verses":[212],"verseLabel":"البقرة: 212","question":"ما سرّ التعبير في قوله تعالى: ﴿الْحَيَاةُ الدُّنْيَا﴾، دون أن يقال: «الدنيا» فقط؟","answer":"يذكرهم أن ما فتنوا به حياة مؤقتة ومرحلة أدنى، لا الدار النهائية؛ فالجمع بين الاسمين يكشف قصرها ودنو منزلتها. والزينة تعلقت بالمظهر الحاضر فحجبتهم عن العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص328–331، تحت البقرة: 212، في وصف الحياة بالدنيا.","url":""}]},{"id":"s2-1037","number":1037,"surah":2,"verses":[212],"verseLabel":"البقرة: 212","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيَسْخَرُونَ مِنَ الَّذِينَ آمَنُوا﴾ بالمضارع بعد ﴿زُيِّنَ﴾ بالماضي؟","answer":"الماضي يثبت رسوخ التزيين، والمضارع يصور سخريتهم المتجددة كلما رأوا المؤمنين وزهدهم في المقاييس الدنيوية. فالخلل الباطن المستقر ينتج سلوكًا يتكرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص330–333، تحت البقرة: 212، في اختلاف الزمنين.","url":""}]},{"id":"s2-1038","number":1038,"surah":2,"verses":[212],"verseLabel":"البقرة: 212","question":"ما سرّ التعبير في قوله تعالى: ﴿وَالَّذِينَ اتَّقَوْا فَوْقَهُمْ يَوْمَ الْقِيَامَةِ﴾، دون أن يقال: «والمؤمنون»؟","answer":"عدل إلى التقوى لأن التفوق ليس بمجرد الاسم، بل بإيمان أثمر مراقبة وعملًا؛ وهي الصفة المقابلة للافتتان بالدنيا. و﴿فوقهم﴾ يقلب موازين السخرية: من استُصغر هنا يعلو هناك.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص331–334، تحت البقرة: 212، في العدول إلى وصف التقوى.","url":""}]},{"id":"s2-1039","number":1039,"surah":2,"verses":[212],"verseLabel":"البقرة: 212","question":"ما دلالة تقديم ﴿فَوْقَهُمْ﴾ على ﴿يَوْمَ الْقِيَامَةِ﴾؟","answer":"لإبراز انقلاب المنزلة فور سماع الجملة؛ العلو هو الرد المباشر على سخريتهم، ثم يحدد زمن ظهوره الكامل. والتقديم يضع الفريقين في صورة طباق مكاني محسوس.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص332–335، تحت البقرة: 212، في تقديم الظرف المكاني.","url":""}]},{"id":"s2-1040","number":1040,"surah":2,"verses":[212],"verseLabel":"البقرة: 212","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَاللَّهُ يَرْزُقُ مَنْ يَشَاءُ بِغَيْرِ حِسَابٍ﴾؟","answer":"حتى لا تُتخذ سعة رزق الكافر دليل كرامة ولا قلة مال المؤمن دليل هوان؛ فالرزق يجري بمشيئة الله وحكمته، والجزاء الأخروي أوسع من مقاييسهم. و﴿بغير حساب﴾ تفيد السعة التي لا يحدها تقدير البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص334–335، تحت البقرة: 212، في التذييل بالرزق.","url":""}]},{"id":"s2-1041","number":1041,"surah":2,"verses":[213],"verseLabel":"البقرة: 213","question":"ما سرّ اختيار لفظ ﴿الصراط﴾ دون الطريق أو السبيل؟","answer":"الصراط يوحي بطريق واضح واسع موصل بلا تشعب، فناسب الحق الواحد الذي يهدي الله إليه وسط اختلاف الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص347، تحت البقرة: 213.","url":""}]},{"id":"s2-1042","number":1042,"surah":2,"verses":[165],"verseLabel":"البقرة: 213، النساء: 165","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿فَبَعَثَ اللَّهُ النَّبِيِّينَ مُبَشِّرِينَ وَمُنْذِرِينَ﴾، وقوله تعالى في النساء: ﴿رُسُلًا مُبَشِّرِينَ وَمُنْذِرِينَ﴾؟","answer":"سياق البقرة عام يبدأ بقوله: ﴿كان الناس أمة واحدة﴾، ولفظ النبيين أعم من الرسل، فناسب عمومَ الناس وامتدادَ تاريخ الهداية. أما النساء فسبق موضعها تعداد رسل معينين وقوله: ﴿ورسلاً قد قصصناهم عليك من قبل﴾، فناسب تخصيص الوظيفة بالرسل واتساق اللفظ مع السياق القريب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص394–396، تحت النساء: 165، في المقارنة بالبقرة: 213.","url":""}]},{"id":"s2-1043","number":1043,"surah":2,"verses":[118],"verseLabel":"البقرة: 213، يونس: 19، هود: 118","question":"ما وجه الجمع بين كون الناس ﴿أُمَّةً وَاحِدَةً﴾ في البقرة ويونس، وقوله في هود: ﴿وَلَوْ شَاءَ رَبُّكَ لَجَعَلَ النَّاسَ أُمَّةً وَاحِدَةً﴾؟","answer":"المراد في البقرة ويونس أنهم كانوا مجتمعين في مرحلة سابقة ثم اختلفوا، أما هود فينفي دوام اجتماعهم على الإيمان في جميع الأزمنة؛ فلا تعارض بين وحدة عارضة قديمة وعدم جعلهم أمة واحدة دائمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص43–44، تحت هود: 118، في المقارنة بالبقرة: 213 ويونس: 19.","url":""}]},{"id":"s2-1044","number":1044,"surah":2,"verses":[213],"verseLabel":"البقرة: 213","question":"ما سرّ التعبير في قوله تعالى: ﴿كَانَ النَّاسُ أُمَّةً وَاحِدَةً﴾، وعلى ماذا كانوا متحدين؟","answer":"تحتمل اتحادهم على الفطرة والهدى ثم اختلافهم، أو اجتماعهم على حال واحدة احتاجت إلى البيان؛ والمقصود أن التفرق ليس الأصل الذي خُلقوا عليه. ثم جاءت الرسالات لتحكم في اختلاف نشأ بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص336–340، تحت البقرة: 213، في معنى الأمة الواحدة.","url":""}]},{"id":"s2-1045","number":1045,"surah":2,"verses":[213],"verseLabel":"البقرة: 213","question":"ما سرّ التعبير في قوله تعالى: ﴿فَبَعَثَ اللَّهُ النَّبِيِّينَ﴾؛ أين ذُكر الاختلاف الذي سبّب بعثهم؟","answer":"طوى جملة «فاختلفوا» لدلالة ما بعده: ﴿فيما اختلفوا فيه﴾؛ فانتقل سريعًا من الوحدة إلى العلاج، وترك السبب يُستخرج من السياق. هذا حذف يختصر تاريخًا كاملًا ويجعل الرسالة جوابًا مباشرًا للانقسام.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص339–342، تحت البقرة: 213، في الحذف ودلالة الفاء.","url":""}]},{"id":"s2-1046","number":1046,"surah":2,"verses":[213],"verseLabel":"البقرة: 213","question":"ما سرّ تقديم ﴿مُبَشِّرِينَ﴾ على ﴿مُنْذِرِينَ﴾؟","answer":"قدمت البشارة لأن الرحمة والفضل أصل الرسالات، ولأنها أحب إلى النفوس وأدعى لقبول الدعوة، ثم جاء الإنذار لمن أعرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص340–343، تحت البقرة: 213، في ترتيب الوصفين.","url":""}]},{"id":"s2-1047","number":1047,"surah":2,"verses":[213],"verseLabel":"البقرة: 213","question":"ما سرّ التعبير في قوله تعالى: ﴿وَأَنْزَلَ مَعَهُمُ الْكِتَابَ﴾، مع تعدد الكتب؟","answer":"أفرد الكتاب باعتبار جنس الوحي ووحدة أصله ومقصده، فكأن الكتب كلها كتاب واحد في إقامة الحق. و﴿معهم﴾ تقرن النص بالمبلغ البشري الذي يبين تطبيقه، فلا تنفصل الرسالة عن الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص341–344، تحت البقرة: 213، في إفراد الكتاب والمعية.","url":""}]},{"id":"s2-1048","number":1048,"surah":2,"verses":[213],"verseLabel":"البقرة: 213","question":"ما دلالة تقييد إنزال الكتاب بقوله تعالى: ﴿بِالْحَقِّ﴾؟","answer":"أي أنزل الكتاب ملابسًا للصدق والعدل ولإقامة الحق؛ فليس الاختلاف ناشئًا من نقص فيه، بل من بغي من أوتوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص342–345، تحت البقرة: 213، في دلالة الباء.","url":""}]},{"id":"s2-1049","number":1049,"surah":2,"verses":[213],"verseLabel":"البقرة: 213","question":"ما سرّ التعبير في قوله تعالى: ﴿لِيَحْكُمَ بَيْنَ النَّاسِ﴾، والكتاب لا يتكلم ويحكم بنفسه؟","answer":"أسند الحكم إلى الكتاب مجازًا؛ لأنه يتضمن الأحكام والمعايير التي يحكم بها الرسول والعلماء بين الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص343–346، تحت البقرة: 213، في إسناد الحكم.","url":""}]},{"id":"s2-1050","number":1050,"surah":2,"verses":[213],"verseLabel":"البقرة: 213","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا اخْتَلَفَ فِيهِ إِلَّا الَّذِينَ أُوتُوهُ﴾، مع أن الكتاب جاء ليزيل الاختلاف؟","answer":"لأن المشكلة لم تكن غموض الكتاب، بل بغي بعض أهله بعد العلم؛ فالدواء نفسه يصير موضع نزاع حين تفسد الإرادة. والقصر يفضح أن أحق الناس بالاجتماع عليه هم الذين صنعوا الانقسام فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص344–347، تحت البقرة: 213، في القصر وتقديم المتعلق.","url":""}]},{"id":"s2-1051","number":1051,"surah":2,"verses":[213],"verseLabel":"البقرة: 213","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ بَعْدِ مَا جَاءَتْهُمُ الْبَيِّنَاتُ بَغْيًا بَيْنَهُمْ﴾؟","answer":"أكد أن اختلافهم وقع بعد وصول الحجج الواضحة، وأن دافعه الحسد وطلب العلو لا نقص المعرفة. و﴿بينهم﴾ يجعل البغي متبادلًا داخل الجماعة التي كان ينبغي أن يوحدها الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص345–348، تحت البقرة: 213، في قيد البينات وتعليل البغي.","url":""}]},{"id":"s2-1052","number":1052,"surah":2,"verses":[213],"verseLabel":"البقرة: 213","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَاللَّهُ يَهْدِي مَنْ يَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ﴾؟","answer":"بعد عرض اختلاف أهل الكتاب يبين أن النجاة ليست بالذكاء وحده، بل بتوفيق الله لمن يطلب الحق؛ والصراط المستقيم طريق لا عوج فيه وسط طرق متنازعة. وتنكيره للتعظيم، مع بقاء الهداية خاضعة للحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص347–348، تحت البقرة: 213، في التذييل بالصراط.","url":""}]},{"id":"s2-1053","number":1053,"surah":2,"verses":[214],"verseLabel":"البقرة: 214","question":"ما سرّ التعبير في قوله تعالى: ﴿مستهم البأساء والضراء وزلزلوا﴾ بهذا التصاعد؟","answer":"بدأ بفقر وخوف خارجي، ثم ألم يمس البدن، ثم اضطراب يهز الكيان كله؛ فتصاعد حتى بلغ سؤال النصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص350–363، تحت البقرة: 214.","url":""}]},{"id":"s2-1054","number":1054,"surah":2,"verses":[16],"verseLabel":"البقرة: 214، آل عمران: 142، التوبة: 16","question":"ما سرّ تفصيل الابتلاء في البقرة، واختصاره أو اختلاف عرضه في آل عمران والتوبة؟","answer":"خاطبت البقرة المؤمنين عامة وعرّفتهم سنة الابتلاء التي جرت على الأمم قبلهم، فناسبها التفصيل والتسلية بذكر البأساء والضراء والزلزال. أما آل عمران فخاطبت أهل أُحد في واقعة مخصوصة، فخصت الجهاد والصبر. والتوبة خاطبت المؤمنين بعد الفتح في مقام تمييز صدق الباطن من النفاق، فناسب سؤالهم هل يظنون أنهم سيُتركون بلا اختبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص21–23، تحت آل عمران: 142، في المقارنة بالبقرة: 214 والتوبة: 16.","url":""}]},{"id":"s2-1055","number":1055,"surah":2,"verses":[29],"verseLabel":"البقرة: 214، الفتح: 29","question":"ما سرّ التعبير في قوله تعالى في البقرة: ﴿وَالَّذِينَ آمَنُوا مَعَهُ﴾، بينما قال في الفتح: ﴿مُحَمَّدٌ رَسُولُ اللَّهِ وَالَّذِينَ مَعَهُ﴾ من غير أن يذكر الإيمان؟","answer":"يصف موضع البقرة عِظم الابتلاء الذي أصاب الرسول والمؤمنين المصاحبين له؛ فصرح بالإيمان لأن المقام يبين أن هذه المعية الإيمانية لها ثمن من الصبر والثبات. أما الفتح فالمقام في تعداد صفات أصحاب النبي ﷺ الظاهرة في جهادهم وعبادتهم وتراحمهم، وكانت معيتهم له قد عرَّفتهم، ثم جاءت الصفات لتكشف حقيقتها؛ فلم يحتج السياق إلى إعادة وصف الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص26–27، تحت التوبة: 88، في مبحث المقارنة بالبقرة: 214 والفتح: 29 والتحريم: 8.","url":""}]},{"id":"s2-1056","number":1056,"surah":2,"verses":[214],"verseLabel":"البقرة: 214","question":"ما سرّ افتتاح الآية بقوله تعالى: ﴿أَمْ حَسِبْتُمْ أَنْ تَدْخُلُوا الْجَنَّةَ﴾؟","answer":"الاستفهام للإنكار والتربية: لا تحسبوا دخول الجنة يقع بلا ابتلاء يمحص الإيمان، وقد مضت هذه السنة في الأمم السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص349–352، تحت البقرة: 214، في الاستفهام الانتقالي.","url":""}]},{"id":"s2-1057","number":1057,"surah":2,"verses":[214],"verseLabel":"البقرة: 214","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَمَّا يَأْتِكُمْ مَثَلُ الَّذِينَ خَلَوْا﴾، دون أن يقال: «ولم تُبتلوا»؟","answer":"﴿لما﴾ تنفي مع توقع الوقوع، و﴿مثل﴾ تستحضر حال السابقين ونمط ابتلائهم لا مجرد حادثة واحدة؛ فكأن سنّة الطريق ستأتيهم في صورة شبيهة. لم يشترط التطابق، بل المشاركة في أصل الامتحان.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص351–354، تحت البقرة: 214، في ﴿لما﴾ والتشبيه.","url":""}]},{"id":"s2-1058","number":1058,"surah":2,"verses":[214],"verseLabel":"البقرة: 214","question":"ما سرّ الجمع بين ﴿الْبَأْسَاءُ وَالضَّرَّاءُ﴾؟","answer":"البأساء ما يصيب المال والمعيشة من شدة، والضراء ما يمس البدن والنفس؛ فجمع وجهي الألم الخارجي والذاتي. ثم أضاف الزلزلة ليبلغ التصوير اضطراب الجماعة كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص352–355، تحت البقرة: 214، في الجمع بين نوعي البلاء.","url":""}]},{"id":"s2-1059","number":1059,"surah":2,"verses":[214],"verseLabel":"البقرة: 214","question":"ما سرّ التعبير في قوله تعالى: ﴿وَزُلْزِلُوا﴾ بعد ﴿مَسَّتْهُمُ الْبَأْسَاءُ وَالضَّرَّاءُ﴾؟","answer":"المس يصور وقوع البلاء، والزلزلة تصور أثره المتكرر العنيف في النفوس حتى يكاد يقتلع ثباتها؛ فانتقل من الألم إلى الاضطراب. وتكرار مبنى الفعل يناسب تتابع الهزات.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص353–356، تحت البقرة: 214، في المبالغة بالزلزلة.","url":""}]},{"id":"s2-1060","number":1060,"surah":2,"verses":[214],"verseLabel":"البقرة: 214","question":"ما دلالة بلوغ البلاء بالرسول والمؤمنين إلى قولهم: ﴿مَتَى نَصْرُ اللَّهِ﴾؟","answer":"ليس قولهم شكًا في وعد الله، بل استبطاء للنصر تحت شدة البلاء وتضرع بطلبه؛ حتى بلغ الامتحان غايته التي يظهر عندها تمام الافتقار.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص354–356، تحت البقرة: 214، في غرض الاستفهام.","url":""}]},{"id":"s2-1061","number":1061,"surah":2,"verses":[214],"verseLabel":"البقرة: 214","question":"ما سرّ توكيد الجواب بقوله تعالى: ﴿أَلَا إِنَّ نَصْرَ اللَّهِ قَرِيبٌ﴾؟","answer":"﴿ألا﴾ للتنبيه، و﴿إن﴾ للتوكيد، والجملة الاسمية تثبت قرب النصر؛ فجاء الجواب قويًا بعد بلوغ الزلزلة غايتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص355–356، تحت البقرة: 214، في توكيد البشارة.","url":""}]},{"id":"s2-1062","number":1062,"surah":2,"verses":[214],"verseLabel":"البقرة: 214","question":"ما سرّ وصف النصر بأنه ﴿قَرِيبٌ﴾ من غير تحديد موعده؟","answer":"ليحفظ اليقين والأمل دون أن يحول الوعد إلى حساب زمني يختبره الناس بأهوائهم؛ كل آت قريب، والفرج أقرب ما يكون عند تمام الابتلاء. الإبهام يربي الثبات لا انتظار تاريخ محدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص355–356، تحت البقرة: 214، في تنكير الزمن والاكتفاء بالقرب.","url":""}]},{"id":"s2-1063","number":1063,"surah":2,"verses":[215],"verseLabel":"البقرة: 215","question":"ما سرّ توجيه جواب سؤالهم ﴿مَاذَا يُنْفِقُونَ﴾ إلى بيان جهات الإنفاق؟","answer":"ضمن الجواب بيان المنفَق ووجهته: سماه خيرًا وبدأ بأولى الناس به. فصلاح جهة الإنفاق أهم من السؤال عن المقدار وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص357–360، تحت البقرة: 215، في الأسلوب الحكيم.","url":""}]},{"id":"s2-1064","number":1064,"surah":2,"verses":[215],"verseLabel":"البقرة: 215","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا أَنْفَقْتُمْ مِنْ خَيْرٍ﴾، وسمّى المال خيرًا؟","answer":"ليشمل كل مال حلال نافع قل أو كثر، ويذكر أن ما يبذل في وجهه الصحيح خير لصاحبه والمتلقي. و﴿من﴾ بيانية أو تبعيضية تمنع توهم اشتراط إنفاق المال كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص358–361، تحت البقرة: 215، في إطلاق الخير.","url":""}]},{"id":"s2-1065","number":1065,"surah":2,"verses":[215],"verseLabel":"البقرة: 215","question":"ما سرّ تقديم الوالدين على بقية المستحقين؟","answer":"لأن حقهما آكد، وحاجتهما مسؤولية مباشرة على الولد، والإحسان إليهما يجمع النفقة والبر؛ ثم اتسعت الدائرة إلى الأقربين فالضعفاء والمنقطعين. فالترتيب يبدأ بمن لا يجوز تجاوزه إلى الأبعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص359–362، تحت البقرة: 215، في ترتيب جهات الإنفاق.","url":""}]},{"id":"s2-1066","number":1066,"surah":2,"verses":[215],"verseLabel":"البقرة: 215","question":"ما سرّ ذكر ﴿الْأَقْرَبِينَ﴾ بعد الوالدين مع دخولهما في القرابة؟","answer":"أفرد الوالدين لعظم حقهما، ثم عم سائر الأقارب؛ فهو ذكر للخاص ثم العام بحسب قوة الصلة. وهذا يمنع أن يذوب حق الأصلين داخل دائرة واسعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص360–362، تحت البقرة: 215، في عطف العام على الخاص.","url":""}]},{"id":"s2-1067","number":1067,"surah":2,"verses":[215],"verseLabel":"البقرة: 215","question":"ما سرّ ختم قائمة المستحقين بـ﴿ابْنِ السَّبِيلِ﴾؟","answer":"لأنه أبعدهم صلةً بالنسب لكنه قريب بالحاجة الطارئة؛ فبعد دوائر الأسرة ذكر الغريب المنقطع ليكمل المجتمع مسؤوليته. وإضافته إلى السبيل تصوره كأن الطريق صار أهله بعد انقطاعه عن أهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص361–363، تحت البقرة: 215، في ترتيب الجهات وصورة ابن السبيل.","url":""}]},{"id":"s2-1068","number":1068,"surah":2,"verses":[215],"verseLabel":"البقرة: 215","question":"ما دلالة تكرار الخير في قوله تعالى: ﴿وَمَا تَفْعَلُوا مِنْ خَيْرٍ فَإِنَّ اللَّهَ بِهِ عَلِيمٌ﴾؟","answer":"وسع الدائرة من الإنفاق إلى كل فعل خير، وطمأن أن ما يخفى من البذل والنية محفوظ في علم الله. وتقديم ﴿به﴾ يبرز أن هذا العمل بعينه لا يضيع ولو نسيه الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص362–363، تحت البقرة: 215، في التعميم والتذييل.","url":""}]},{"id":"s2-1069","number":1069,"surah":2,"verses":[216],"verseLabel":"البقرة: 216","question":"ما سرّ التعبير في قوله تعالى: ﴿وعسى أن تكرهوا شيئًا وهو خير لكم﴾؟","answer":"يصحح قصر الحكم على الشعور العاجل؛ فقد تخفى المصلحة وراء المشقة كما يخفى الشر وراء اللذة، والعلم الكامل لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص368–379، تحت البقرة: 216.","url":""}]},{"id":"s2-1070","number":1070,"surah":2,"verses":[19],"verseLabel":"البقرة: 216، النساء: 19","question":"ما سرّ ذكر وجهي الكراهة والمحبة في البقرة، والاكتفاء بوجه الكراهة في النساء؟","answer":"آية البقرة في سياق القتال الذي كرهه المخاطبون وأحبوا السلامة منه؛ فالمقام قائم على بيان طرفي الخير والشر: قد يكون الخير في المكروه، والشر في المحبوب، فناسب ذكر الطرفين. أما النساء ففي معالجة كراهية الزوجة وخشية التسرع في فراقها؛ فالمقصود حبس النفس عن قرار الفراق بسبب المكروه، ولو ذُكر احتمال الشر في المحبوب لفتح للنفس باب الميل إلى غيرها، فاقتصر السياق على الوجه الذي يعالج المشكلة مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص754–755، تحت النساء: 19، في المقارنة بالبقرة: 216.","url":""}]},{"id":"s2-1071","number":1071,"surah":2,"verses":[19],"verseLabel":"البقرة: 216، النساء: 19","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿وَهُوَ خَيْرٌ لَكُمْ﴾، وقوله تعالى في النساء: ﴿وَيَجْعَلَ اللَّهُ فِيهِ خَيْرًا كَثِيرًا﴾؟","answer":"في البقرة أخبر عن حقيقة خفية ثابتة في الأمر نفسه: ما تكرهونه من القتال قد يكون خيرًا لكم وإن لم تدركوه الآن؛ فجاء ﴿وهو خير لكم﴾. أما النساء فربط الخير بجعل الله؛ لأن الصبر على الزوجة المكروهة امتثالًا لأمر حسن المعاشرة سبب يجعل الله عاقبته خيرًا كثيرًا، جزاءً على الصبر والامتثال. وزيادة ﴿كثيرًا﴾ تفتح أمام الزوج أبواب خير متعددة لا يراها ساعة الكراهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص755، تحت النساء: 19، في المقارنة بالبقرة: 216.","url":""}]},{"id":"s2-1072","number":1072,"surah":2,"verses":[216],"verseLabel":"البقرة: 216","question":"ما سرّ التعبير في قوله تعالى: ﴿كُتِبَ عَلَيْكُمُ الْقِتَالُ﴾ بعد الكلام عن الإنفاق؟","answer":"لأن المال والنفس جناحا نصرة الجماعة، فبعد توجيه البذل ذكر التكليف الذي يحتاج إليه؛ كما أن الإنفاق يهيئ للقتال ويخفف آثاره. و﴿كتب﴾ تثبت الفرض فيما لا يكفي فيه الحماس العابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص364–368، تحت البقرة: 216، في المناسبة ودلالة الكتابة.","url":""}]},{"id":"s2-1073","number":1073,"surah":2,"verses":[216],"verseLabel":"البقرة: 216","question":"ما سرّ التعبير في قوله تعالى: ﴿وَهُوَ كُرْهٌ لَكُمْ﴾ بالمصدر لا «مكروه»؟","answer":"المصدر ﴿كره﴾ للمبالغة؛ كأن القتال نفس الكراهة والثقل على النفوس، لا مجرد أمر موصوف بأنه مكروه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص366–370، تحت البقرة: 216، في الإخبار بالمصدر.","url":""}]},{"id":"s2-1074","number":1074,"surah":2,"verses":[216],"verseLabel":"البقرة: 216","question":"ما دلالة تنكير ﴿شَيْئًا﴾ في جملتي الكراهة والمحبة؟","answer":"ليعم الحكم كل ما يكرهه أو يحبه الإنسان، لا القتال وحده؛ فتحولت الواقعة إلى قاعدة تربوية شاملة. وأدنى شيء قد تخفى عاقبته على صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص371–374، تحت البقرة: 216، في تنكير الشيء.","url":""}]},{"id":"s2-1075","number":1075,"surah":2,"verses":[216],"verseLabel":"البقرة: 216","question":"ما سرّ مقابلة الكراهة بالخير والمحبة بالشر، دون «النفع والضر»؟","answer":"الخير والشر أوسع من المنفعة الحسية؛ يشملان الدين والعاقبة والأخلاق والثواب، بينما قد تكون اللذة نافعة ظاهرًا فاسدة المآل. المقابلة تصحح ميزان الحكم لا مجرد حساب المصلحة العاجلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص372–375، تحت البقرة: 216، في المقابلة والاحتباك.","url":""}]},{"id":"s2-1076","number":1076,"surah":2,"verses":[216],"verseLabel":"البقرة: 216","question":"ما سرّ تقديم المكروه الذي فيه خير على المحبوب الذي فيه شر؟","answer":"لأنه متصل مباشرة بالقتال الموصوف بالكراهة، ولأن المقام يريد أولًا تسلية المكلف وحمله على الامتثال؛ ثم أكمل القاعدة بالجانب المقابل. فبدأ بعلاج الشعور الحاضر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص373–376، تحت البقرة: 216، في ترتيب المقابلة.","url":""}]},{"id":"s2-1077","number":1077,"surah":2,"verses":[216],"verseLabel":"البقرة: 216","question":"ما دلالة حذف مفعول العلم في قوله تعالى: ﴿وَاللَّهُ يَعْلَمُ وَأَنْتُمْ لَا تَعْلَمُونَ﴾؟","answer":"حذف المفعولين ليعم علمه بكل العواقب والمصالح وخفاء ذلك عن البشر؛ فالفارق ليس معلومة واحدة بل إحاطة كاملة مقابل قصور كامل. والاسم الظاهر يثبت مصدر التشريع، والخطاب يواجه ثقة النفس بحكمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص374–378، تحت البقرة: 216، في إيجاز الحذف.","url":""}]},{"id":"s2-1078","number":1078,"surah":2,"verses":[217],"verseLabel":"البقرة: 217","question":"ما سرّ ترتيب السؤال: ﴿يَسْأَلُونَكَ عَنِ الشَّهْرِ الْحَرَامِ قِتَالٍ فِيهِ﴾؟","answer":"قدم الشهر الحرام لأنه موضع اهتمام السائلين، ثم جاء ﴿قتال فيه﴾ بدل اشتمال أو بيانًا للمسؤول عنه؛ فبرزت حرمة الزمن قبل الفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص383–384، تحت البقرة: 217.","url":""}]},{"id":"s2-1079","number":1079,"surah":2,"verses":[217],"verseLabel":"البقرة: 217","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن يرتدد﴾ بفك الإدغام، لا: يرتد؟","answer":"الفك هو الأصل ويعطي اللفظ امتدادًا يلائم تصوير الرجوع المتدرج والثبات عليه حتى الموت، مع جواز الإدغام في العربية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص393، تحت البقرة: 217.","url":""}]},{"id":"s2-1080","number":1080,"surah":2,"verses":[217],"verseLabel":"البقرة: 217","question":"ما سرّ مجيء الجواب: ﴿قُلْ قِتَالٌ فِيهِ كَبِيرٌ﴾ دون نفي حرمة القتال؟","answer":"أقر بأن القتال فيه كبير ولم ينف الحرمة؛ ثم وازن بينه وبين جرائم المشركين الأكبر: الصد والكفر والإخراج والفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص382–386، تحت البقرة: 217، في تنكير القتال ووصفه.","url":""}]},{"id":"s2-1081","number":1081,"surah":2,"verses":[217],"verseLabel":"البقرة: 217","question":"ما سرّ تعداد قوله تعالى: ﴿وَصَدٌّ عَنْ سَبِيلِ اللَّهِ وَكُفْرٌ بِهِ وَالْمَسْجِدِ الْحَرَامِ﴾ بعد الإقرار بكبر القتال؟","answer":"ليبين أن خصومهم اقتطعوا حادثة القتال وأخفوا منظومة جرائمهم: الصد والكفر وانتهاك المسجد والإخراج. وتراكم المصادر يضع الأفعال على ميزان واحد ويكشف الأكبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص384–389، تحت البقرة: 217، في تعداد الجرائم والعطف.","url":""}]},{"id":"s2-1082","number":1082,"surah":2,"verses":[217],"verseLabel":"البقرة: 217","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِخْرَاجُ أَهْلِهِ مِنْهُ أَكْبَرُ عِنْدَ اللَّهِ﴾؟","answer":"لأن إخراج أهل المسجد المؤمنين اعتداء مستمر على الدين والحرمة والجماعة، لا واقعة قتال محدودة؛ وميزان ﴿عند الله﴾ يصحح الموازين الدعائية عند الناس. وصيغة التفضيل لا تهون الأول بل تبين تفاوت الجرم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص387–391، تحت البقرة: 217، في التفضيل.","url":""}]},{"id":"s2-1083","number":1083,"surah":2,"verses":[217],"verseLabel":"البقرة: 217","question":"ما سرّ التعبير هنا بـ﴿وَالْفِتْنَةُ أَكْبَرُ مِنَ الْقَتْلِ﴾ بعد التعبير سابقًا بـ﴿أَشَدُّ مِنَ الْقَتْلِ﴾؟","answer":"﴿أشد﴾ في الموضع الأول تلحظ قوة الألم والضرر، و﴿أكبر﴾ هنا تلحظ عظم الجرم عند الله بعد تعداد الصد والكفر والإخراج؛ فلكل وصف جهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص389–393، تحت البقرة: 217، في مناسبة ﴿أكبر﴾.","url":""}]},{"id":"s2-1084","number":1084,"surah":2,"verses":[217],"verseLabel":"البقرة: 217","question":"ما مناسبة الاعتراض بقوله تعالى: ﴿وَلَا يَزَالُونَ يُقَاتِلُونَكُمْ﴾؟","answer":"لينقل الكلام من حادثة ماضية إلى خطر مستمر: جدلهم عن الشهر ليس حرصًا على الحرمة، بل جزء من حرب لا تنقطع حتى يردوا المؤمنين. والمضارع مع ﴿لا يزالون﴾ يصور الإصرار المتجدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص391–395، تحت البقرة: 217، في الالتفات والاعتراض.","url":""}]},{"id":"s2-1085","number":1085,"surah":2,"verses":[217],"verseLabel":"البقرة: 217","question":"ما سرّ التعبير في قوله تعالى: ﴿حَتَّى يَرُدُّوكُمْ عَنْ دِينِكُمْ إِنِ اسْتَطَاعُوا﴾؟","answer":"كشف الغاية القصوى لقتالهم: ليست أرضًا أو مالًا فقط، بل رد المؤمن عن دينه؛ ثم قيدها بـ﴿إن استطاعوا﴾ لتحقير قدرتهم وتثبيت المؤمنين مع التحذير من محاولتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص393–396، تحت البقرة: 217، في الغاية والشرط.","url":""}]},{"id":"s2-1086","number":1086,"surah":2,"verses":[217],"verseLabel":"البقرة: 217","question":"ما سرّ التعبير في قوله تعالى: ﴿فَيَمُتْ وَهُوَ كَافِرٌ﴾؛ أليست الردة وحدها كافية؟","answer":"لأن حبوط العمل والخلود المذكورين مترتبان على الثبات على الكفر حتى الموت، أما من رجع وتاب فبابه مفتوح. والحال تؤكد أن العبرة بالخاتمة لا بلحظة زلل أعقبها إصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص394–397، تحت البقرة: 217، في الفاء والحال.","url":""}]},{"id":"s2-1087","number":1087,"surah":2,"verses":[217],"verseLabel":"البقرة: 217","question":"ما دلالة تكرار اسم الإشارة في قوله تعالى: ﴿فَأُولَئِكَ حَبِطَتْ أَعْمَالُهُمْ... وَأُولَئِكَ أَصْحَابُ النَّارِ﴾؟","answer":"لأن لكل نتيجة فظاعتها: ضياع العمل في الدارين، ثم ملازمة النار والخلود؛ فأعيدت الإشارة ليستقل الوعيدان. والبعد في ﴿أولئك﴾ يناسب سقوط منزلتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص396–399، تحت البقرة: 217، في تكرار الإشارة.","url":""}]},{"id":"s2-1088","number":1088,"surah":2,"verses":[218],"verseLabel":"البقرة: 218","question":"ما سرّ الجمع بين الإيمان والهجرة والجهاد؟","answer":"الإيمان أصل باطن، والهجرة تضحية بالمكان والمألوف، والجهاد بذل للطاقة والنفس؛ فترقى من الاعتقاد إلى مفارقة ثم مواجهة. واجتماعها يثبت صدق الرجاء بالعمل لا بالدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص400–402، تحت البقرة: 218، في ترتيب الصفات.","url":""}]},{"id":"s2-1089","number":1089,"surah":2,"verses":[218],"verseLabel":"البقرة: 218","question":"ما سرّ التعبير في قوله تعالى: ﴿أُولَئِكَ يَرْجُونَ رَحْمَتَ اللَّهِ﴾، ولم يجزم لهم بها؟","answer":"الرجاء يجمع حسن الظن مع الخوف والعمل، فلا يغترون بأعمالهم ولا يجزمون لأنفسهم؛ بل يظلون متعلقين بفضل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص401–404، تحت البقرة: 218، في اسم الإشارة والرجاء.","url":""}]},{"id":"s2-1090","number":1090,"surah":2,"verses":[218],"verseLabel":"البقرة: 218","question":"ما سرّ التعبير بـ﴿رَحْمَتَ اللَّهِ﴾ بدل «ثواب الله»؟","answer":"الرحمة أوسع من الثواب؛ فهي تشمل المغفرة والقبول والنصر والجنة، وتبين أن الجزاء فضل من الله لا مجرد معاوضة على العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص402–404، تحت البقرة: 218، في اختيار الرحمة.","url":""}]},{"id":"s2-1091","number":1091,"surah":2,"verses":[218],"verseLabel":"البقرة: 218","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَاللَّهُ غَفُورٌ رَحِيمٌ﴾؟","answer":"المغفرة تستر ما قد يقع من تقصير في طريق الهجرة والجهاد، والرحمة تمنحهم ما يرجونه؛ فالفاصلة تجيب رجاءهم بالاسمين الموافقين. والجملة الاسمية تثبت دوام الصفتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص403–405، تحت البقرة: 218، في مناسبة الخاتمة.","url":""}]},{"id":"s2-1092","number":1092,"surah":2,"verses":[219],"verseLabel":"البقرة: 219","question":"ما سرّ التعبير في قوله تعالى في الخمر والميسر ﴿فيهما إثم كبير ومنافع للناس﴾، فاعترف بالمنافع؟","answer":"ذكر المنافع إنصافًا وتهيئة للموازنة، ثم قرر أن الإثم أكبر منها؛ فليس التحريم مبنيًا على إنكار الواقع، بل على غلبة المفسدة على المنفعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص409–414، تحت البقرة: 219.","url":""}]},{"id":"s2-1093","number":1093,"surah":2,"verses":[219],"verseLabel":"البقرة: 219","question":"ما مناسبة عطف سؤال الإنفاق على سؤال الخمر والميسر؟","answer":"يجمع السؤالين شأن المال: الميسر أكل مال بالباطل، والإنفاق بذل للمال في الخير. فانتقل من طريق فاسد لاكتسابه إلى طريق صالح لإنفاقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص413، تحت البقرة: 219.","url":""}]},{"id":"s2-1094","number":1094,"surah":2,"verses":[219],"verseLabel":"البقرة: 219","question":"ما سرّ الجمع بين الخمر والميسر في السؤال عنهما؟","answer":"قرن بينهما لاشتراكهما في إفساد العقل والمال وإثارة العداوة والصد عن ذكر الله، ولأنهما كانا متلازمين في مجالس العرب ومعاشهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص406–409، تحت البقرة: 219، في سر الاقتران.","url":""}]},{"id":"s2-1095","number":1095,"surah":2,"verses":[219],"verseLabel":"البقرة: 219","question":"ما سرّ تقديم قوله تعالى: ﴿فِيهِمَا إِثْمٌ كَبِيرٌ﴾ على ذكر المنافع؟","answer":"قدم الإثم لأنه المقصود بالحكم والتحذير، ثم ذكر المنافع إنصافًا وتهيئة للموازنة التي انتهت إلى غلبة الإثم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص408–411، تحت البقرة: 219، في تقديم الإثم.","url":""}]},{"id":"s2-1096","number":1096,"surah":2,"verses":[219],"verseLabel":"البقرة: 219","question":"ما سرّ إفراد ﴿إِثْمُهُمَا﴾ وجمع ﴿مَنَافِعُهُمَا﴾؟","answer":"أفرد الإثم باعتبار جنسه أو لاجتماع آثاره في مفسدة كبرى، وجمع المنافع لتعدد صورها من ربح ولذة ومكاسب عارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص410–413، تحت البقرة: 219، في الإفراد والجمع.","url":""}]},{"id":"s2-1097","number":1097,"surah":2,"verses":[219],"verseLabel":"البقرة: 219","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِثْمُهُمَا أَكْبَرُ مِنْ نَفْعِهِمَا﴾، دون أن يقال: «لا نفع فيهما»؟","answer":"قرر ميزان الترجيح: قد توجد منفعة لكنها لا تبرر ما هو أكبر منها ضررًا؛ وهذا يمهد للتدرج في التحريم ويعلم النظر في المآلات. والمفرد ﴿نفعهما﴾ يجمع كل المنافع في كفة واحدة فلا تغلب الإثم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص411–414، تحت البقرة: 219، في المقارنة بصيغة التفضيل.","url":""}]},{"id":"s2-1098","number":1098,"surah":2,"verses":[219],"verseLabel":"البقرة: 219","question":"ما سرّ الجواب بقوله تعالى: ﴿قُلِ الْعَفْوَ﴾ عن سؤالهم: ﴿مَاذَا يُنْفِقُونَ﴾؟","answer":"العفو هو الفاضل السهل الذي يزيد عن الحاجة من غير إجحاف بالنفس والعيال؛ فحدد الجواب القدر المعتدل للإنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص413–416، تحت البقرة: 219، في معنى العفو ومناسبة الجواب.","url":""}]},{"id":"s2-1099","number":1099,"surah":2,"verses":[219],"verseLabel":"البقرة: 219","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿كَذَلِكَ يُبَيِّنُ اللَّهُ لَكُمُ الْآيَاتِ لَعَلَّكُمْ تَتَفَكَّرُونَ﴾؟","answer":"كما بين ميزان الخمر والإنفاق يبين سائر الأحكام لتعمل العقول في العواقب، لا لتتلقى أوامر بلا فهم؛ والتفكر يعبر من الدنيا إلى الآخرة كما تكمل الآية التالية. والإشارة تجمع طريقة البيان المتدرج المقنع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص415–416، تحت البقرة: 219، في التشبيه وغاية التفكر.","url":""}]},{"id":"s2-1100","number":1100,"surah":2,"verses":[220],"verseLabel":"البقرة: 220","question":"ما سرّ التعبير في قوله تعالى في اليتامى ﴿إصلاح لهم خير﴾، دون أن يقال: إصلاحهم خير؟","answer":"اللام في ﴿لهم﴾ تجعل الإصلاح واقعًا لمصلحتهم ونفعهم، أما «إصلاحهم» فقد يوهم أن اليتامى أنفسهم محل الإصلاح لا أموالهم وشؤونهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص427، تحت البقرة: 220.","url":""}]},{"id":"s2-1101","number":1101,"surah":2,"verses":[220],"verseLabel":"البقرة: 220","question":"ما سرّ التعبير عن مخالطة اليتامى بصيغة المفاعلة؟","answer":"لأنها مشاركة متبادلة في الطعام والسكن والمال، لا فعل من طرف واحد؛ وصيغة المفاعلة تصور الحياة المشتركة التي تضبطها الأخوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص429، تحت البقرة: 220.","url":""}]},{"id":"s2-1102","number":1102,"surah":2,"verses":[220],"verseLabel":"البقرة: 220","question":"ما دلالة حذف مفعول المشيئة في قوله تعالى: ﴿وَلَوْ شَاءَ اللَّهُ لَأَعْنَتَكُمْ﴾؟","answer":"حذف متعلق المشيئة ليعم: لو شاء أن يشدد في شأن مخالطتهم وأموالهم لأوقعكم في العنت؛ فالحذف يوسع صور المشقة التي رفعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص434، تحت البقرة: 220.","url":""}]},{"id":"s2-1103","number":1103,"surah":2,"verses":[220],"verseLabel":"البقرة: 220","question":"ما سرّ مجيء ﴿فِي الدُّنْيَا وَالْآخِرَةِ﴾ في أول الآية مع تعلقها بالتفكر قبلها؟","answer":"وصلها بما قبلها ليكون التفكر في مصالح الدارين معًا؛ فلا يحكم الإنسان على الخمر والإنفاق واليتامى بمعيار عاجل فقط. وموقعها بين الآيتين يجسر من قاعدة التفكير إلى تطبيق جديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص417–420، تحت البقرة: 220، في ارتباط المطلع بما قبله.","url":""}]},{"id":"s2-1104","number":1104,"surah":2,"verses":[220],"verseLabel":"البقرة: 220","question":"ما سرّ تكرار ﴿وَيَسْأَلُونَكَ عَنِ الْيَتَامَى﴾ بعد سؤالي الخمر والإنفاق؟","answer":"تتوالى الأسئلة لتكشف حاجتهم إلى بيان ينظم المال والمجتمع، وسؤال اليتامى نشأ من الخوف من مخالطة أموالهم بعد الوعيد. والمضارع يصور تجدد السؤال عند نزول الأحكام.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص419–422، تحت البقرة: 220، في تكرار صيغة السؤال.","url":""}]},{"id":"s2-1105","number":1105,"surah":2,"verses":[220],"verseLabel":"البقرة: 220","question":"ما سرّ إجمال الجواب بقوله تعالى: ﴿قُلْ إِصْلَاحٌ لَهُمْ خَيْرٌ﴾ دون تفصيل صور التصرف؟","answer":"أعطى معيارًا جامعًا هو الإصلاح؛ لأن صور التصرف تتغير باختلاف الأحوال، والعبرة بأن يكون العمل محققًا لمصلحة اليتيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص421–424، تحت البقرة: 220، في الإيجاز والتنكير.","url":""}]},{"id":"s2-1106","number":1106,"surah":2,"verses":[220],"verseLabel":"البقرة: 220","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنْ تُخَالِطُوهُمْ فَإِخْوَانُكُمْ﴾؟","answer":"المخالطة جائزة إذا قامت على الأخوة؛ فأنتم وإياهم أسرة إيمانية، لا أصحاب أموال منفصلة يعاملون بالحرج أو الاستغلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص423–427، تحت البقرة: 220، في الشرط والتعبير بالأخوة.","url":""}]},{"id":"s2-1107","number":1107,"surah":2,"verses":[220],"verseLabel":"البقرة: 220","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِخْوَانُكُمْ﴾، دون أن يقال: «فلا جناح عليكم»؟","answer":"قوله ﴿فإخوانكم﴾ أرفع من مجرد نفي الجناح؛ إذ يثبت رابطة توجب النصيحة والرعاية والمساواة، لا مجرد إباحة المخالطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص424–428، تحت البقرة: 220، في العدول إلى وصف الأخوة.","url":""}]},{"id":"s2-1108","number":1108,"surah":2,"verses":[220],"verseLabel":"البقرة: 220","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاللَّهُ يَعْلَمُ الْمُفْسِدَ مِنَ الْمُصْلِحِ﴾؟","answer":"لأن المخالطة الواحدة قد تتشابه ظاهرًا ويختلف قصدها: واحد يمزج المال لمصلحة اليتيم وآخر ليأكله؛ فلا يخدع الشكل علم الله. وتقديم المفسد للتحذير في مقام الخوف من التعدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص426–430، تحت البقرة: 220، في الطباق والعلم بالنيات.","url":""}]},{"id":"s2-1109","number":1109,"surah":2,"verses":[220],"verseLabel":"البقرة: 220","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَلَوْ شَاءَ اللَّهُ لَأَعْنَتَكُمْ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ﴾؟","answer":"ذكّرهم أن الله قادر على التشديد لكنه خفف بحكمته؛ فهو عزيز لا يعجزه الإعنات، حكيم يضع التيسير موضعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص429–435، تحت البقرة: 220، في الشرط ومناسبة الاسمين.","url":""}]},{"id":"s2-1110","number":1110,"surah":2,"verses":[221],"verseLabel":"البقرة: 221","question":"ما سرّ التعبير في قوله تعالى: ﴿ولأمة مؤمنة خير من مشركة ولو أعجبتكم﴾؟","answer":"قلب ميزان الجمال والحرية والمكانة: أدنى مؤمنة اجتماعيًا خير من مشركة بالغة الإعجاب، لأن العقيدة تحفظ البيت والمصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص436–450، تحت البقرة: 221.","url":""}]},{"id":"s2-1111","number":1111,"surah":2,"verses":[221],"verseLabel":"البقرة: 221","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى يؤمن﴾ بـ﴿حتى﴾ لا ﴿إلى أن﴾؟","answer":"﴿حتى﴾ تجعل الإيمان غاية ينتهي عند تحققها المنع، وتوحي بأن تبدل العقيدة انتقال حقيقي لا مرور زمن فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص443، تحت البقرة: 221.","url":""}]},{"id":"s2-1112","number":1112,"surah":2,"verses":[221],"verseLabel":"البقرة: 221","question":"ما دلالة تقديم اسم الله في قوله تعالى: ﴿وَاللَّهُ يَدْعُو إِلَى الْجَنَّةِ وَالْمَغْفِرَةِ﴾؟","answer":"ليقابل المشركين أنفسهم بـالله: ﴿أولئك يدعون إلى النار والله يدعو﴾، فيظهر الفرق بين مصدر الدعوتين قبل ذكر الغايتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص450، تحت البقرة: 221.","url":""}]},{"id":"s2-1113","number":1113,"surah":2,"verses":[221],"verseLabel":"البقرة: 221","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَأَمَةٌ مُؤْمِنَةٌ خَيْرٌ مِنْ مُشْرِكَةٍ﴾ مع أن المقارنة بين حرة وأمة؟","answer":"ليقلب ميزان الاختيار من المكانة الاجتماعية والجمال إلى الإيمان؛ فأدنى المؤمنات منزلة في عرف الناس خير من مشركة أعجبتهم. والمبالغة في الطرفين تجعل أولوية العقيدة أوضح.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص436–442، تحت البقرة: 221، في المقابلة والتفضيل.","url":""}]},{"id":"s2-1114","number":1114,"surah":2,"verses":[221],"verseLabel":"البقرة: 221","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَوْ أَعْجَبَتْكُمْ﴾؟","answer":"لأن الإعجاب هو المدخل الأقوى الذي قد يغطي على اختلاف العقيدة؛ فجاء الشرط مستوعبًا أقصى دواعي الرغبة ليقرر أن البريق العاجل لا يساوي سلامة البيت والدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص439–444، تحت البقرة: 221، في الشرط والمبالغة.","url":""}]},{"id":"s2-1115","number":1115,"surah":2,"verses":[221],"verseLabel":"البقرة: 221","question":"ما سرّ اختلاف البناء بين ﴿لَا تَنْكِحُوا الْمُشْرِكَاتِ﴾ و﴿لَا تُنْكِحُوا الْمُشْرِكِينَ﴾؟","answer":"الأول نهي الرجال عن الزواج، والثاني نهي الأولياء عن تزويج المؤمنات؛ فغيّر الفعل من الثلاثي إلى الرباعي لأن جهة التصرف تغيرت. وبذلك شمل الحكم طرفي الأسرة بعبارة دقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص436–446، تحت البقرة: 221، في اختلاف الصيغتين.","url":""}]},{"id":"s2-1116","number":1116,"surah":2,"verses":[221],"verseLabel":"البقرة: 221","question":"ما سرّ التعبير في قوله تعالى في الرجل: ﴿وَلَعَبْدٌ مُؤْمِنٌ خَيْرٌ مِنْ مُشْرِكٍ﴾؟","answer":"كرر المعيار نفسه حتى لا يظن أن الاعتبار الديني مطلوب في الزوجة وحدها؛ فعبد مؤمن خير من حر مشرك مهما أعجب الولي أو المرأة. والتوازي يثبت وحدة المقياس مع اختلاف المخاطب.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص443–447، تحت البقرة: 221، في الموازنة بين الشطرين.","url":""}]},{"id":"s2-1117","number":1117,"surah":2,"verses":[221],"verseLabel":"البقرة: 221","question":"ما سرّ التعبير في قوله تعالى عن المشركين: ﴿أُولَئِكَ يَدْعُونَ إِلَى النَّارِ﴾؟","answer":"أشار إليهم باسم البعيد إبعادًا لطريقهم، وجعل أثر الزواج بهم دعوة إلى النار لأن المخالطة والمودة تنقل الاعتقاد والسلوك إلى الأسرة والذرية؛ فالخطر أبعد من الشخصين.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص446–451، تحت البقرة: 221، في اسم الإشارة والاستعارة.","url":""}]},{"id":"s2-1118","number":1118,"surah":2,"verses":[221],"verseLabel":"البقرة: 221","question":"ما سرّ مقابلة دعوة المشركين بقوله تعالى: ﴿وَاللَّهُ يَدْعُو إِلَى الْجَنَّةِ وَالْمَغْفِرَةِ﴾؟","answer":"وضع نهايتي الطريقين وجهًا لوجه: زواج يجر إلى النار، وأمر إلهي يقود إلى الجنة والمغفرة. وذكر المغفرة قبل دخول الجنة معنىً؛ إذ لا وصول إلى النعيم إلا بعد تطهير الذنب.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص448–453، تحت البقرة: 221، في المقابلة وترتيب الغايتين.","url":""}]},{"id":"s2-1119","number":1119,"surah":2,"verses":[221],"verseLabel":"البقرة: 221","question":"ما دلالة قوله تعالى: ﴿بِإِذْنِهِ﴾، ومناسبة الختم بـ﴿لَعَلَّهُمْ يَتَذَكَّرُونَ﴾؟","answer":"ليبين أن الهداية والجنة ليستا بمجرد التمني بل بتوفيق الله وشرعه، وأن تفصيل الحكم موعظة توقظ ما تعرفه الفطرة من تقديم العاقبة على الإعجاب العابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص452–457، تحت البقرة: 221، في القيد والخاتمة.","url":""}]},{"id":"s2-1120","number":1120,"surah":2,"verses":[222],"verseLabel":"البقرة: 222","question":"ما سرّ وصف المحيض بأنه ﴿أَذًى﴾ دون «مرض» أو «نجاسة»؟","answer":"الأذى أعم من المرض والنجاسة، ويصف الضرر والمشقة الملازمين للحال من غير أن يجعل المرأة نفسها موضع تنفير.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص458–481، تحت البقرة: 222.","url":""}]},{"id":"s2-1121","number":1121,"surah":2,"verses":[222],"verseLabel":"البقرة: 222","question":"ما سرّ التعبير في قوله تعالى: ﴿فاعتزلوا النساء في المحيض﴾ لا: زمن المحيض؟","answer":"﴿في﴾ تحتمل الزمان والموضع، فتقيد الاعتزال بحالة الحيض ومحل الأذى، ولا تجعله هجرًا للمرأة في حياتها كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص458–481، تحت البقرة: 222.","url":""}]},{"id":"s2-1122","number":1122,"surah":2,"verses":[222],"verseLabel":"البقرة: 222","question":"ما سرّ توجيه جواب سؤال المحيض إلى بيان أنه ﴿أَذًى﴾؟","answer":"وجه الجواب إلى علة الحكم التي يحتاجون إليها: المحيض أذى، ولذلك شرع اعتزال موضعه؛ فلم يكن المقصود وصفًا طبيًا مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص458–463، تحت البقرة: 222، في معنى المحيض والأذى.","url":""}]},{"id":"s2-1123","number":1123,"surah":2,"verses":[222],"verseLabel":"البقرة: 222","question":"ما سرّ التعبير في قوله تعالى: ﴿فَاعْتَزِلُوا النِّسَاءَ فِي الْمَحِيضِ﴾، دون أن يقال: «فاعتزلوا النساء» فقط؟","answer":"قيد الاعتزال بموضع الحيض وزمنه، فلا يفهم منه هجر المرأة في المعيشة والمجالسة. والجار والمجرور يرد الاعتزال إلى الفعل المؤذي لا إلى المرأة كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص461–466، تحت البقرة: 222، في التقييد.","url":""}]},{"id":"s2-1124","number":1124,"surah":2,"verses":[222],"verseLabel":"البقرة: 222","question":"ما سرّ إتباع الاعتزال بقوله تعالى: ﴿وَلَا تَقْرَبُوهُنَّ﴾؟","answer":"الاعتزال قد يفهم على وجه مجمل، فجاء ﴿ولا تقربوهن﴾ لتأكيد منع الجماع ومقدماته في موضع الحيض.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص464–468، تحت البقرة: 222، في الكناية والتوكيد.","url":""}]},{"id":"s2-1125","number":1125,"surah":2,"verses":[222],"verseLabel":"البقرة: 222","question":"ما سرّ اختلاف التعبير بين ﴿حَتَّى يَطْهُرْنَ﴾ و﴿فَإِذَا تَطَهَّرْنَ﴾؟","answer":"﴿يطهرن﴾ يدل على انقطاع دم الحيض، و﴿تطهرن﴾ يدل على فعل التطهر بالغسل؛ فجمع بين زوال الأذى وحصول الطهارة الشرعية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص466–472، تحت البقرة: 222، في اختلاف ﴿يطهرن﴾ و﴿تطهرن﴾.","url":""}]},{"id":"s2-1126","number":1126,"surah":2,"verses":[222],"verseLabel":"البقرة: 222","question":"ما سرّ التعبير في قوله تعالى: ﴿فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ اللَّهُ﴾؟","answer":"أباح المعاشرة بعد الطهر لكنه أبقاها في الحد الذي شرعه الله، فليست الإباحة مطلقة في كل موضع أو كيفية. والتعبير يربط أخص شؤون الحياة بأمر الله لا بمجرد الشهوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص470–475، تحت البقرة: 222، في القيد ومناسبة الأمر.","url":""}]},{"id":"s2-1127","number":1127,"surah":2,"verses":[222],"verseLabel":"البقرة: 222","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ اللَّهَ يُحِبُّ التَّوَّابِينَ﴾ في سياق أحكام الحيض؟","answer":"لأن من تجاوز الحد يحتاج إلى رجوع، ولأن الطاعة نفسها تجدد رجوع العبد إلى أمر ربه. وصيغة ﴿التوابين﴾ تدل على تكرر التوبة فلا يغلق الخطاب باب الإصلاح بعد الخطأ.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص474–478، تحت البقرة: 222، في مناسبة التوابين.","url":""}]},{"id":"s2-1128","number":1128,"surah":2,"verses":[222],"verseLabel":"البقرة: 222","question":"ما سرّ الجمع بين ﴿التَّوَّابِينَ﴾ و﴿الْمُتَطَهِّرِينَ﴾؟","answer":"التوبة طهارة الباطن من الذنب، والتطهر طهارة الظاهر من الأذى؛ فجمع الاسمان كمال النظافة الحسية والمعنوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص476–480، تحت البقرة: 222، في الجمع وتكرار الفعل.","url":""}]},{"id":"s2-1129","number":1129,"surah":2,"verses":[223],"verseLabel":"البقرة: 223","question":"ما سرّ التعبير في قوله تعالى: ﴿فأتوا حرثكم أنى شئتم﴾ لا: كيف شئتم؟","answer":"﴿أنى﴾ أوسع في الهيئات والأزمنة المباحة، لكن لفظ ﴿حرثكم﴾ يقيدها بموضع الحرث؛ فالتوسعة داخل الحد لا خارجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص481–499، تحت البقرة: 223.","url":""}]},{"id":"s2-1130","number":1130,"surah":2,"verses":[223],"verseLabel":"البقرة: 223","question":"ما سرّ تشبيه النساء بالحرث في قوله تعالى: ﴿نِسَاؤُكُمْ حَرْثٌ لَكُمْ﴾؟","answer":"الحرث موضع الإنبات والنسل، فشبه به موضع الولد من المرأة؛ وفي التشبيه توجيه إلى مقصد العلاقة وموضعها المشروع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص481–486، تحت البقرة: 223، في تشبيه الحرث.","url":""}]},{"id":"s2-1131","number":1131,"surah":2,"verses":[223],"verseLabel":"البقرة: 223","question":"ما دلالة إعادة لفظ ﴿حَرْثَكُمْ﴾ في قوله تعالى: ﴿فَأْتُوا حَرْثَكُمْ﴾؟","answer":"إعادة اللفظ تقيد الإباحة بالموضع الذي يتحقق فيه معنى الحرث والإنجاب؛ فلا تُفهم ﴿أنى شئتم﴾ إذنًا في غيره. والتكرار يثبت الصورة التي عليها مدار الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص484–489، تحت البقرة: 223، في التكرار والتقييد.","url":""}]},{"id":"s2-1132","number":1132,"surah":2,"verses":[223],"verseLabel":"البقرة: 223","question":"ما وجه قوله تعالى: ﴿أَنَّى شِئْتُمْ﴾ مع وجود حدود للمعاشرة؟","answer":"﴿أنى﴾ تحتمل كيف ومن أين، والمراد تنوع الهيئة والجهة ما دام الإتيان في موضع الحرث المشروع؛ فلا ترفع القيود المبينة في السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص486–491، تحت البقرة: 223، في دلالة ﴿أنى﴾.","url":""}]},{"id":"s2-1133","number":1133,"surah":2,"verses":[223],"verseLabel":"البقرة: 223","question":"ما مناسبة الانتقال من المعاشرة إلى قوله تعالى: ﴿وَقَدِّمُوا لِأَنْفُسِكُمْ﴾؟","answer":"أي قدموا لأنفسكم العمل الصالح والتقوى، وقيل التسمية والدعاء وطلب الولد؛ فنقل الإباحة من مجرد الشهوة إلى مسؤولية وآثار باقية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص489–494، تحت البقرة: 223، في الانتقال والأمر.","url":""}]},{"id":"s2-1134","number":1134,"surah":2,"verses":[223],"verseLabel":"البقرة: 223","question":"ما مناسبة إتباع الإباحة بقوله تعالى: ﴿وَاتَّقُوا اللَّهَ وَاعْلَمُوا أَنَّكُمْ مُلَاقُوهُ﴾؟","answer":"لأن الخلوة قد توهم غياب الرقابة، فاستحضر التقوى واللقاء ليضبطا استعمال المباح وحدوده. و﴿اعلموا﴾ تنقل حقيقة الآخرة إلى يقين حاضر يراقب به الإنسان نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص492–496، تحت البقرة: 223، في مناسبة التقوى واللقاء.","url":""}]},{"id":"s2-1135","number":1135,"surah":2,"verses":[223],"verseLabel":"البقرة: 223","question":"ما مناسبة ختم الأحكام الأسرية بقوله تعالى: ﴿وَبَشِّرِ الْمُؤْمِنِينَ﴾؟","answer":"لأن من امتثل الحدود الخفية في علاقته الخاصة دل على صدق إيمانه، فاستحق البشارة. وحذف المبشر به يعم خير الدنيا والآخرة ويترك النفس متطلعة إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص495–498، تحت البقرة: 223، في الحذف والخاتمة.","url":""}]},{"id":"s2-1136","number":1136,"surah":2,"verses":[224],"verseLabel":"البقرة: 224","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تجعلوا الله عرضة لأيمانكم﴾؟ وكيف يكون اسم الله عُرضة؟","answer":"العُرضة ما يجعل حاجزًا أو معرضًا للشيء؛ فالمعنى لا تجعلوا الحلف باسم الله مانعًا تتذرعون به لترك البر والتقوى والإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص499–512، تحت البقرة: 224.","url":""}]},{"id":"s2-1137","number":1137,"surah":2,"verses":[224],"verseLabel":"البقرة: 224","question":"ما دلالة إضافة الأيمان إليهم في قوله تعالى: ﴿لِأَيْمَانِكُمْ﴾؟","answer":"ليحمّلهم مسؤولية ما أنشأته ألسنتهم؛ فالحلف فعلهم ولا يجوز أن ينسبوا ما ترتب عليه إلى أمر الله. والإضافة تميز اليمين البشرية من الحكم الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص501–505، تحت البقرة: 224، في الإضافة.","url":""}]},{"id":"s2-1138","number":1138,"surah":2,"verses":[224],"verseLabel":"البقرة: 224","question":"ما وجه قوله تعالى: ﴿أَنْ تَبَرُّوا وَتَتَّقُوا﴾ مع النهي عن جعل الله عرضة للأيمان؟","answer":"أي لا تجعلوا أيمانكم بالله مانعًا من أن تبروا وتتقوا وتصلحوا؛ فالمصدر المؤول متعلق بالنهي وبيان لما ينبغي ألا يحجبه الحلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص502–507، تحت البقرة: 224، في تعلق المصدر المؤول.","url":""}]},{"id":"s2-1139","number":1139,"surah":2,"verses":[224],"verseLabel":"البقرة: 224","question":"ما سرّ ترتيب البر والتقوى والإصلاح بين الناس؟","answer":"بدأ بالخير العام، ثم بحاجز التقوى الذي يمنع الشر، ثم بأثرهما الاجتماعي في إصلاح الخصومات؛ فانتقل من بناء النفس إلى ترميم المجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص505–509، تحت البقرة: 224، في ترتيب المعطوفات.","url":""}]},{"id":"s2-1140","number":1140,"surah":2,"verses":[224],"verseLabel":"البقرة: 224","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَاللَّهُ سَمِيعٌ عَلِيمٌ﴾؟","answer":"اليمين قول يسمعه الله، والنية التي وراءها سر يعلمه؛ فجمع الاسمان ظاهر الحلف وباطنه. والخاتمة تمنع الاحتيال بعبارات تبدو خيرًا وقصدها غير ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص508–511، تحت البقرة: 224، في مناسبة الاسمين.","url":""}]},{"id":"s2-1141","number":1141,"surah":2,"verses":[225],"verseLabel":"البقرة: 225","question":"ما سرّ ختم حكم لغو الأيمان بـ﴿غَفُورٌ حَلِيمٌ﴾ دون ﴿غفور رحيم﴾؟","answer":"الغفور يناسب تجاوز لغو اليمين، والحليم يناسب عدم المعاجلة بالمؤاخذة على ما لم يعقده القلب؛ فالمقام عفو وإمهال لا مجرد رحمة عامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص521، تحت البقرة: 225.","url":""}]},{"id":"s2-1142","number":1142,"surah":2,"verses":[89],"verseLabel":"البقرة: 225، المائدة: 89","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة عن الأيمان: ﴿بِمَا كَسَبَتْ قُلُوبُكُمْ﴾، وقوله تعالى في المائدة: ﴿بِمَا عَقَّدْتُمُ الْأَيْمَانَ﴾؟","answer":"﴿كسبت قلوبكم﴾ في البقرة أعم من كل قصد وعزم باطني في اليمين، و﴿عقدتم الأيمان﴾ في المائدة أخص باليمين المؤكدة المعقودة التي تجب فيها الكفارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص576، تحت المائدة: 89، في المقارنة بالبقرة: 225.","url":""}]},{"id":"s2-1143","number":1143,"surah":2,"verses":[225],"verseLabel":"البقرة: 225","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ﴾؟","answer":"رفع المؤاخذة عما يجري بلا قصد عقد القلب، لأن التكليف يتعلق بالإرادة لا بمجرد صوت اللسان. وتعبير ﴿في أيمانكم﴾ يجعل اللغو واقعًا ضمن كلام القسم لا يمينًا مقصودة في ذاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص512–517، تحت البقرة: 225، في معنى اللغو.","url":""}]},{"id":"s2-1144","number":1144,"surah":2,"verses":[225],"verseLabel":"البقرة: 225","question":"ما سرّ مقابلة اللغو بقوله تعالى: ﴿بِمَا كَسَبَتْ قُلُوبُكُمْ﴾؟","answer":"اللغو ما يجري بلا قصد، فقابله بما تعمدته القلوب واكتسبته؛ فمحل المؤاخذة القصد لا مجرد حركة اللسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص515–519، تحت البقرة: 225، في إسناد الكسب إلى القلوب.","url":""}]},{"id":"s2-1145","number":1145,"surah":2,"verses":[225],"verseLabel":"البقرة: 225","question":"ما مناسبة ختم الآية بـ﴿غَفُورٌ حَلِيمٌ﴾ بدل ﴿سميع عليم﴾ المذكورة قبلها؟","answer":"بعد نفي المؤاخذة عن اللغو ناسبت المغفرة ما يقع من خلل، والحلم تأخير العقوبة وعدم العجلة على العبد؛ أما الآية السابقة فمقامها مراقبة القول والقصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص519–522، تحت البقرة: 225، في اختلاف الفاصلتين.","url":""}]},{"id":"s2-1146","number":1146,"surah":2,"verses":[226],"verseLabel":"البقرة: 226","question":"ما دلالة تقديم ﴿لِلَّذِينَ يُؤْلُونَ مِنْ نِسَائِهِمْ﴾ قبل ذكر الحكم؟","answer":"لتعيين أصحاب الحالة منذ البداية وربط المهلة بهم وحدهم، فلا تتوهم أنها عدة عامة. وتقديم الجار والمجرور يفيد الاختصاص ويثير انتظار ما قدر لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص523–526، تحت البقرة: 226، في التقديم.","url":""}]},{"id":"s2-1147","number":1147,"surah":2,"verses":[226],"verseLabel":"البقرة: 226","question":"ما سرّ التعبير في قوله تعالى: ﴿يُؤْلُونَ مِنْ نِسَائِهِمْ﴾، دون أن يقال: «يحلفون ألا يقربوهن»؟","answer":"اختار لفظ الإيلاء الجامع المعروف لهذا النوع من اليمين، ثم قيده بالنساء ليكشف أثره الأسري. والإيجاز يحول ممارسة جاهلية مفتوحة إلى حكم منضبط.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص524–527، تحت البقرة: 226، في اختيار الإيلاء.","url":""}]},{"id":"s2-1148","number":1148,"surah":2,"verses":[226],"verseLabel":"البقرة: 226","question":"لماذا عبّر بـ﴿تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ﴾؟","answer":"التربص انتظار مقصود مع مراقبة العاقبة، وحد بأربعة أشهر حتى لا تبقى الزوجة معلقة بلا معاشرة ولا طلاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص525–529، تحت البقرة: 226، في المصدر وتحديد المدة.","url":""}]},{"id":"s2-1149","number":1149,"surah":2,"verses":[226],"verseLabel":"البقرة: 226","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِنْ فَاءُوا﴾، وما الذي يوحي به لفظ الفيء؟","answer":"الفيء رجوع إلى ما ينبغي بعد عدول عنه، فكأن العشرة هي الأصل الذي يعود إليه الزوج. واللفظ يحمل معنى التصحيح والعودة لا مجرد إنهاء الامتناع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص527–530، تحت البقرة: 226، في اختيار ﴿فاءوا﴾.","url":""}]},{"id":"s2-1150","number":1150,"surah":2,"verses":[226],"verseLabel":"البقرة: 226","question":"ما مناسبة ختم الرجوع بقوله تعالى: ﴿فَإِنَّ اللَّهَ غَفُورٌ رَحِيمٌ﴾؟","answer":"لأن الفيء يفتح باب إصلاح ما أفسده الحلف؛ فالمغفرة تمحو الذنب والرحمة تعيد المودة وترفع الحرج. وجواب الشرط المحذوف يفهم من هذه البشارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص529–531، تحت البقرة: 226، في الحذف والخاتمة.","url":""}]},{"id":"s2-1151","number":1151,"surah":2,"verses":[227],"verseLabel":"البقرة: 227","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنْ عَزَمُوا الطَّلَاقَ﴾، دون أن يقال: «وإن طلقوا»؟","answer":"ذكر العزم لأن القضية بعد مهلة تفكير: المطلوب قرار جاد لا تهديد متكرر أو تعليق. وإضافة العزم إلى الطلاق تصور انتقاله من خاطر إلى اختيار محسوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص532–535، تحت البقرة: 227، في اختيار العزم.","url":""}]},{"id":"s2-1152","number":1152,"surah":2,"verses":[227],"verseLabel":"البقرة: 227","question":"أين جواب الشرط في ﴿وَإِنْ عَزَمُوا الطَّلَاقَ﴾؟","answer":"جواب الشرط محذوف للتهويل أو مفهوم من السياق، أي وقع الطلاق ولزم حكمه؛ ثم جاءت الخاتمة وعيدًا بأن الله يسمع العزم والقول ويعلم النية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص534–537، تحت البقرة: 227، في حذف الجواب.","url":""}]},{"id":"s2-1153","number":1153,"surah":2,"verses":[227],"verseLabel":"البقرة: 227","question":"ما سرّ اختلاف الخاتمة بين الطلاق: ﴿سَمِيعٌ عَلِيمٌ﴾، والرجوع: ﴿غَفُورٌ رَحِيمٌ﴾؟","answer":"الفيء رجوع إلى المعاشرة والإصلاح فناسبه الغفران والرحمة، أما عزم الطلاق فعمل وقول خفيان أو معلنان فناسبهما السمع والعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص536–539، تحت البقرة: 227، في اختلاف الفاصلتين.","url":""}]},{"id":"s2-1154","number":1154,"surah":2,"verses":[228],"verseLabel":"البقرة: 228","question":"ما سرّ التعبير في قوله تعالى: ﴿بأنفسهن﴾ مع أن التربص لا يكون إلا منهن؟","answer":"يؤكد أنهن يحبسن رغبة النفس ويشاركن بوعي في حفظ النسب والحقوق، فلا يلقين المسؤولية على رقابة خارجية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص546، تحت البقرة: 228.","url":""}]},{"id":"s2-1155","number":1155,"surah":2,"verses":[228],"verseLabel":"البقرة: 228","question":"ما سرّ التعبير في قوله تعالى: ﴿وللرجال عليهن درجة﴾ بعد تقرير الحقوق المتبادلة؟","answer":"أثبت التوازن أولًا ثم ذكر درجة المسؤولية والقوامة وما يتصل بالرجعة والإنفاق؛ فهي تنظيم وتكليف زائد لا إلغاء للمماثلة بالمعروف.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص540–556، تحت البقرة: 228.","url":""}]},{"id":"s2-1156","number":1156,"surah":2,"verses":[228],"verseLabel":"البقرة: 228","question":"ما سرّ التعبير في قوله تعالى: ﴿وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ﴾ بدل «يُتربص بهن»؟","answer":"أسند التربص إليهن ليقرر مسؤوليتهن في حفظ العدة، و﴿بأنفسهن﴾ تؤكد مباشرة المرأة له وضبطها نفسها عن الزواج والكتمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص540–545، تحت البقرة: 228، في الإسناد وزيادة ﴿بأنفسهن﴾.","url":""}]},{"id":"s2-1157","number":1157,"surah":2,"verses":[228],"verseLabel":"البقرة: 228","question":"ما سرّ التعبير بـ﴿ثَلَاثَةَ قُرُوءٍ﴾ دون «ثلاث قروء»؟","answer":"لأن مفرد ﴿قروء﴾ هو «قُرء» وهو مذكر، فخالفه العدد من ثلاثة إلى عشرة فجاء ﴿ثلاثة﴾ بالتاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص543–548، تحت البقرة: 228، في العدد واختيار اللفظ.","url":""}]},{"id":"s2-1158","number":1158,"surah":2,"verses":[228],"verseLabel":"البقرة: 228","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنْ كُنَّ يُؤْمِنَّ بِاللَّهِ وَالْيَوْمِ الْآخِرِ﴾ بعد النهي عن كتمان الحمل؟","answer":"لأن ما في الرحم لا يطلع عليه غالبًا إلا المرأة، فاستدعى رقابة الإيمان حين تعجز رقابة الناس. وذكر اليوم الآخر يضع الكتمان السري أمام الحساب العلني.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص546–551، تحت البقرة: 228، في الشرط ومناسبة الإيمان.","url":""}]},{"id":"s2-1159","number":1159,"surah":2,"verses":[228],"verseLabel":"البقرة: 228","question":"ما سرّ التعبير في قوله تعالى: ﴿وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ﴾ مع وقوع الطلاق؟","answer":"سمّاهم بعولة باعتبار بقاء رابطة الرجعة في العدة، وجاء بأفعل التفضيل لبيان أولوية الزوج بالرد ما دام الباب مفتوحًا، لا ملكًا مطلقًا بعد انقضاء الحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص549–554، تحت البقرة: 228، في التسمية والتفضيل.","url":""}]},{"id":"s2-1160","number":1160,"surah":2,"verses":[228],"verseLabel":"البقرة: 228","question":"ما دلالة تقييد الرجعة بقوله تعالى: ﴿إِنْ أَرَادُوا إِصْلَاحًا﴾؟","answer":"حتى لا تستعمل الرجعة للإضرار أو إطالة العدة؛ حق الرد مشروع عند قصد إصلاح الحياة الزوجية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص552–556، تحت البقرة: 228، في الشرط والتنكير.","url":""}]},{"id":"s2-1161","number":1161,"surah":2,"verses":[228],"verseLabel":"البقرة: 228","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ﴾؟","answer":"صاغ قاعدة توازن مدهشة: كل واجب عليهن يقابله حق لهن بحسب المعروف، فبدأ بحقوقهن بعد أحكام قد تبدو كلها قيودًا عليهن. والتقديم في ﴿لهن﴾ يلفت إلى ما قد يغفل عنه المجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص554–559، تحت البقرة: 228، في المقابلة والتقديم.","url":""}]},{"id":"s2-1162","number":1162,"surah":2,"verses":[228],"verseLabel":"البقرة: 228","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَاللَّهُ عَزِيزٌ حَكِيمٌ﴾؟","answer":"﴿عزيز﴾ يمنع من التلاعب بحدوده أو مغالبته، و﴿حكيم﴾ يضع الحقوق والدرجة كلًا في موضعه. فالفاصلة ترد نظام الأسرة إلى سلطان مقرون بالحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص560–562، تحت البقرة: 228، في مناسبة الاسمين.","url":""}]},{"id":"s2-1163","number":1163,"surah":2,"verses":[229],"verseLabel":"البقرة: 229","question":"ما سرّ تسمية أحكام الزواج والطلاق ﴿حُدُودَ اللَّهِ﴾؟","answer":"سميت حدودًا لأنها أحكام فاصلة تحد المباح من المحظور وتحجز عن الظلم؛ وإضافتها إلى الله تعظم حرمتها وتوجب الوقوف عندها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص563–579، تحت البقرة: 229.","url":""}]},{"id":"s2-1164","number":1164,"surah":2,"verses":[229],"verseLabel":"البقرة: 229","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا تعتدوها﴾ بصيغة الافتعال؟","answer":"الافتعال يوحي بتعمد المجاوزة وبذل النفس فيها، فيحذر من التحايل المقصود على الحدود لا مجرد خطأ عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص579، تحت البقرة: 229.","url":""}]},{"id":"s2-1165","number":1165,"surah":2,"verses":[229],"verseLabel":"البقرة: 229","question":"ما سرّ التعبير في قوله تعالى: ﴿الطلاق مرتان﴾ لا: طلقتان؟","answer":"﴿مرتان﴾ تعد فعل الطلاق الرجعي المتكرر الذي تتخلله فرصة مراجعة، لا مجرد لفظين أو طلقتين مجموعتين في لحظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص583، تحت البقرة: 229.","url":""}]},{"id":"s2-1166","number":1166,"surah":2,"verses":[229],"verseLabel":"البقرة: 229","question":"ما سرّ التعبير في قوله تعالى: ﴿الطَّلَاقُ مَرَّتَانِ﴾ مع أن الطلاق قد يقع ثلاثًا؟","answer":"المراد الطلاق الذي يملك بعده الرجعة مرتان؛ أما الثالثة فتبينها الآية التالية. والعبارة قطعت عادة التكرار بلا حد، فجعلت للقرار عددًا يحفظ المرأة ويمنح فرصتي مراجعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص563–568، تحت البقرة: 229، في الإيجاز والعدد.","url":""}]},{"id":"s2-1167","number":1167,"surah":2,"verses":[229],"verseLabel":"البقرة: 229","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِمْسَاكٌ بِمَعْرُوفٍ أَوْ تَسْرِيحٌ بِإِحْسَانٍ﴾؟","answer":"بعد كل رجعة لا ثالث بين حياة كريمة وفراق كريم؛ فحذف المبتدأ ليجعل الخيارين كأنهما الحكم الحاضر. ورفع التسريح من مجرد عدل إلى إحسان يمنع الانتقام عند الافتراق.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص566–571، تحت البقرة: 229، في التقسيم والحذف.","url":""}]},{"id":"s2-1168","number":1168,"surah":2,"verses":[229],"verseLabel":"البقرة: 229","question":"ما سرّ التعبير في قوله تعالى في البقاء ﴿بِمَعْرُوفٍ﴾ وفي الفراق ﴿بِإِحْسَانٍ﴾؟","answer":"دوام الحياة يحتاج إلى المعروف المتجدد الذي تعرفه الفطرة والشرع، أما لحظة الفراق فهي مظنة الشح والخصومة فطلب فيها الإحسان الزائد: أداء الحقوق وترك الأذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص568–573، تحت البقرة: 229، في اختلاف القيدين.","url":""}]},{"id":"s2-1169","number":1169,"surah":2,"verses":[229],"verseLabel":"البقرة: 229","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا يَحِلُّ لَكُمْ أَنْ تَأْخُذُوا مِمَّا آتَيْتُمُوهُنَّ شَيْئًا﴾؟","answer":"نسب العطاء إلى الأزواج ثم نكر ﴿شيئًا﴾ ليشمل القليل والكثير؛ فما صار حقًا للمرأة لا يسترد بالضغط عند الطلاق. والتعبير بـ﴿لا يحل﴾ يحول المروءة إلى حد شرعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص571–576، تحت البقرة: 229، في العموم والتنكير.","url":""}]},{"id":"s2-1170","number":1170,"surah":2,"verses":[229],"verseLabel":"البقرة: 229","question":"ما سرّ الاستثناء بقوله تعالى: ﴿إِلَّا أَنْ يَخَافَا أَلَّا يُقِيمَا حُدُودَ اللَّهِ﴾؟","answer":"أبيح أخذ العوض في الخلع حين يغلب على الزوجين خوف العجز عن إقامة حقوق الزواج؛ فالاستثناء يفتح مخرجًا من ضرر مستمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص574–579، تحت البقرة: 229، في الاستثناء وتعليل الخلع.","url":""}]},{"id":"s2-1171","number":1171,"surah":2,"verses":[229],"verseLabel":"البقرة: 229","question":"ما سرّ الانتقال من المثنى ﴿يَخَافَا﴾ إلى الجمع ﴿فَإِنْ خِفْتُمْ﴾؟","answer":"الخوف الأول من الزوجين في خاصة حالهما، والثاني موجه إلى الحكام والأولياء والجماعة الذين يقدرون الحال ويحكمون في الخلع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص576–580، تحت البقرة: 229، في اختلاف الضمائر.","url":""}]},{"id":"s2-1172","number":1172,"surah":2,"verses":[229],"verseLabel":"البقرة: 229","question":"ما سرّ التعبير في قوله تعالى في الخلع: ﴿فَلَا جُنَاحَ عَلَيْهِمَا فِيمَا افْتَدَتْ بِهِ﴾؟","answer":"رفع الحرج عن الزوج في الأخذ وعن الزوجة في البذل معًا، وسمى البذل افتداءً لأنه يخلصها من رابطة تخشى معها تضييع الحدود. والعبارة تقيده بالحاجة لا بالابتزاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص578–581، تحت البقرة: 229، في التثنية واستعارة الافتداء.","url":""}]},{"id":"s2-1173","number":1173,"surah":2,"verses":[229],"verseLabel":"البقرة: 229","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَمَنْ يَتَعَدَّ حُدُودَ اللَّهِ فَأُولَئِكَ هُمُ الظَّالِمُونَ﴾؟","answer":"بعد تكرار الحدود قرر أن تجاوزها ظلم للنفس وللزوج الآخر، وأكد الحكم باسم الإشارة وضمير الفصل. فالأحكام ليست تفاصيل شكلية؛ العبث بها يغير وصف الإنسان إلى ظالم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص580–582، تحت البقرة: 229، في الشرط والقصر.","url":""}]},{"id":"s2-1174","number":1174,"surah":2,"verses":[230],"verseLabel":"البقرة: 230","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى تنكح زوجًا غيره﴾ لا: رجلًا غيره؟","answer":"قال ﴿زوجًا﴾ ليشترط عقد زواج صحيح وحياة زوجية حقيقية، لا مجرد عقد صوري على رجل بقصد التحليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص589، تحت البقرة: 230.","url":""}]},{"id":"s2-1175","number":1175,"surah":2,"verses":[230],"verseLabel":"البقرة: 230","question":"ما دلالة قوله تعالى بعد الطلقة الثالثة: ﴿فَلَا تَحِلُّ لَهُ مِنْ بَعْدُ﴾؟","answer":"﴿من بعد﴾ تؤكد ابتداء التحريم عقب الطلقة الثالثة واستمراره إلى تحقق الشرط المذكور؛ فلا رجعة مباشرة بعدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص583–586، تحت البقرة: 230، في الفاء والغاية.","url":""}]},{"id":"s2-1176","number":1176,"surah":2,"verses":[230],"verseLabel":"البقرة: 230","question":"ما سرّ التعبير في قوله تعالى عن الزوج الثاني: ﴿فَإِنْ طَلَّقَهَا﴾ ولم يجعل رجوعها إلى الأول أمرًا مطلوبًا؟","answer":"الزواج الثاني علاقة كاملة قد تستمر، فإن انتهت بطلاق طبيعي فقط عاد إمكان النظر في الزواج الأول. صيغة الشرط تمنع تحويل الثاني إلى جسر مرتب سلفًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص586–589، تحت البقرة: 230، في الشرط.","url":""}]},{"id":"s2-1177","number":1177,"surah":2,"verses":[230],"verseLabel":"البقرة: 230","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلَا جُنَاحَ عَلَيْهِمَا أَنْ يَتَرَاجَعَا﴾؟","answer":"رفع الحرج عن الاثنين لأن التجربة السابقة قد تجعل رجوعهما موضع تهمة، وجاء بصيغة التفاعل لأن العودة عقد جديد بإرادتين لا رجعة يملكها الرجل وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص587–590، تحت البقرة: 230، في التثنية وصيغة التفاعل.","url":""}]},{"id":"s2-1178","number":1178,"surah":2,"verses":[230],"verseLabel":"البقرة: 230","question":"ما دلالة تقييد العودة بقوله تعالى: ﴿إِنْ ظَنَّا أَنْ يُقِيمَا حُدُودَ اللَّهِ﴾؟","answer":"أي إن غلب على ظنهما القدرة على الوفاء بحقوق الزواج بعد التجربة السابقة؛ فلا تكون العودة تكرارًا لأسباب الفشل والظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص589–591، تحت البقرة: 230، في الشرط واختيار الظن.","url":""}]},{"id":"s2-1179","number":1179,"surah":2,"verses":[230],"verseLabel":"البقرة: 230","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿يُبَيِّنُهَا لِقَوْمٍ يَعْلَمُونَ﴾؟","answer":"ينتفع بتفصيل الحدود من يتعلمها ويعقل حكمتها، لا من يتخذ الطلاق والرجعة ألعوبة. وصيغة المضارع تصور البيان متجددًا، ووصف القوم بالعلم يحفز إلى الفقه قبل القرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص590–592، تحت البقرة: 230، في الخاتمة.","url":""}]},{"id":"s2-1180","number":1180,"surah":2,"verses":[231],"verseLabel":"البقرة: 231","question":"ما مناسبة النهي عن اتخاذ آيات الله هزوًا في أثناء أحكام الطلاق؟","answer":"لأن التلاعب بألفاظ الطلاق والرجعة والتحايل على العدد يحول حدود الله إلى لعبة؛ فالتغليظ يحمي أخطر مواضع العبث الأسري.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص593–612، تحت البقرة: 231.","url":""}]},{"id":"s2-1181","number":1181,"surah":2,"verses":[231],"verseLabel":"البقرة: 231","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿أَنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ﴾؟","answer":"لأن نية الرجعة قد تستر قصد الإضرار، فالعلم الشامل يراقب باطن التصرف الذي لا تكشفه الصيغة القانونية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص610، تحت البقرة: 231.","url":""}]},{"id":"s2-1182","number":1182,"surah":2,"verses":[2],"verseLabel":"البقرة: 231، الطلاق: 2","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿أَوْ سَرِّحُوهُنَّ بِمَعْرُوفٍ﴾، وقوله تعالى في سورة الطلاق: ﴿أَوْ فَارِقُوهُنَّ بِمَعْرُوفٍ﴾؟","answer":"﴿سرحوهن﴾ في البقرة يناسب سياق بقاء المطلقة في العدة تحت يد الزوج حتى يطلق سراحها بالمعروف، و﴿فارقوهن﴾ في سورة الطلاق يناسب بلوغ الأجل وحصول المفارقة الفعلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص323–325، تحت الطلاق: 2، في المقارنة بالبقرة: 229 و231.","url":""}]},{"id":"s2-1183","number":1183,"surah":2,"verses":[231],"verseLabel":"البقرة: 231","question":"ما سرّ تكرار الأمر بالإمساك أو التسريح بعد ذكره في الآية 229؟","answer":"هناك بيان لأصل الخيار بعد الطلاق، وهنا بيان لوقته وأخلاق تنفيذه عند بلوغ العدة؛ فالتكرار ينقل الحكم من التشريع العام إلى لحظة قد يقع فيها الضرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص593–598، تحت البقرة: 231، في التكرار والسياق.","url":""}]},{"id":"s2-1184","number":1184,"surah":2,"verses":[231],"verseLabel":"البقرة: 231","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تُمْسِكُوهُنَّ ضِرَارًا لِتَعْتَدُوا﴾؟","answer":"كشف حيلة الرجعة التي ظاهرها إبقاء الزواج وباطنها إطالة الأذى، وجعل الإمساك نفسه اعتداءً حين ينقلب مقصده من الإصلاح إلى الضرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص597–602، تحت البقرة: 231، في المفعول لأجله.","url":""}]},{"id":"s2-1185","number":1185,"surah":2,"verses":[232],"verseLabel":"البقرة: 232","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا تعضلوهن﴾؟ وما الصورة التي يحملها العضل؟","answer":"العضل حبس ومنع في ضيق، فيصور الولي كمن يحاصر المرأة ويصدها عن زواج رضيه الطرفان؛ فجاء النهي لتحرير حقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص612–628، تحت البقرة: 232.","url":""}]},{"id":"s2-1186","number":1186,"surah":2,"verses":[2],"verseLabel":"البقرة: 232، الطلاق: 2","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿ذَلِكَ يُوعَظُ بِهِ مَنْ كَانَ مِنْكُمْ يُؤْمِنُ بِاللَّهِ﴾ بالإفراد و﴿منكم﴾، وقوله تعالى في الطلاق: ﴿ذَلِكُمْ يُوعَظُ بِهِ مَنْ كَانَ يُؤْمِنُ بِاللَّهِ﴾ بالجمع ومن غير ﴿منكم﴾؟","answer":"جاءت البقرة في تشديد شديد على من يظلم النساء أو يعضلهن ويحتال على أموالهن؛ فالإفراد في ﴿ذلك﴾ ثم التبعيض في ﴿منكم﴾ يلمحان إلى قلة المستجيبين المتورعين عن هذه المطامع. أما أحكام سورة الطلاق في هذا الموضع فأيسر امتثالًا وأكثر من يسلك طريقها، كما أن صدر السورة خاطب النبي والأمة معًا؛ فناسب خطاب الجمع ﴿ذلكم﴾ وحذف التبعيض.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص333–335، تحت الطلاق: 2، في المقارنة بالبقرة: 232.","url":""}]},{"id":"s2-1187","number":1187,"surah":2,"verses":[232],"verseLabel":"البقرة: 232","question":"ما سرّ توجيه الخطاب إلى الجماعة في قوله تعالى: ﴿فَلَا تَعْضُلُوهُنَّ أَنْ يَنْكِحْنَ أَزْوَاجَهُنَّ﴾؟","answer":"الخطاب للأولياء وللمجتمع ومن يملك المنع؛ لأن العضل قد يصدر من الولي أو يتواطأ عليه المحيطون، فحمّل الجماعة مسؤولية رفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص612–618، تحت البقرة: 232، في الخطاب واختيار ﴿تعضلوهن﴾.","url":""}]},{"id":"s2-1188","number":1188,"surah":2,"verses":[232],"verseLabel":"البقرة: 232","question":"ما سرّ إطلاق ﴿أَزْوَاجَهُنَّ﴾ بعد انتهاء الزواج؟","answer":"باعتبار ما كان وما يراد أن يعود، وفي اللفظ تذكير بأن المانع يقطع رابطة عرفها الطرفان ويرتضيان استئنافها، لا أنه يحميها من غريب.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص616–622، تحت البقرة: 232، في التعبير بالزوجية.","url":""}]},{"id":"s2-1189","number":1189,"surah":2,"verses":[232],"verseLabel":"البقرة: 232","question":"ما سرّ التعبير في قوله تعالى: ﴿ذَلِكُمْ أَزْكَى لَكُمْ وَأَطْهَرُ﴾ ثم ﴿وَاللَّهُ يَعْلَمُ وَأَنْتُمْ لَا تَعْلَمُونَ﴾؟","answer":"ترك العضل أطهر من الضغينة والريبة وأزكى للعلاقات، ولو خالف تقديرات الناس العاجلة؛ فختم بعلم الله ليقدم حكمة الشرع على ظنون الأسرة والمجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص621–627، تحت البقرة: 232، في التفضيل والخاتمة.","url":""}]},{"id":"s2-1190","number":1190,"surah":2,"verses":[233],"verseLabel":"البقرة: 233","question":"ما سرّ التعبير في قوله تعالى: ﴿حولين كاملين﴾ لا سنتين؟","answer":"الحول دورة زمنية مكتملة من وقت الولادة، وهو أدق في حساب الرضاع من السنة التقويمية؛ و﴿كاملين﴾ تمنع نقص المدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص636، تحت البقرة: 233.","url":""}]},{"id":"s2-1191","number":1191,"surah":2,"verses":[233],"verseLabel":"البقرة: 233","question":"لماذا عبّر عن الأب بـ﴿المولود له﴾ لا الوالد؟","answer":"نسب الولد إليه ليجعل هذه النسبة نفسها علة وجوب النفقة عليه، فيوازن جهد الأم الجسدي بمسؤوليته المالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص641، تحت البقرة: 233.","url":""}]},{"id":"s2-1192","number":1192,"surah":2,"verses":[233],"verseLabel":"البقرة: 233","question":"ما سرّ التعبير في قوله تعالى: ﴿لا تكلف نفس إلا وسعها﴾ لا طاقتها؟","answer":"الوسع ما يسع الإنسان فعله بلا حرج بالغ، أما الطاقة فقد تشمل أقصى ما يقدر عليه بمشقة؛ فاختير الأرفق.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص639، تحت البقرة: 233.","url":""}]},{"id":"s2-1193","number":1193,"surah":2,"verses":[233],"verseLabel":"البقرة: 233","question":"ما سرّ التعبير في قوله تعالى: ﴿وعلى الوارث مثل ذلك﴾ لا: على القريب؟","answer":"الوارث وصف قانوني يحدد من يخلف الأب في المسؤولية بحسب الصلة والحق، أما القريب فلفظ واسع لا يضبط من يلزم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص644، تحت البقرة: 233.","url":""}]},{"id":"s2-1194","number":1194,"surah":2,"verses":[6],"verseLabel":"البقرة: 233، الطلاق: 6","question":"ما سرّ التعبير في قوله تعالى في البقرة عن المرضعات: ﴿وَعَلَى الْمَوْلُودِ لَهُ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِالْمَعْرُوفِ﴾، وقال للمطلقات في سورة الطلاق: ﴿فَآتُوهُنَّ أُجُورَهُنَّ﴾؟","answer":"آية الطلاق تتحدث عن امرأة انفصلت عرى الزوجية بينها وبين الأب؛ فإذا أرضعت ولده صارت خدمتها المستقلة مستحقة لأجرة صريحة. أما البقرة فتؤصل مسؤولية الأبوين المشتركة، وتسمي الأم ﴿والدة﴾ والأب ﴿المولود له﴾؛ فعبّرت عن حقها بالنفقة والكسوة في منظومة الحقوق الأسرية المتقابلة، لا بأجرة عمل منفصل. اختلاف اللفظ يكشف اختلاف العلاقة في السياقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص648–649، تحت البقرة: 233، في المقارنة بالطلاق: 6.","url":""}]},{"id":"s2-1195","number":1195,"surah":2,"verses":[233],"verseLabel":"البقرة: 233","question":"ما سرّ التعبير في قوله تعالى: ﴿وَالْوَالِدَاتُ يُرْضِعْنَ﴾، دون أن يقال «الأمهات»؟","answer":"لفظ الوالدات يناسب مقام الولادة والرضاع ويستحضر الصلة الجسدية التي ينبني عليها الحكم، بينما الأم أعم وقد تطلق على غير الوالدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص628–634، تحت البقرة: 233، في اختيار اللفظ.","url":""}]},{"id":"s2-1196","number":1196,"surah":2,"verses":[233],"verseLabel":"البقرة: 233","question":"ما سرّ التعبير في قوله تعالى: ﴿حَوْلَيْنِ كَامِلَيْنِ﴾، أليست التثنية كافية؟","answer":"دفع توهم التساهل في كسر شيء من العامين، وأكد أن هذه مدة تمام الرضاع لمن أراده؛ فـ﴿كاملين﴾ تحفظ حق الطفل وتحدد نهاية الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص632–638، تحت البقرة: 233، في التوكيد.","url":""}]},{"id":"s2-1197","number":1197,"surah":2,"verses":[233],"verseLabel":"البقرة: 233","question":"لماذا كرر منع الضرر للأم والأب: ﴿لَا تُضَارَّ وَالِدَةٌ... وَلَا مَوْلُودٌ لَهُ﴾؟","answer":"حتى لا يتحول الطفل إلى وسيلة انتقام بعد الفراق؛ فلا يضغط الأب بالنفقة ولا الأم بالرضاع. وبناء الفعل يحتمل نهي كل طرف عن الإضرار ونهي الآخرين عن إضراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص639–645، تحت البقرة: 233، في احتمال صيغة ﴿تضار﴾.","url":""}]},{"id":"s2-1198","number":1198,"surah":2,"verses":[233],"verseLabel":"البقرة: 233","question":"لماذا اشترط في الفصال ﴿تَرَاضٍ مِنْهُمَا وَتَشَاوُرٍ﴾؟","answer":"لأن مصلحة الطفل لا يقررها طرف منفرد؛ فالتراضي يمنع الإكراه، والتشاور يطلب تقدير الأصلح قبل القرار. وجمعهما يفرق بين مجرد الموافقة والقرار المبني على نظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص644–650، تحت البقرة: 233، في الجمع والترتيب.","url":""}]},{"id":"s2-1199","number":1199,"surah":2,"verses":[234],"verseLabel":"البقرة: 234","question":"ما سرّ التعبير في قوله تعالى: ﴿ويذرون أزواجًا﴾ لا: يتركون أرامل؟","answer":"سماهن أزواجًا وفاء للرابطة التي انتهت بالموت، ولم يلصق بهن وصف الترمل الذي يبرز الفقد ويغطي هويتهن.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص656، تحت البقرة: 234.","url":""}]},{"id":"s2-1200","number":1200,"surah":2,"verses":[234],"verseLabel":"البقرة: 234","question":"لماذا كانت عدة الوفاة ﴿أربعة أشهر وعشرًا﴾ ولم يقل: عشرة أيام؟","answer":"حذف المعدود للعلم به من السياق العربي، ويحتمل الليالي بأيامها؛ فأوجز وحافظ على نسق العدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص651–667، تحت البقرة: 234.","url":""}]},{"id":"s2-1201","number":1201,"surah":2,"verses":[234],"verseLabel":"البقرة: 234","question":"ما سرّ التعبير في قوله تعالى: ﴿يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا﴾؟","answer":"أسند التربص إليهن كما في عدة الطلاق، لكن زاد مدة الوفاة تحقيقًا لبراءة الرحم ووفاءً للرابطة المنتهية بالموت. وحذف «أيام» بعد عشرًا جريًا على وضوح المعدود.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص651–657، تحت البقرة: 234، في الإسناد والعدد.","url":""}]},{"id":"s2-1202","number":1202,"surah":2,"verses":[234],"verseLabel":"البقرة: 234","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِذَا بَلَغْنَ أَجَلَهُنَّ﴾، دون أن يقال «قاربن» كما في المطلقات؟","answer":"بلوغ الأجل هنا انقضاء العدة حقيقة، لأن ما بعدها رفع للحرج عن تصرف المرأة؛ أما آيات الطلاق فالمقام مقام قرار الإمساك أو التسريح قرب النهاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص655–662، تحت البقرة: 234، في اختلاف التعبير.","url":""}]},{"id":"s2-1203","number":1203,"surah":2,"verses":[234],"verseLabel":"البقرة: 234","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنْفُسِهِنَّ بِالْمَعْرُوفِ﴾؟","answer":"رفع المسؤولية عن الأولياء بعد تمام العدة وأعاد للمرأة حرية شأنها في حدود المعروف، فلا ولاية تمنعها من زينة أو زواج مشروع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص660–666، تحت البقرة: 234، في رفع الجناح والقيد.","url":""}]},{"id":"s2-1204","number":1204,"surah":2,"verses":[235],"verseLabel":"البقرة: 235","question":"ما سرّ التعبير في قوله تعالى: ﴿أو أكننتم في أنفسكم﴾ لا: كننتم؟","answer":"الإكنان إخفاء الشيء وصونه في باطن النفس، وهو أدق من مجرد الستر؛ ففرق بين خاطر مكتوم وقول أو وعد ظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص676، تحت البقرة: 235.","url":""}]},{"id":"s2-1205","number":1205,"surah":2,"verses":[235],"verseLabel":"البقرة: 235","question":"لماذا فرّق بين ﴿عَرَّضْتُمْ بِهِ مِنْ خِطْبَةِ النِّسَاءِ﴾ و﴿أَكْنَنْتُمْ فِي أَنْفُسِكُمْ﴾؟","answer":"أباح الإشارة المحتملة وكتمان الرغبة، ومنع التصريح والعقد في العدة؛ فاختلاف اللفظ يرسم درجات ما في النفس وما يظهر على اللسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص667–672، تحت البقرة: 235، في التعريض والإكنان.","url":""}]},{"id":"s2-1206","number":1206,"surah":2,"verses":[235],"verseLabel":"البقرة: 235","question":"ما سرّ التعبير في قوله تعالى: ﴿عَلِمَ اللَّهُ أَنَّكُمْ سَتَذْكُرُونَهُنَّ﴾؟","answer":"راعى طبيعة النفس وأن الرغبة ستظهر، فلم يكلفها بمحو الخاطر بل ضبط طريقة التعبير عنه. والسين تصور الأمر المتوقع الذي جاء التشريع لتنظيمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص670–675، تحت البقرة: 235، في الاستقبال والتعليل.","url":""}]},{"id":"s2-1207","number":1207,"surah":2,"verses":[235],"verseLabel":"البقرة: 235","question":"لماذا استثنى: ﴿إِلَّا أَنْ تَقُولُوا قَوْلًا مَعْرُوفًا﴾ بعد النهي عن المواعدة سرًا؟","answer":"أخرج من المواعدة المحرمة قولًا منضبطًا لا فحش فيه ولا إلزام ولا تصريح يعارض حرمة العدة؛ فالمعروف معيار اللفظ والقصد معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص673–678، تحت البقرة: 235، في الاستثناء.","url":""}]},{"id":"s2-1208","number":1208,"surah":2,"verses":[235],"verseLabel":"البقرة: 235","question":"لماذا ختم بـ﴿وَاعْلَمُوا أَنَّ اللَّهَ غَفُورٌ حَلِيمٌ﴾ بعد التحذير من علمه؟","answer":"جمع الهيبة والرجاء: يعلم خفايا النفوس فاحذروه، لكنه يغفر الخاطر أو الزلة لمن رجع ويحلم فلا يعاجل بالعقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص677–681، تحت البقرة: 235، في الجمع بين الوعيد والرجاء.","url":""}]},{"id":"s2-1209","number":1209,"surah":2,"verses":[236],"verseLabel":"البقرة: 236","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا جُنَاحَ عَلَيْكُمْ إِنْ طَلَّقْتُمُ النِّسَاءَ مَا لَمْ تَمَسُّوهُنَّ﴾؟","answer":"رفع توهم الإثم في طلاق وقع قبل الدخول وتحديد المهر، مع إبقاء واجب الجبر بالمتاع؛ فعدم الجناح لا يعني غياب المسؤولية الأدبية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص682–686، تحت البقرة: 236، في رفع الجناح.","url":""}]},{"id":"s2-1210","number":1210,"surah":2,"verses":[236],"verseLabel":"البقرة: 236","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَتِّعُوهُنَّ عَلَى الْمُوسِعِ قَدَرُهُ وَعَلَى الْمُقْتِرِ قَدَرُهُ﴾؟","answer":"ساوى في أصل المواساة وراعى تفاوت القدرة في مقدارها؛ فكرر البناء لتظهر مسؤولية الغني والفقير معًا من غير إجحاف بأحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص684–688، تحت البقرة: 236، في المقابلة والتكرار.","url":""}]},{"id":"s2-1211","number":1211,"surah":2,"verses":[236],"verseLabel":"البقرة: 236","question":"لماذا وصف المتاع بأنه ﴿حَقًّا عَلَى الْمُحْسِنِينَ﴾؟","answer":"جعله حقًا مؤكدًا ثم نسب أداءه إلى الإحسان، لأن المؤمن لا يقف عند براءة الذمة بل يجبر خاطر من فارقها قبل اكتمال الزواج.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص687–690، تحت البقرة: 236، في المصدر ووصف المحسنين.","url":""}]},{"id":"s2-1212","number":1212,"surah":2,"verses":[237],"verseLabel":"البقرة: 237","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن طلقتموهن﴾ بـ﴿إن﴾ لا ﴿إذا﴾؟","answer":"لأن الطلاق قبل المسيس فرضٌ طارئ غير مرغوب ولا متيقن، فناسبته أداة الاحتمال لا أداة المتوقع الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص695، تحت البقرة: 237.","url":""}]},{"id":"s2-1213","number":1213,"surah":2,"verses":[237],"verseLabel":"البقرة: 237","question":"لماذا أوجب نصف المهر إذا وقع الطلاق قبل المسيس بعد فرضه؟","answer":"لأن العقد والفرض أنشآ حقًا، وعدم الدخول خفف الكمال إلى النصف؛ فجمع الحكم بين احترام الالتزام ومراعاة أن الزواج لم يكتمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص691–695، تحت البقرة: 237، في مناسبة التنصيف.","url":""}]},{"id":"s2-1214","number":1214,"surah":2,"verses":[237],"verseLabel":"البقرة: 237","question":"ما سرّ التعبير في قوله تعالى: ﴿إِلَّا أَنْ يَعْفُونَ أَوْ يَعْفُوَ الَّذِي بِيَدِهِ عُقْدَةُ النِّكَاحِ﴾؟","answer":"فتح للطرفين باب تجاوز الحد المالي بالفضل: للمرأة ترك نصفها، ولمن بيده العقد إتمام المهر؛ فالعفو هنا تحرير للعلاقة من الحساب المجرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص694–698، تحت البقرة: 237، في الاستثناء والمقابلة.","url":""}]},{"id":"s2-1215","number":1215,"surah":2,"verses":[237],"verseLabel":"البقرة: 237","question":"ما سرّ التعبير في قوله تعالى: ﴿وَأَنْ تَعْفُوا أَقْرَبُ لِلتَّقْوَى﴾؟","answer":"لأن العفو عند الخصومة دليل قدرة النفس على كبح الشح والانتقام، فجعله طريقًا أقرب إلى التقوى لا مجرد تنازل اجتماعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص696–699، تحت البقرة: 237، في التفضيل.","url":""}]},{"id":"s2-1216","number":1216,"surah":2,"verses":[237],"verseLabel":"البقرة: 237","question":"لماذا ختم أحكام المهر بقوله: ﴿وَلَا تَنْسَوُا الْفَضْلَ بَيْنَكُمْ﴾؟","answer":"حتى لا تمحو لحظة الفراق ما كان من مودة وإحسان؛ فالحقوق تحد الأدنى، والفضل يحفظ الإنسانية بعد انقطاع العقد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص698–700، تحت البقرة: 237، في النهي والخاتمة.","url":""}]},{"id":"s2-1217","number":1217,"surah":2,"verses":[238],"verseLabel":"البقرة: 238","question":"ما سرّ التعبير في قوله تعالى: ﴿حافظوا على الصلوات والصلاة الوسطى﴾ فخص صلاة بعد جمع الصلوات؟","answer":"عطف الخاص على العام لمزيد العناية بصلاة تتعرض للتفويت أو تتوسط الصلوات، مع بقاء المحافظة شاملة للجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص708–710، تحت البقرة: 238.","url":""}]},{"id":"s2-1218","number":1218,"surah":2,"verses":[238],"verseLabel":"البقرة: 238","question":"لماذا اختار الصلاة من بين العبادات في وسط أحكام الأسرة؟","answer":"لأنها تجدد التقوى التي تضبط الطلاق والحقوق عند الغضب، وتعيد القلب من نزاع العلاقات إلى الوقوف بين يدي الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص709، تحت البقرة: 238.","url":""}]},{"id":"s2-1219","number":1219,"surah":2,"verses":[238],"verseLabel":"البقرة: 238","question":"ما سرّ التعبير في قوله تعالى: ﴿وَقُومُوا لِلَّهِ قَانِتِينَ﴾؟","answer":"لم يكتف بأداء الصلاة، بل طلب قيامًا خالصًا لله مصحوبًا بالخضوع والسكينة؛ فاللام تصفي الجهة و﴿قانتين﴾ تصف هيئة الظاهر والباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص708–712، تحت البقرة: 238، في التقديم والحال.","url":""}]},{"id":"s2-1220","number":1220,"surah":2,"verses":[239],"verseLabel":"البقرة: 239","question":"ما سرّ التعبير في قوله تعالى في حال الخوف ﴿فرجالًا أو ركبانا﴾ ثم أمر بالذكر بعد الأمن؟","answer":"خفف الهيئة ولم يسقط الصلاة في الخطر، ثم أعادها إلى كمالها مع شكر نعمة الأمن؛ فجمع دوام العبادة ومرونة صورتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص713–721، تحت البقرة: 239.","url":""}]},{"id":"s2-1221","number":1221,"surah":2,"verses":[239],"verseLabel":"البقرة: 239","question":"لماذا رخص في الخوف: ﴿فَرِجَالًا أَوْ رُكْبَانًا﴾؟","answer":"لأن الصلاة لا تسقط بالخطر، لكن هيئتها تتكيف معه؛ فذكر حالتي المشي والركوب ليشمل ما تسمح به القدرة. وفي الإيجاز جمع بين المحافظة والتيسير.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص713–716، تحت البقرة: 239، في الحذف والتقسيم.","url":""}]},{"id":"s2-1222","number":1222,"surah":2,"verses":[239],"verseLabel":"البقرة: 239","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِذَا أَمِنْتُمْ فَاذْكُرُوا اللَّهَ﴾، دون أن يقال «فصلوا»؟","answer":"الذكر أعم وهو روح الصلاة، فيشمل العودة إلى هيئتها الكاملة وشكر نعمة الأمن. واختيار اللفظ يصل عبادة الخوف بعبادة الطمأنينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص715–718، تحت البقرة: 239، في اختيار الذكر.","url":""}]},{"id":"s2-1223","number":1223,"surah":2,"verses":[239],"verseLabel":"البقرة: 239","question":"لماذا ختم بـ﴿كَمَا عَلَّمَكُمْ مَا لَمْ تَكُونُوا تَعْلَمُونَ﴾؟","answer":"جعل تعليم الصلاة وسائر الشرائع نعمة تستوجب الذكر، فكما أخرجهم من الجهل يشكرونه بالطاعة. والتشبيه يربط مقدار الشكر بعظمة التعليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص717–720، تحت البقرة: 239، في التعليل.","url":""}]},{"id":"s2-1224","number":1224,"surah":2,"verses":[240],"verseLabel":"البقرة: 240","question":"ما سرّ التعبير في قوله تعالى: ﴿متاعًا إلى الحول﴾ بالحول لا السنة؟","answer":"الحول دورة زمنية محسوبة من لحظة الوفاة، وهو الأنسب لمدة حق السكنى والنفقة، لا سنة تقويمية قد بدأ بعضها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص733، تحت البقرة: 240.","url":""}]},{"id":"s2-1225","number":1225,"surah":2,"verses":[240],"verseLabel":"البقرة: 240","question":"لماذا جاءت وصية المتوفى لزوجته بـ﴿مَتَاعًا إِلَى الْحَوْلِ غَيْرَ إِخْرَاجٍ﴾؟","answer":"قصدت حفظها من أن يجتمع عليها فقد الزوج وفقد المسكن والنفقة، فجعل المتاع ممتدًا ومنع إخراجها. وتعرض الموسوعة لعلاقة الحكم بما نزل بعده من المواريث والعدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص721–727، تحت البقرة: 240، في المقصد والتركيب.","url":""}]},{"id":"s2-1226","number":1226,"surah":2,"verses":[240],"verseLabel":"البقرة: 240","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِنْ خَرَجْنَ فَلَا جُنَاحَ عَلَيْكُمْ﴾؟","answer":"فرق بين إخراجها قسرًا، وهو المنهي عنه، وبين خروجها باختيارها بعد تحقق الحق؛ فرفع الحرج عن الأولياء فيما تستقل به من شأنها المعروف.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص726–731، تحت البقرة: 240، في الشرط والمقابلة.","url":""}]},{"id":"s2-1227","number":1227,"surah":2,"verses":[240],"verseLabel":"البقرة: 240","question":"لماذا ختم بـ﴿عَزِيزٌ حَكِيمٌ﴾؟","answer":"العزيز يحمي حدوده وحق الضعيفة من العبث، والحكيم يوازن بين حق السكنى وحرية المرأة في الخروج؛ فاجتمع السلطان مع وضع الحكم في موضعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص731–735، تحت البقرة: 240، في الفاصلة.","url":""}]},{"id":"s2-1228","number":1228,"surah":2,"verses":[241],"verseLabel":"البقرة: 241","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلِلْمُطَلَّقَاتِ مَتَاعٌ بِالْمَعْرُوفِ﴾ بعد تفصيل أحوال الطلاق؟","answer":"ختم التفصيل بقاعدة عامة تحفظ جبر خاطر المطلقة بحسب المعروف، فلا تضيع حالة لم يصرح بها. وتقديم ﴿للمطلقات﴾ يثبت الحق لهن.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص736–739، تحت البقرة: 241، في التعميم والتقديم.","url":""}]},{"id":"s2-1229","number":1229,"surah":2,"verses":[241],"verseLabel":"البقرة: 241","question":"ما سرّ التعبير في قوله تعالى: ﴿حَقًّا عَلَى الْمُتَّقِينَ﴾، وفي الآية 236: ﴿عَلَى الْمُحْسِنِينَ﴾؟","answer":"هناك برز الإحسان في جبر من طلقت قبل الدخول، وهنا ختمت منظومة الحدود بالتقوى التي تدفع إلى أداء حق كل مطلقة؛ فاختلف الوصف باختلاف زاوية السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص738–741، تحت البقرة: 241، في اختلاف الخاتمتين.","url":""}]},{"id":"s2-1230","number":1230,"surah":2,"verses":[242],"verseLabel":"البقرة: 242","question":"ما سرّ التعبير في قوله تعالى: ﴿كَذَلِكَ يُبَيِّنُ اللَّهُ لَكُمْ آيَاتِهِ﴾ بعد أحكام الأسرة؟","answer":"الإشارة تلخص وضوح التفصيل وتوازنه بين الحقوق، وتنسب البيان إلى الله ليعلم أن هذه الحدود هداية لا قيود متفرقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص741–742، تحت البقرة: 242، في اسم الإشارة.","url":""}]},{"id":"s2-1231","number":1231,"surah":2,"verses":[242],"verseLabel":"البقرة: 242","question":"لماذا كانت الغاية: ﴿لَعَلَّكُمْ تَعْقِلُونَ﴾؟","answer":"لأن إدراك حكمة هذه التفاصيل يمنع تطبيقها آليًا أو التحايل عليها؛ فالعقل يصل النص بمقاصد العدل والإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص742–743، تحت البقرة: 242، في الخاتمة.","url":""}]},{"id":"s2-1232","number":1232,"surah":2,"verses":[243],"verseLabel":"البقرة: 243","question":"ما سرّ التعبير في قوله تعالى عن الخارجين من ديارهم ﴿وهم ألوف حذر الموت﴾ ثم أماتهم الله؟","answer":"جمع كثرتهم وسبب فرارهم ليهدم وهم أن العدد والحيلة يدفعان الأجل؛ جاءهم الموت من الجهة التي هربوا منها ثم أراهم الإحياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص744–763، تحت البقرة: 243.","url":""}]},{"id":"s2-1233","number":1233,"surah":2,"verses":[61],"verseLabel":"البقرة: 243، يونس: 60، النمل: 73، غافر: 61","question":"لماذا كرر لفظ ﴿النَّاسِ﴾ في البقرة: ﴿إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَشْكُرُونَ﴾، بينما قال في يونس والنمل: ﴿ولكن أكثرهم﴾ بالضمير؟","answer":"سياق البقرة، ومثله غافر، يقصد تحريك الناس جميعًا للاعتبار بآيات الله وفضله؛ فكرر الاسم الظاهر ليبقى عموم البشر حاضرًا في طرفي الكلام. أما يونس والنمل فالسياق متصل بمرجع قريب هو ﴿الناس﴾، فناسب الضمير ربط الجملة بما قبلها وتجنب إعادة لا يحتاجها المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص417–418، تحت النمل: 73، في المقارنة بالبقرة: 243 ويونس: 60 وغافر: 61.","url":""}]},{"id":"s2-1234","number":1234,"surah":2,"verses":[243],"verseLabel":"البقرة: 243","question":"لماذا افتتح قصة الخارجين من ديارهم بـ﴿أَلَمْ تَرَ﴾ مع أن المخاطب لم يشاهدها؟","answer":"نزّل الخبر الموثوق منزلة المشاهد ليستحضر السامع غرابة القصة وعبرتها، والاستفهام يشوقه إلى مشهد ألوف يهربون من الموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص744–748، تحت البقرة: 243، في الاستفهام والرؤية.","url":""}]},{"id":"s2-1235","number":1235,"surah":2,"verses":[243],"verseLabel":"البقرة: 243","question":"لماذا ختم القصة بقوله: ﴿وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَشْكُرُونَ﴾؟","answer":"الإحياء والإنذار فضل، لكن أكثر الناس لا يحولون معرفة قدرة الله إلى شكر وطاعة. والاستدراك يكشف التفاوت بين عموم الفضل وقلة الاستجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص752–756، تحت البقرة: 243، في الاستدراك.","url":""}]},{"id":"s2-1236","number":1236,"surah":2,"verses":[244],"verseLabel":"البقرة: 244","question":"لماذا أعقب قصة الموت والحياة بالأمر ﴿وقاتلوا في سبيل الله﴾؟","answer":"القصة تحرر المؤمن من جبن الفرار: لا يقدم القتال أجلًا ولا يؤخر الهرب موتًا، فبني عليها الأمر بالفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص767–772، تحت البقرة: 244.","url":""}]},{"id":"s2-1237","number":1237,"surah":2,"verses":[244],"verseLabel":"البقرة: 244","question":"لماذا ختم بـ﴿وَاعْلَمُوا أَنَّ اللَّهَ سَمِيعٌ عَلِيمٌ﴾؟","answer":"يسمع أقوال المترددين والمطيعين ويعلم دوافعهم، فلا تختفي وراء شعار الجهاد نية فاسدة ولا وراء الاعتذار حقيقة الجبن.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص760–762، تحت البقرة: 244، في الفاصلة.","url":""}]},{"id":"s2-1238","number":1238,"surah":2,"verses":[245],"verseLabel":"البقرة: 245","question":"لماذا سمّى الإنفاق قرضًا لله مع أن الله هو مالك المال؟","answer":"تشريف للمنفق وضمان للوفاء والمضاعفة، كأن ما بذله دين محفوظ عند الله؛ وهو غني لكنه نسب الأخذ إليه رفقًا بالمحتاج.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص763–772، تحت البقرة: 245.","url":""}]},{"id":"s2-1239","number":1239,"surah":2,"verses":[245],"verseLabel":"البقرة: 245","question":"ما سرّ التعبير في قوله تعالى: ﴿فيضاعفه له أضعافًا كثيرة﴾ ولم يحدد عدد المضاعفة؟","answer":"أطلقها لتبقى أبواب الرجاء مفتوحة بحسب الإخلاص والحاجة وفضل الله الذي لا يحده رقم واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص763–772، تحت البقرة: 245.","url":""}]},{"id":"s2-1240","number":1240,"surah":2,"verses":[11],"verseLabel":"البقرة: 245، الحديد: 11","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿فَيُضَاعِفَهُ لَهُ أَضْعَافًا كَثِيرَةً﴾، وقوله تعالى في الحديد: ﴿فَيُضَاعِفَهُ لَهُ وَلَهُ أَجْرٌ كَرِيمٌ﴾؟","answer":"آية البقرة جاءت في سياق الجهاد والحاجة إلى تحريك النفوس لبذل المال؛ فوجهت النظر إلى الكم، وصرحت بأضعاف كثيرة غير محددة، ثم شرحت السورة صورة المضاعفة في مثل الحبة التي أنبتت سبع سنابل. أما الحديد فذكر المضاعفة بإطلاق، ثم نقل النظر إلى نوع الجزاء وقدره المعنوي فقال ﴿أجر كريم﴾؛ فجمع الوعد بالزيادة مع جلال الأجر وكرامته في سياق الحث العام على الإنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص737–738، تحت الحديد: 11، في الاتفاق والاختلاف مع البقرة: 245.","url":""}]},{"id":"s2-1241","number":1241,"surah":2,"verses":[245],"verseLabel":"البقرة: 245","question":"لماذا ختم بـ﴿وَاللَّهُ يَقْبِضُ وَيَبْسُطُ وَإِلَيْهِ تُرْجَعُونَ﴾؟","answer":"من يخشى الفقر يعلم أن الرزق قبضًا وبسطًا بيد الله، وأن المال وصاحبه راجعان إليه؛ فالمقابلة تعالج سبب البخل من جذره.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص768–771، تحت البقرة: 245، في الطباق والخاتمة.","url":""}]},{"id":"s2-1242","number":1242,"surah":2,"verses":[246],"verseLabel":"البقرة: 246","question":"ما سرّ قول بني إسرائيل ﴿ابعث لنا ملكًا﴾ لا: أرسل لنا؟","answer":"البعث إقامة شخص من بينهم وتحريكه لمهمة القيادة، أما الإرسال فقد يوحي برسول يأتيهم برسالة؛ وهم طلبوا قائدًا يقاتلون تحت رايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص780، تحت البقرة: 246.","url":""}]},{"id":"s2-1243","number":1243,"surah":2,"verses":[246],"verseLabel":"البقرة: 246","question":"ما سرّ قول نبيهم ﴿هل عسيتم إن كتب عليكم القتال ألا تقاتلوا﴾ بـ﴿إن﴾؟","answer":"اختبر احتمال فرض ما يطلبونه قبل وقوعه، وكشف أن حماسة القول قد تنهار عند تحول الطلب إلى تكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص784، تحت البقرة: 246.","url":""}]},{"id":"s2-1244","number":1244,"surah":2,"verses":[246],"verseLabel":"البقرة: 246","question":"ما دلالة قولهم: ﴿وَقَدْ أُخْرِجْنَا مِنْ دِيَارِنَا وَأَبْنَائِنَا﴾، وجمعهم بين الديار والأبناء؟","answer":"جمعوا خسارة الوطن والأسرة ليقدموا أقوى دوافع القتال، فكأن الضرر أحاط بمكانهم ونسلهم معًا؛ ثم فضح التولي ضعف الدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص785، تحت البقرة: 246.","url":""}]},{"id":"s2-1245","number":1245,"surah":2,"verses":[246],"verseLabel":"البقرة: 246","question":"ما سرّ التعبير في قوله تعالى عن بني إسرائيل حين فُرض عليهم القتال: ﴿تَوَلَّوْا إِلَّا قَلِيلًا مِنْهُمْ﴾، دون أن يقال: «قعدوا»؟","answer":"﴿تولوا﴾ ترسم حركة الانصراف بعد أن كانوا هم الذين طلبوا القتال: كأنهم يديرون ظهورهم وينكصون حين جاء الجد. أما «قعدوا» فقد تصف مجرد ترك الخروج، ولا تحمل الصورة نفسها من الرجوع والتخلي بعد الطلب والوعد. لذلك اختير اللفظ الذي يجسد التناقض بين حماسة القول وفرار الفعل، ويجعل التوبيخ أوقع في نفس القارئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص787، تحت البقرة: 246، في مبحث إيثار ﴿تولوا﴾ على «قعدوا».","url":""}]},{"id":"s2-1246","number":1246,"surah":2,"verses":[246],"verseLabel":"البقرة: 246","question":"ما دلالة قولهم: ﴿وَقَدْ أُخْرِجْنَا مِنْ دِيَارِنَا وَأَبْنَائِنَا﴾، ولم يقولوا: «من بيوتنا» أو «مساكننا»؟","answer":"الدار أوسع من البيت والمسكن؛ فهي تشمل الأرض وما عليها من بناء، وقد تطلق على البلدة والوطن كله، أما البيت والمسكن فيلحظان موضع الإقامة خاصة. لذلك صوّرت ﴿ديارنا﴾ أن العدو لم يطردهم من مبانٍ مفردة فحسب، بل اقتلعهم من كامل أرضهم ومجال حياتهم، فكان اللفظ أبلغ في بيان شدة ما يدفعهم ــ في دعواهم ــ إلى القتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص784، تحت البقرة: 246، في مبحث إيثار ﴿الديار﴾ على البيت والمسكن والمنزل.","url":""}]},{"id":"s2-1247","number":1247,"surah":2,"verses":[246],"verseLabel":"البقرة: 246","question":"لماذا عاد أسلوب ﴿أَلَمْ تَرَ﴾ في قصة الملأ من بني إسرائيل؟","answer":"ليستحضر القارئ تكرار نمط بشري: يطلب الناس التكليف بحماسة ثم يتراجعون عند وقوعه. والرؤية القلبية تجعل القصة مرآة للحاضر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص772–777، تحت البقرة: 246، في الاستفهام.","url":""}]},{"id":"s2-1248","number":1248,"surah":2,"verses":[246],"verseLabel":"البقرة: 246","question":"ما دلالة قولهم: ﴿ابْعَثْ لَنَا مَلِكًا نُقَاتِلْ فِي سَبِيلِ اللَّهِ﴾؟","answer":"طلبوا قائدًا يجمعهم وربطوا القتال بسبيل الله، لكن جواب النبي اختبر صدق الشعار قبل منحهم ما طلبوا؛ فليس حسن العبارة دليل ثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص776–781، تحت البقرة: 246، في الطلب والغاية.","url":""}]},{"id":"s2-1249","number":1249,"surah":2,"verses":[246],"verseLabel":"البقرة: 246","question":"لماذا ختم بقوله: ﴿وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ﴾ بعد تولي أكثرهم؟","answer":"سمى التراجع ظلمًا لأنه نقض لطلبهم وترك للمستضعفين بعد ادعاء نصرتهم، والعلم الإلهي يميز القلة الصادقة من الجمهور المتحمس قولًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص784–788، تحت البقرة: 246، في الاستثناء والخاتمة.","url":""}]},{"id":"s2-1250","number":1250,"surah":2,"verses":[247],"verseLabel":"البقرة: 247","question":"لماذا اعترضوا على ملك طالوت بفقره، فجاء الجواب بزيادة العلم والجسم لا المال؟","answer":"قلب معيار القيادة من النسب والثراء إلى علم يحسن التدبير وجسم يقدر على التنفيذ، وقدم العلم لأنه قائد القوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص790–796، تحت البقرة: 247.","url":""}]},{"id":"s2-1251","number":1251,"surah":2,"verses":[247],"verseLabel":"البقرة: 247","question":"ما سرّ قول نبيهم: ﴿إِنَّ اللَّهَ قَدْ بَعَثَ لَكُمْ طَالُوتَ مَلِكًا﴾، ولم يقل: «أرسل لكم طالوت»؟","answer":"مادة ﴿بعث﴾ تتضمن الإثارة والتحريك والإخراج بعد خمول، بخلاف الإرسال الذي يغلب فيه معنى الانطلاق برفق وسهولة. وكان بنو إسرائيل قد ذلوا وتفرقت جماعتهم واستباح العدو أرضهم؛ فاحتاجوا إلى قائد يثير فيهم العزم وينفض عنهم غبار الهوان، لا إلى مجرد شخص يُرسَل إليهم. لذلك جسّد ﴿بعث﴾ الوظيفة المطلوبة من طالوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص793–794، تحت البقرة: 247، في مبحث إيثار ﴿بعث﴾ على «أرسل».","url":""}]},{"id":"s2-1252","number":1252,"surah":2,"verses":[247],"verseLabel":"البقرة: 247","question":"لماذا قدّم الله العلم على قوة الجسم في وصف طالوت: ﴿وَزَادَهُ بَسْطَةً فِي الْعِلْمِ وَالْجِسْمِ﴾، مع أن قيادة الحرب تبدو أحوج إلى القوة البدنية؟","answer":"قُدّم العلم لإظهار أنه الأساس في القيادة؛ فالقائد يحتاج أولًا إلى معرفة ما يصلح الرعية وتدبير الطريق والحرب، ثم تأتي القوة أداةً تنفذ ذلك العلم. والقوة إذا لم يوجّهها علم قد تدمر صاحبها ومن يقودهم؛ لذلك نبّه الترتيب إلى أن الفضيلة العقلية أرفع وأحكم قيادةً من الفضيلة الجسمانية، مع الحاجة إليهما معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص794–795، تحت البقرة: 247، في مبحث تقديم العلم على الجسم.","url":""}]},{"id":"s2-1253","number":1253,"surah":2,"verses":[247],"verseLabel":"البقرة: 247","question":"اعترض بنو إسرائيل بأن طالوت ﴿لَمْ يُؤْتَ سَعَةً مِنَ الْمَالِ﴾؛ فلماذا لم يرد نبيهم بذكر ماله، وإنما قال: ﴿وَزَادَهُ بَسْطَةً فِي الْعِلْمِ وَالْجِسْمِ﴾؟","answer":"تجاهل الجواب معيارهم؛ لأن الغنى الشخصي ليس شرطًا لصلاح الحاكم. المال الذي تقوم به المملكة تجلبه الرعية ويكون في بيت مالها، أما ما لا يُستغنى عنه في القائد فهو علم يحسن به التدبير وقوة يقدر بها على التنفيذ والنصر. فكان الرد تصحيحًا لمقياسهم نفسه: أهلية القيادة لا تُشترى بالثروة، بل تقوم على الكفاءة التي اختاره الله لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص795، تحت البقرة: 247، في مبحث العدول عن الإجابة عن سعة المال إلى العلم والجسم.","url":""}]},{"id":"s2-1254","number":1254,"surah":2,"verses":[247],"verseLabel":"البقرة: 247","question":"ما سرّ قول نبيهم: ﴿إِنَّ اللَّهَ قَدْ بَعَثَ لَكُمْ طَالُوتَ مَلِكًا﴾؟","answer":"قدم اسم الله وأكد الخبر بـ﴿إن﴾ و﴿قد﴾ ليقرر أن الاختيار إلهي لا اقتراح بشري، وأن الملك بعث لمصلحتهم ولو خالف أهواءهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص789–795، تحت البقرة: 247، في التوكيد والتقديم.","url":""}]},{"id":"s2-1255","number":1255,"surah":2,"verses":[247],"verseLabel":"البقرة: 247","question":"لماذا اعترضوا بقولهم: ﴿أَنَّى يَكُونُ لَهُ الْمُلْكُ عَلَيْنَا﴾؟","answer":"﴿أنى﴾ تستبعد استحقاقه من كل وجه، وكشف قولهم ﴿علينا﴾ أن الاعتراض مس كبرهم الشخصي لا مجرد بحث عن الأصلح.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص793–800، تحت البقرة: 247، في الاستفهام والضمير.","url":""}]},{"id":"s2-1256","number":1256,"surah":2,"verses":[247],"verseLabel":"البقرة: 247","question":"لماذا جعلوا معيار الملك: ﴿وَنَحْنُ أَحَقُّ بِالْمُلْكِ مِنْهُ وَلَمْ يُؤْتَ سَعَةً مِنَ الْمَالِ﴾؟","answer":"قاسوا القيادة بالنسب والثراء، فجمع اعتراضهم بين تزكية النفس واحتقار الفقير. والسياق يمهد لقلب هذا المقياس بالعلم والجسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص798–804، تحت البقرة: 247، في التفضيل والتعليل.","url":""}]},{"id":"s2-1257","number":1257,"surah":2,"verses":[247],"verseLabel":"البقرة: 247","question":"لماذا كان الجواب: ﴿إِنَّ اللَّهَ اصْطَفَاهُ عَلَيْكُمْ وَزَادَهُ بَسْطَةً فِي الْعِلْمِ وَالْجِسْمِ﴾؟","answer":"قابل المال العارض بمؤهلي القيادة الحقيقيين: علم يحسن التدبير وقوة تنفذ وتحمي، وقدم العلم لأنه قائد القوة. والاصطفاء الإلهي أصل يسبق المزايا المكتسبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص802–810، تحت البقرة: 247، في المقابلة وترتيب الصفات.","url":""}]},{"id":"s2-1258","number":1258,"surah":2,"verses":[247],"verseLabel":"البقرة: 247","question":"لماذا ختم بـ﴿وَاللَّهُ وَاسِعٌ عَلِيمٌ﴾؟","answer":"ملكه واسع يعطيه من يشاء ولا تحصره مقاييس الناس، وعلمه يضعه عند الأقدر لا الأغنى. الاسمان يجيبان اعتراضهم على الاختيار والرزق معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص808–نهاية المجلد، تحت البقرة: 247، في الفاصلة.","url":""}]},{"id":"s2-1259","number":1259,"surah":2,"verses":[248],"verseLabel":"البقرة: 248","question":"لماذا كانت علامة مُلك طالوت رجوع التابوت؟","answer":"لأنه رمز لتراث نبوتهم وسكينتهم، فرجوعه على وجه معجز يثبت اختيار الله لطالوت بما يمس ذاكرتهم الدينية مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص10–18، تحت البقرة: 248.","url":""}]},{"id":"s2-1260","number":1260,"surah":2,"verses":[248],"verseLabel":"البقرة: 248","question":"ما سرّ التعبير في قوله تعالى: ﴿أن يأتيكم التابوت﴾ بالإتيان لا المجيء؟","answer":"الإتيان أعم وقد يلحظ وصول الشيء وحصوله لهم، وهو الأنسب لتابوت تحمله الملائكة حتى يبلغهم دون حركة ذاتية منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص14، تحت البقرة: 248.","url":""}]},{"id":"s2-1261","number":1261,"surah":2,"verses":[248],"verseLabel":"البقرة: 248","question":"ما سرّ التعبير في قوله تعالى: ﴿إن كنتم مؤمنين﴾ بـ﴿إن﴾ مع مطالبتهم بالآية؟","answer":"تعريض باختبار حقيقة إيمانهم: إن كانوا مصدقين بالله ونبيهم فهذه الآية كافية، وإلا فالمشكلة في العناد لا الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص18، تحت البقرة: 248.","url":""}]},{"id":"s2-1262","number":1262,"surah":2,"verses":[248],"verseLabel":"البقرة: 248","question":"ما سرّ التعبير في قوله تعالى عن التابوت: ﴿فِيهِ سَكِينَةٌ مِنْ رَبِّكُمْ﴾، دون أن يقال: «من الله»؟","answer":"لفظ ﴿الرب﴾ يبرز معنى التدبير والرعاية والقيام بمصالح المربوب، وإضافته إليهم في ﴿ربكم﴾ تشعرهم بأن الذي اختار طالوت هو نفسه المتولي لأمرهم والمصلح لشأنهم. فناسب مقامَ اضطرابهم واعتراضهم أن يذكَّروا بربوبية الله الخاصة لهم؛ لتطمئن قلوبهم إلى اختياره وتدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص14–15، تحت البقرة: 248، في مبحث إيثار لفظ الرب وإضافته إلى المخاطبين.","url":""}]},{"id":"s2-1263","number":1263,"surah":2,"verses":[248],"verseLabel":"البقرة: 248","question":"ما سرّ التعبير في قوله تعالى: ﴿فِيهِ سَكِينَةٌ مِنْ رَبِّكُمْ وَبَقِيَّةٌ مِمَّا تَرَكَ آلُ مُوسَى وَآلُ هَارُونَ﴾؟","answer":"جمع أثرًا معنويًا هو السكينة وآثارًا مادية من ميراث النبوة؛ ليخاطب القلب والحس معًا، وأضاف السكينة إلى ربهم ليجعل الطمأنينة عطاءً منه لا خاصية في الصندوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص12–16، تحت البقرة: 248، في الجمع والإضافة.","url":""}]},{"id":"s2-1264","number":1264,"surah":2,"verses":[248],"verseLabel":"البقرة: 248","question":"ما سرّ التعبير في قوله تعالى: ﴿تَحْمِلُهُ الْمَلَائِكَةُ﴾؟","answer":"مجيء التابوت محمولًا بالملائكة يقطع احتمال المصادفة أو الحيلة البشرية، ويجعل العلامة في مستوى الاعتراض على اختيار الله لطالوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص14–18، تحت البقرة: 248، في دلالة الجملة.","url":""}]},{"id":"s2-1265","number":1265,"surah":2,"verses":[249],"verseLabel":"البقرة: 249","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما فصل طالوت بالجنود﴾ لا: خرج بالجيش؟","answer":"الفصل يصور مفارقة المكان وانفصال الجيش عمن خلفه في حركة منظمة، ويمهد لتمييز آخر يقع عند النهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص27–29، تحت البقرة: 249.","url":""}]},{"id":"s2-1266","number":1266,"surah":2,"verses":[249],"verseLabel":"البقرة: 249","question":"لماذا كان اختبار الجيش بنهر في طريق المعركة؟","answer":"كشف قدرتهم على ضبط شهوة عاجلة تحت العطش؛ فمن عجز عن أمر ماء يسير كان أبعد عن الثبات أمام العدو.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص19–39، تحت البقرة: 249.","url":""}]},{"id":"s2-1267","number":1267,"surah":2,"verses":[249],"verseLabel":"البقرة: 249","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن لم يطعمه فإنه مني﴾، دون أن يقال: ومن لم يشربه؟","answer":"الطعم أعم من الشرب ويشعر بأدنى ذوق، فشدد في الاختبار: من لم يذقه إلا الغرفة المأذونة فهو من صفوة الجيش.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص31، تحت البقرة: 249.","url":""}]},{"id":"s2-1268","number":1268,"surah":2,"verses":[249],"verseLabel":"البقرة: 249","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما جاوزه هو والذين آمنوا معه﴾ بصيغة جاوز لا جاز؟","answer":"جاوز تدل على تعدية الحد وتركه وراءه، فتصور عبور النهر والاختبار معًا، لا مجرد المرور داخله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص34–35، تحت البقرة: 249.","url":""}]},{"id":"s2-1269","number":1269,"surah":2,"verses":[249],"verseLabel":"البقرة: 249","question":"لماذا عبّر عن يقينهم بالنصر بقوله ﴿الذين يظنون أنهم ملاقو الله﴾؟","answer":"الظن هنا يقين راجح يحكم السلوك، واستحضار لقاء الله هو الذي صغر في أعينهم فرق العدد وأطلق رجاء النصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص24–36، تحت البقرة: 249.","url":""}]},{"id":"s2-1270","number":1270,"surah":2,"verses":[249],"verseLabel":"البقرة: 249","question":"ما دلالة قول المؤمنين: ﴿كَمْ مِنْ فِئَةٍ قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةً﴾، ولم يقولوا: «انتصرت على فئة كثيرة»؟","answer":"﴿غلبت﴾ تكسر التوقع مباشرة؛ لأن المألوف أن تغلب الكثرةُ القلةَ، فتقرر أن الغلبة لا تتبع العدد بذاته بل أسبابًا مادية ومعنوية يتصدرها الإيمان والتأييد الإلهي. أما «انتصرت» فقد توهم أن النصر جاءهم من غير مباشرة أسباب المقاومة؛ فلفظ الغلبة يجمع العمل والمواجهة والنتيجة غير المتوقعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص37–38، تحت البقرة: 249، في مبحث إيثار ﴿غلبت﴾.","url":""}]},{"id":"s2-1271","number":1271,"surah":2,"verses":[249],"verseLabel":"البقرة: 249","question":"لماذا استثنى ﴿مَنِ اغْتَرَفَ غُرْفَةً بِيَدِهِ﴾؟","answer":"أباح قدر الضرورة الذي يعين على المسير ومنع الاسترسال في الشهوة؛ وتصغير الفعل إلى غرفة باليد يرسم حدًا محسوسًا بين الانضباط والانقياد للعطش.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص26–32، تحت البقرة: 249، في الاستثناء والتنكير.","url":""}]},{"id":"s2-1272","number":1272,"surah":2,"verses":[249],"verseLabel":"البقرة: 249","question":"ما دلالة قول القلة: ﴿كَمْ مِنْ فِئَةٍ قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةً بِإِذْنِ اللَّهِ﴾؟","answer":"قابلوا حساب العدد بسنّة تتكرر: النصر ليس نتاج الكثرة وحدها. و﴿كم﴾ الخبرية تستحضر شواهد كثيرة، بينما ﴿بإذن الله﴾ تمنع الثقة بالنفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص33–39، تحت البقرة: 249، في ﴿كم﴾ والمقابلة.","url":""}]},{"id":"s2-1273","number":1273,"surah":2,"verses":[250],"verseLabel":"البقرة: 250","question":"ما دلالة قول المؤمنين ﴿أفرغ علينا صبرًا﴾ فصوّر الصبر ماءً يُفرغ؟","answer":"طلبوا صبرًا غامرًا ينصب عليهم حتى يملأ القلب والجوارح، لا جرعة محدودة من الشجاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص40–45، تحت البقرة: 250.","url":""}]},{"id":"s2-1274","number":1274,"surah":2,"verses":[250],"verseLabel":"البقرة: 250","question":"لماذا عبّر عن دعائهم بـ﴿قالوا﴾ لا: دعوا؟","answer":"أظهر ألفاظهم نفسها لتصبح دعاءً يتعلمه المؤمنون، و﴿قالوا﴾ تستحضر اجتماع أصواتهم عند البروز للعدو.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص43، تحت البقرة: 250.","url":""}]},{"id":"s2-1275","number":1275,"surah":2,"verses":[250],"verseLabel":"البقرة: 250","question":"لماذا رتبوا الدعاء: الصبر، ثم ثبات الأقدام، ثم النصر؟","answer":"بدأوا بالقوة الباطنة، ثم أثرها الجسدي في الميدان، ثم الثمرة الخارجية؛ فالنصر في تصورهم نتيجة إعداد القلب والعمل، لا أمنية منفصلة عن الأسباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص41–44، تحت البقرة: 250، في ترتيب الدعاء.","url":""}]},{"id":"s2-1276","number":1276,"surah":2,"verses":[251],"verseLabel":"البقرة: 251","question":"ما سرّ التعبير في قوله تعالى: ﴿ولولا دفع الله الناس بعضهم ببعض لفسدت الأرض﴾ لا: لفسد الكافرون؟","answer":"استبداد المعتدي يفسد نظام الأرض ودينها وعمرانها، والدفع يحمي الناس جميعًا لا طائفة واحدة؛ لذلك اتسعت النتيجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص45–53، تحت البقرة: 251.","url":""}]},{"id":"s2-1277","number":1277,"surah":2,"verses":[251],"verseLabel":"البقرة: 251","question":"لماذا ختم بقوله ﴿ولكن الله ذو فضل على العالمين﴾ لا المؤمنين؟","answer":"سنة الدفع تحفظ العالم من استيلاء الفساد، فينتفع بها مؤمن وكافر، وإن قام المؤمنون بوظيفة المقاومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص52، تحت البقرة: 251.","url":""}]},{"id":"s2-1278","number":1278,"surah":2,"verses":[251],"verseLabel":"البقرة: 251","question":"ما سرّ التعبير في قوله تعالى عن داود: ﴿وَآتَاهُ اللَّهُ الْمُلْكَ وَالْحِكْمَةَ﴾ فقدم الملك على الحكمة؟","answer":"رتب السياق النعمتين بحسب انتقال داود في مراتب الفضل: من الملك، وهو شريف، إلى الحكمة والنبوة، وهي أشرف. كما أن الملك كان محور القصة منذ طلب بني إسرائيل ملكًا واعتراضهم على طالوت، فناسب تقديم ما تعلقت به عنايتهم، ثم الارتقاء إلى النعمة الأعلى التي تضبط الملك وتمنعه من الطغيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص48–49، تحت البقرة: 251، في مبحث تقديم الملك على الحكمة.","url":""}]},{"id":"s2-1279","number":1279,"surah":2,"verses":[251],"verseLabel":"البقرة: 251","question":"ما سرّ التعبير في قوله تعالى: ﴿فَهَزَمُوهُمْ بِإِذْنِ اللَّهِ﴾ قبل ذكر قتل داود جالوت؟","answer":"نسب النصر أولًا إلى إذن الله وإلى الجماعة، ثم أبرز البطولة الفردية؛ حتى لا يطغى اسم البطل على مصدر النصر أو جهد الجيش.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص45–48، تحت البقرة: 251، في الترتيب والقيد.","url":""}]},{"id":"s2-1280","number":1280,"surah":2,"verses":[251],"verseLabel":"البقرة: 251","question":"لماذا جمع لداود بين ﴿الْمُلْكَ وَالْحِكْمَةَ﴾؟","answer":"الملك يمنحه سلطة التنفيذ والحكمة تمنحه العلم الذي يهدي القوة؛ فاجتماعهما صورة القيادة الكاملة، بعد أن أثبتت المعركة شجاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص47–50، تحت البقرة: 251، في الجمع.","url":""}]},{"id":"s2-1281","number":1281,"surah":2,"verses":[252],"verseLabel":"البقرة: 252","question":"ما سرّ التعبير في قوله تعالى: ﴿تلك آيات الله﴾ باسم الإشارة للبعيد لا ﴿هذه﴾؟","answer":"البعد لتعظيم منزلة الآيات والقصص، أو للإشارة إلى الوقائع الماضية التي أحضرها الوحي كأنها مشاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص55، تحت البقرة: 252.","url":""}]},{"id":"s2-1282","number":1282,"surah":2,"verses":[252],"verseLabel":"البقرة: 252","question":"ما سرّ التعبير في قوله تعالى: ﴿تِلْكَ آيَاتُ اللَّهِ نَتْلُوهَا عَلَيْكَ بِالْحَقِّ﴾ بعد القصة؟","answer":"أشار إلى الوقائع البعيدة كأنها حاضرة، وقرر أن تلاوتها حق لا أسطورة؛ فالقصة برهان نبوة وعبرة واقعية في آن واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص53–56، تحت البقرة: 252، في الإشارة والالتفات.","url":""}]},{"id":"s2-1283","number":1283,"surah":2,"verses":[252],"verseLabel":"البقرة: 252","question":"لماذا ختم بـ﴿وَإِنَّكَ لَمِنَ الْمُرْسَلِينَ﴾؟","answer":"علم النبي بهذه التفاصيل ووحدة سنن الرسالات شاهد على إرساله، وجمعت ﴿إن﴾ واللام و﴿من﴾ توكيدًا يضعه في سلسلة الرسل لا خبرًا منفردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص56–59، تحت البقرة: 252، في التوكيد.","url":""}]},{"id":"s2-1284","number":1284,"surah":2,"verses":[253],"verseLabel":"البقرة: 253","question":"لماذا فضّل الله بعض الرسل على بعض مع النهي عن التفريق بينهم؟","answer":"النهي عن التفريق في أصل التصديق والقبول، أما التفضيل فهو تفاوت من الله في الخصائص والمعجزات والمقامات؛ فلا تعارض بين الإيمان بالجميع ومراتبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص60–77، تحت البقرة: 253.","url":""}]},{"id":"s2-1285","number":1285,"surah":2,"verses":[253],"verseLabel":"البقرة: 253","question":"ما سرّ التعبير في قوله تعالى: ﴿ورفع بعضهم درجات﴾ لا منازل؟","answer":"الدرجات توحي بمراتب متصاعدة متعددة بعضها فوق بعض، فناسبت تفاوت الفضائل الإلهية أكثر من مكان إقامة ثابت.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص69، تحت البقرة: 253.","url":""}]},{"id":"s2-1286","number":1286,"surah":2,"verses":[253],"verseLabel":"البقرة: 253","question":"ما سرّ التعبير بقوله تعالى: ﴿مِنْهُمْ مَنْ كَلَّمَ اللَّهُ﴾ دون التصريح باسم موسى؟","answer":"أبرز المنقبة نفسها وجعلها قسمًا مميزًا من أقسام التفضيل، مع شهرة صاحبها؛ فالحذف يوجه النظر إلى عطاء الله لا إلى مجرد الاسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص64–70، تحت البقرة: 253، في الإبهام والحذف.","url":""}]},{"id":"s2-1287","number":1287,"surah":2,"verses":[253],"verseLabel":"البقرة: 253","question":"لماذا خص عيسى بالبينات والتأييد بروح القدس؟","answer":"لأن رسالته أحاطت بها المعجزات والإنكار، فناسب ذكر الحجج الظاهرة والمدد الذي ثبته. والتخصيص مثال للتفضيل لا حصر لسائر فضائل الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص68–72، تحت البقرة: 253، في التخصيص.","url":""}]},{"id":"s2-1288","number":1288,"surah":2,"verses":[253],"verseLabel":"البقرة: 253","question":"لماذا تكرر: ﴿وَلَوْ شَاءَ اللَّهُ مَا اقْتَتَلُوا﴾؟","answer":"الأول يقرر إمكان منع الاقتتال بعد مجيء البينات، والثاني يعيد الحقيقة بعد بيان اختلافهم ليقطع توهم أن اختلافهم أفلت من المشيئة؛ والتكرار يحيط السبب والنتيجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص71–76، تحت البقرة: 253، في التكرار.","url":""}]},{"id":"s2-1289","number":1289,"surah":2,"verses":[254],"verseLabel":"البقرة: 254","question":"لماذا ذُكر الإنفاق قبل يوم ﴿لا بيع فيه ولا خلة ولا شفاعة﴾؟","answer":"دعاهم إلى بذل المال في زمن يمكن فيه شراء الآخرة بالعمل قبل يوم لا تنفع فيه وسائل التدارك الدنيوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص77–86، تحت البقرة: 254.","url":""}]},{"id":"s2-1290","number":1290,"surah":2,"verses":[254],"verseLabel":"البقرة: 254","question":"لماذا ناداهم بوصف الإيمان قبل الأمر بالإنفاق؟","answer":"استدعى ما في الإيمان من تصديق ووعد ليحرك البذل، فالنداء يذكرهم أن الاستجابة ليست ضريبة غريبة بل ثمرة هويتهم التي اختاروها.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص77–80، تحت البقرة: 254، في النداء.","url":""}]},{"id":"s2-1291","number":1291,"surah":2,"verses":[254],"verseLabel":"البقرة: 254","question":"ما سرّ التعبير في قوله تعالى: ﴿مِمَّا رَزَقْنَاكُمْ﴾؟","answer":"لم يطلب كل المال، وذكّر أن المبذول بعض رزق وهبه الله أصلًا؛ فـ﴿من﴾ للتبعيض والإضافة إلى الرزق تعالجان الشح وشعور الملك المطلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص79–82، تحت البقرة: 254، في التبعيض والإسناد.","url":""}]},{"id":"s2-1292","number":1292,"surah":2,"verses":[254],"verseLabel":"البقرة: 254","question":"لماذا وصف اليوم بأنه لا بيع فيه ولا خلة ولا شفاعة؟","answer":"أغلق أبواب النجاة التي يركن إليها الإنسان في الدنيا: شراء الخلاص، وصداقة تنصر، وواسطة بغير إذن؛ ليجعل زمن العمل الآن قبل يوم الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص81–85، تحت البقرة: 254، في التعداد والنفي.","url":""}]},{"id":"s2-1293","number":1293,"surah":2,"verses":[255],"verseLabel":"البقرة: 255","question":"لماذا افتُتحت آية الكرسي بـ﴿الله لا إله إلا هو﴾؟","answer":"بدأت بالاسم الجامع وقصر العبادة فيه، ثم جاءت صفات الحياة والقيومية والملك والعلم والقدرة براهين على هذا التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص86–92، تحت البقرة: 255.","url":""}]},{"id":"s2-1294","number":1294,"surah":2,"verses":[255],"verseLabel":"البقرة: 255","question":"لماذا جمع بين ﴿الحي القيوم﴾ تحديدًا؟","answer":"الحي كامل في ذاته، والقيوم قائم بنفسه مقيم لغيره؛ فاجتمع كمال الوجود وكمال تدبير كل موجود.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص86–106، تحت البقرة: 255.","url":""}]},{"id":"s2-1295","number":1295,"surah":2,"verses":[255],"verseLabel":"البقرة: 255","question":"ما سرّ التعبير في قوله تعالى: ﴿لا تأخذه سنة ولا نوم﴾ فقدم السِّنة على النوم؟","answer":"نفى أخف مقدمات النوم ثم نفى النوم الكامل، فإذا لم تلحقه غفلة يسيرة فانتفاء الاستغراق أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص92–97، تحت البقرة: 255.","url":""}]},{"id":"s2-1296","number":1296,"surah":2,"verses":[255],"verseLabel":"البقرة: 255","question":"ما سرّ التعبير في قوله تعالى: ﴿له ما في السماوات وما في الأرض﴾ بـ﴿ما﴾ لا ﴿من﴾؟","answer":"﴿ما﴾ أعم فتشمل العقلاء وغيرهم وكل الأعيان والقوى، فيستوعب ملكه كل ما في الكون دون استثناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص97، تحت البقرة: 255.","url":""}]},{"id":"s2-1297","number":1297,"surah":2,"verses":[255],"verseLabel":"البقرة: 255","question":"ما سرّ التعبير في قوله تعالى: ﴿وسع كرسيه السماوات والأرض﴾، دون أن يقال: ملكه أو علمه؟","answer":"الصورة المحسوسة للكرسي توحي بعظمة السلطان وسعة ما دونه، مع تنزيه الله عن مشابهة الأجسام؛ وهي أوقع في النفس من عبارة مجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص97–104، تحت البقرة: 255.","url":""}]},{"id":"s2-1298","number":1298,"surah":2,"verses":[255],"verseLabel":"البقرة: 255","question":"لماذا ثنّى الضمير في ﴿ولا يؤوده حفظهما﴾؟","answer":"يعود إلى السماوات والأرض المذكورتين، فجمع حفظ العالم العلوي والسفلي في ضميرين وأثبت أنه لا يثقله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص104، تحت البقرة: 255.","url":""}]},{"id":"s2-1299","number":1299,"surah":2,"verses":[255],"verseLabel":"البقرة: 255","question":"لماذا ختمت آية الكرسي بـ﴿العلي العظيم﴾؟","answer":"بعد شمول الملك والعلم والحفظ ختم بعلوه عن كل نقص وعظمة لا يقاس بها شيء، فتلخصت صفات الآية في الاسمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص104–106، تحت البقرة: 255.","url":""}]},{"id":"s2-1300","number":1300,"surah":2,"verses":[255],"verseLabel":"البقرة: 255","question":"ما سرّ التعبير في قوله تعالى في آية الكرسي: ﴿مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ﴾ بصيغة السؤال، دون أن يقال مباشرة: «لا يشفع عنده أحد إلا بإذنه»؟","answer":"الاستفهام هنا يتضمن النفي والإنكار، لكنه أبلغ من النفي المباشر؛ لأنه يستدعي من السامع أن يبحث عن الجواب ثم يقر بنفسه أنه لا أحد يملك الشفاعة استقلالًا. وبعد تقرير ملك الله للسماوات والأرض جاءت الصيغة لتبطل اعتقاد من يتوهم شفيعًا يفرض إرادته على الله؛ فلا تقع شفاعة إلا بعد إذنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص96–98، تحت البقرة: 255، في مبحث أسلوب ﴿من ذا﴾ والاستفهام المتضمن النفي.","url":""}]},{"id":"s2-1301","number":1301,"surah":2,"verses":[255],"verseLabel":"البقرة: 255","question":"ما سرّ التعبير في قوله تعالى: ﴿يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ﴾؟","answer":"كناية تستوعب ما تقدم وما تأخر وما ظهر وما خفي، فتضع علم الخلق المحدود داخل علم شامل لا يغيب عنه اتجاه أو زمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص98–101، تحت البقرة: 255، في الكناية والطباق.","url":""}]},{"id":"s2-1302","number":1302,"surah":2,"verses":[256],"verseLabel":"البقرة: 256","question":"ما سرّ التعبير في قوله تعالى: ﴿لا إكراه في الدين﴾، دون أن يقال: في الإسلام؟","answer":"الدين أعم فيشمل أصل الاعتقاد الذي لا يصنعه الإكراه، ويقرر قاعدة العلاقة بين الإيمان القلبي والاختيار بعد وضوح الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص111، تحت البقرة: 256.","url":""}]},{"id":"s2-1303","number":1303,"surah":2,"verses":[256],"verseLabel":"البقرة: 256","question":"ما سرّ التعبير في قوله تعالى: ﴿قد تبين الرشد من الغي﴾ قبل ذكر الكفر بالطاغوت والإيمان بالله؟","answer":"قرر وضوح الطريقين أولًا ثم بنى عليه الاختيار العملي: رفض الطاغوت والإيمان بالله؛ فالموقف ثمرة البيان لا قسر.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص106–117، تحت البقرة: 256.","url":""}]},{"id":"s2-1304","number":1304,"surah":2,"verses":[256],"verseLabel":"البقرة: 256","question":"ما سرّ التعبير في قوله تعالى: ﴿فقد استمسك بالعروة الوثقى﴾ فصوّر الإيمان بعروة؟","answer":"شبه المؤمن بمن قبض على أقوى مقبض ينقذه من السقوط، فجمع فعل الاستمساك وأمان الوسيلة التي لا تنفصم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص115، تحت البقرة: 256.","url":""}]},{"id":"s2-1305","number":1305,"surah":2,"verses":[256],"verseLabel":"البقرة: 256","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا إِكْرَاهَ فِي الدِّينِ﴾ بعد آية الكرسي؟","answer":"بعد ظهور براهين الإله الحق لا يحتاج الإيمان إلى إكراه؛ فالدين تصديق قلبي لا يصنعه الضغط، والآية التالية تبين أن الرشد قد انفصل عن الغي.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص106–110، تحت البقرة: 256، في اتصال الآيتين.","url":""}]},{"id":"s2-1306","number":1306,"surah":2,"verses":[256],"verseLabel":"البقرة: 256","question":"ما سرّ التعبير في قوله تعالى: ﴿قَدْ تَبَيَّنَ الرُّشْدُ مِنَ الْغَيِّ﴾؟","answer":"علل نفي الإكراه بوضوح الطريقين، واختار ﴿تبين﴾ لتصوير انفصالهما بعد قيام الدليل؛ فالمطلوب اختيار واع لا استجابة قسرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص109–113، تحت البقرة: 256، في التعليل والطباق.","url":""}]},{"id":"s2-1307","number":1307,"surah":2,"verses":[256],"verseLabel":"البقرة: 256","question":"ما سرّ تقديم الكفر بالطاغوت على الإيمان بالله؟","answer":"لأن التوحيد يتضمن تخليًا عن كل معبود وسلطان باطل قبل التحلي بالإيمان؛ فنفى الزيف ثم أثبت الحق، كما في كلمة التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص111–114، تحت البقرة: 256، في التقديم.","url":""}]},{"id":"s2-1308","number":1308,"surah":2,"verses":[257],"verseLabel":"البقرة: 257","question":"لماذا أفرد النور وجمع الظلمات في ﴿يخرجهم من الظلمات إلى النور﴾؟","answer":"الحق واحد متسق، أما الباطل فطرق متشعبة من جهل وشهوة وشبهة؛ فالإفراد والجمع يصوران وحدة الهدى وتفرق الضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص117–134، تحت البقرة: 257.","url":""}]},{"id":"s2-1309","number":1309,"surah":2,"verses":[257],"verseLabel":"البقرة: 257","question":"ما سرّ التعبير في قوله تعالى: ﴿النور﴾ لا الضياء؟","answer":"النور أعم وألطف ويستعمل للهداية التي تكشف الطريق وتطمئن القلب، أما الضياء فيبرز قوة الإشراق والحرارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص124، تحت البقرة: 257.","url":""}]},{"id":"s2-1310","number":1310,"surah":2,"verses":[257],"verseLabel":"البقرة: 257","question":"ما سرّ التعبير للمؤمنين بقوله تعالى: ﴿يُخْرِجُهُمْ مِنَ الظُّلُمَاتِ إِلَى النُّورِ﴾ مع أنهم مؤمنون؟","answer":"لأن ولاية الله تجدد نقلهم من بقايا الجهل والهوى إلى مراتب الهداية، أو تصف أصل انتقالهم الذي به صاروا مؤمنين؛ والمضارع يشعر باستمرار الرعاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص120–126، تحت البقرة: 257، في المضارع.","url":""}]},{"id":"s2-1311","number":1311,"surah":2,"verses":[257],"verseLabel":"البقرة: 257","question":"ما سرّ التعبير في قوله تعالى في الكافرين: ﴿أَوْلِيَاؤُهُمُ الطَّاغُوتُ﴾ مع إفراد لفظ الطاغوت؟","answer":"الطاغوت اسم جنس يجمع رؤوس الباطل، فصح الإخبار به عن أولياء متعددين؛ ووحدة الاسم تكشف أن تنوعهم يرجع إلى أصل واحد هو تجاوز حد العبودية.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص124–129، تحت البقرة: 257، في المطابقة.","url":""}]},{"id":"s2-1312","number":1312,"surah":2,"verses":[257],"verseLabel":"البقرة: 257","question":"لماذا ختم الكافرين بـ﴿هُمْ فِيهَا خَالِدُونَ﴾؟","answer":"ضمير الفصل والتقديم يؤكدان اختصاص من مات على الكفر بالملازمة المذكورة، ويقابلان دوام ولاية الله للمؤمن بدوام عاقبة ولاية الطاغوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص128–133، تحت البقرة: 257، في التوكيد والمقابلة.","url":""}]},{"id":"s2-1313","number":1313,"surah":2,"verses":[258],"verseLabel":"البقرة: 258","question":"ما سرّ التعبير في قوله تعالى: ﴿ألم تر إلى الذي حاج إبراهيم﴾ لا: جادل إبراهيم؟","answer":"المحاجة مفاعلة بالحجة والبرهان، فتصف مقامًا ادعى فيه الخصم الدليل ورد عليه إبراهيم بدليل قاطع، لا جدلًا لفظيًا فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص140، تحت البقرة: 258.","url":""}]},{"id":"s2-1314","number":1314,"surah":2,"verses":[258],"verseLabel":"البقرة: 258","question":"ما سرّ التعبير في قوله تعالى: ﴿أن آتاه الله الملك﴾ فجعل النعمة سببًا لطغيانه؟","answer":"حمله الملك على الغرور بدل الشكر، فصارت النعمة في اختياره سبب المحاجة؛ والتعبير يفضح انقلاب العطاء إلى حجة على المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص141، تحت البقرة: 258.","url":""}]},{"id":"s2-1315","number":1315,"surah":2,"verses":[258],"verseLabel":"البقرة: 258","question":"لماذا انتقل إبراهيم من حجة الإحياء والإماتة إلى حجة الشمس؟","answer":"لما لبّس الملك بادعاء معنى شكلي للإحياء والإماتة نقله إبراهيم إلى آية كونية لا يستطيع تقليدها أو تحريف معناها، فبهت.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص134–149، تحت البقرة: 258.","url":""}]},{"id":"s2-1316","number":1316,"surah":2,"verses":[258],"verseLabel":"البقرة: 258","question":"ما سرّ التعبير في قوله تعالى: ﴿فَبُهِتَ الَّذِي كَفَرَ﴾ ولم يذكر جوابًا له؟","answer":"لأن الحجة أسقطت قدرته على الكلام، فكان صمته هو الجواب. ووصفه بالذي كفر يربط البهت بموقفه من الحق لا باسمه أو ملكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص143–148، تحت البقرة: 258، في الإيجاز والموصول.","url":""}]},{"id":"s2-1317","number":1317,"surah":2,"verses":[259],"verseLabel":"البقرة: 259","question":"ما سرّ التعبير في قوله تعالى: ﴿أو كالذي مر على قرية﴾ ولم يسمِّ الرجل ولا القرية؟","answer":"لأن العبرة في سؤال الإحياء والمشهد البرهاني، لا في الهوية والجغرافيا؛ فالإبهام يمنع انشغال القارئ بما لا يغير الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص149–172، تحت البقرة: 259.","url":""}]},{"id":"s2-1318","number":1318,"surah":2,"verses":[259],"verseLabel":"البقرة: 259","question":"لماذا سأل ﴿أنى يحيي هذه الله بعد موتها﴾ بـ﴿أنى﴾ لا كيف أو متى؟","answer":"﴿أنى﴾ تستفهم عن الجهة والكيفية مع استبعاد ظاهر، فتجمع دهشته أمام خراب شامل لا يسأل عن زمنه وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص157، تحت البقرة: 259.","url":""}]},{"id":"s2-1319","number":1319,"surah":2,"verses":[259],"verseLabel":"البقرة: 259","question":"ما سرّ التعبير في قوله تعالى: ﴿مائة عام﴾ لا مائة سنة؟","answer":"العام يلائم دورة زمنية كاملة وقد يستعمل في زمن الرخاء، وهنا يقابل حفظ الطعام وتغير الحمار؛ والتنويع العربي لا يغير العدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص160، تحت البقرة: 259.","url":""}]},{"id":"s2-1320","number":1320,"surah":2,"verses":[259],"verseLabel":"البقرة: 259","question":"لماذا حفظ الله طعامه وشرابه وأراه بِلَى حماره؟","answer":"جمع بجوار بعض قدرة الحفظ من التغير وقدرة الإماتة ثم التركيب والإحياء، ليعلم أن الله لا تحكمه سنة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص149–172، تحت البقرة: 259.","url":""}]},{"id":"s2-1321","number":1321,"surah":2,"verses":[259],"verseLabel":"البقرة: 259","question":"ما سرّ التعبير في قوله تعالى: ﴿أَوْ كَالَّذِي مَرَّ عَلَى قَرْيَةٍ﴾، دون أن يقال: «دخل قرية» أو «جاء إلى قرية»؟","answer":"﴿مرّ﴾ يدل على اجتياز سريع من غير قصد الإقامة؛ فالرجل اتخذ القرية طريقًا، ثم فاجأه الموت حيث لم يحتسب وبقي مائة عام. وفي اللفظ لمحة وعظية توافق القصة: الإنسان نفسه مارّ في الدنيا لا مقيم فيها، وقد يأتيه الموت في أثناء مروره؛ فجمعت الكلمة حركة الحدث وعبرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص153–154، تحت البقرة: 259، في مبحث إيثار الفعل ﴿مرّ﴾.","url":""}]},{"id":"s2-1322","number":1322,"surah":2,"verses":[259],"verseLabel":"البقرة: 259","question":"لماذا وصف القرية بأنها ﴿خَاوِيَةٌ عَلَى عُرُوشِهَا﴾؟","answer":"صورة تجعل السقوف ساقطة ثم الجدران خاوية فوقها، فتبلغ بالخراب منتهاه؛ ولهذا يشتد سؤال: كيف يحيي هذه الله بعد موتها؟","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص153–159، تحت البقرة: 259، في التصوير.","url":""}]},{"id":"s2-1323","number":1323,"surah":2,"verses":[259],"verseLabel":"البقرة: 259","question":"لماذا سأله الله: ﴿كَمْ لَبِثْتَ﴾ بعد أن أماته مئة عام؟","answer":"أراد أن يكشف محدودية إدراك الزمن عند الإنسان؛ ظنها يومًا أو بعض يوم، ثم واجهه بالحقيقة ليهيئه لرؤية آثار القدرة في الطعام والحمار وجسده.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص158–164، تحت البقرة: 259، في السؤال والجواب.","url":""}]},{"id":"s2-1324","number":1324,"surah":2,"verses":[259],"verseLabel":"البقرة: 259","question":"لماذا جمع له بين طعام لم يتغير وحمار صار عظامًا ثم أحياه؟","answer":"وضع بجوار بعض صورتين متعاكستين تحت القدرة نفسها: حفظ بلا تغير، وإماتة ثم تركيب وإحياء؛ ليرى أن الله لا تحكمه سنة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص163–171، تحت البقرة: 259، في المقابلة وتعدد الآيات.","url":""}]},{"id":"s2-1325","number":1325,"surah":2,"verses":[260],"verseLabel":"البقرة: 260","question":"ما سرّ دعاء إبراهيم باسم الربوبية في قوله: ﴿رَبِّ أَرِنِي كَيْفَ تُحْيِي الْمَوْتَى﴾؟","answer":"طلب تربية قلبه بالانتقال من علم الخبر إلى مشاهدة الكيفية، فناسب اسم الرب الذي يزيد عبده علمًا وطمأنينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص177، تحت البقرة: 260.","url":""}]},{"id":"s2-1326","number":1326,"surah":2,"verses":[260],"verseLabel":"البقرة: 260","question":"ما سرّ التعبير في قوله تعالى له ﴿أولم تؤمن﴾ مع علمه بإيمانه؟","answer":"ليظهر جوابه للأمة ويفصل بين طلب الطمأنينة والشك في القدرة؛ فالسؤال تعليمي تقريري لا استعلام عن مجهول.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص180–182، تحت البقرة: 260.","url":""}]},{"id":"s2-1327","number":1327,"surah":2,"verses":[260],"verseLabel":"البقرة: 260","question":"لماذا أجاب إبراهيم ﴿بلى ولكن ليطمئن قلبي﴾؟ أكان في قلبه شك؟","answer":"أثبت الإيمان أولًا، ثم طلب سكون القلب بمشاهدة ما علمه يقينًا؛ فالمعرفة درجات، والعيان يزيد الطمأنينة دون أن يسبقه كفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص180–188، تحت البقرة: 260.","url":""}]},{"id":"s2-1328","number":1328,"surah":2,"verses":[260],"verseLabel":"البقرة: 260","question":"لماذا اختيرت أربعة من الطير في تجربة الإحياء؟","answer":"العدد يحقق تنوع الأجزاء وتفرقها على جهات متعددة مع بقاء التجربة قابلة للمشاهدة والتمييز؛ والعبرة بجمع المتفرق لا بسر عددي لازم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص172–190، تحت البقرة: 260.","url":""}]},{"id":"s2-1329","number":1329,"surah":2,"verses":[260],"verseLabel":"البقرة: 260","question":"لماذا سأل إبراهيم: ﴿رَبِّ أَرِنِي كَيْفَ تُحْيِي الْمَوْتَى﴾ مع إيمانه؟","answer":"لم يطلب أصل التصديق بل مشاهدة الكيفية لينتقل من علم الخبر إلى طمأنينة العيان؛ ولذلك أجاب عن سؤال الإيمان بالإثبات ثم علل بطلب طمأنينة القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص172–178، تحت البقرة: 260، في السؤال والحوار.","url":""}]},{"id":"s2-1330","number":1330,"surah":2,"verses":[260],"verseLabel":"البقرة: 260","question":"ما سرّ توجيهه بقوله تعالى: ﴿فَخُذْ أَرْبَعَةً مِنَ الطَّيْرِ فَصُرْهُنَّ إِلَيْكَ﴾؟","answer":"جعله يباشر التجربة بيده ويرتبط بالطيور قبل تفريقها، ليكون اجتماع أجزائها وعودتها إليه أبلغ في المشاهدة وأبعد عن الاشتباه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص177–182، تحت البقرة: 260، في ترتيب الأوامر.","url":""}]},{"id":"s2-1331","number":1331,"surah":2,"verses":[260],"verseLabel":"البقرة: 260","question":"لماذا جعل على كل جبل جزءًا ثم أمره أن يدعوها؟","answer":"بالغ في تفريق الأجزاء ثم جمعها بمجرد النداء، ليظهر أن تباعد المادة لا يعجز القدرة وأن الإحياء استجابة سريعة لأمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص181–186، تحت البقرة: 260، في الصورة والنتيجة.","url":""}]},{"id":"s2-1332","number":1332,"surah":2,"verses":[260],"verseLabel":"البقرة: 260","question":"لماذا ختم بـ﴿وَاعْلَمْ أَنَّ اللَّهَ عَزِيزٌ حَكِيمٌ﴾؟","answer":"العزيز لا يعجزه جمع المتفرق، والحكيم يختار للتعليم الآية والطريقة والوقت الأنسب؛ فالفاصلة تجيب عن إمكان الإحياء وعن حكمة المشهد معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص185–189، تحت البقرة: 260، في مناسبة الاسمين.","url":""}]},{"id":"s2-1333","number":1333,"surah":2,"verses":[261],"verseLabel":"البقرة: 261","question":"لماذا شبّه النفقة بحبة أنبتت سبع سنابل في كل سنبلة مائة حبة؟","answer":"حول المضاعفة إلى مشهد زرع حي: حبة واحدة تصير سبعمئة، ليشعر المنفق أن ما يخرج من يده لا يفنى بل ينمو.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص190–206، تحت البقرة: 261.","url":""}]},{"id":"s2-1334","number":1334,"surah":2,"verses":[261],"verseLabel":"البقرة: 261","question":"لماذا جمع ﴿أموالهم﴾ ولم يقل: مالهم؟","answer":"لأن المنفقين متعددون ولكل واحد مال وصور من البذل، فالجمع يستوعب اختلاف الملكيات والنفقات.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص197، تحت البقرة: 261.","url":""}]},{"id":"s2-1335","number":1335,"surah":2,"verses":[261],"verseLabel":"البقرة: 261","question":"ما سرّ التعبير في قوله تعالى: ﴿والله يضاعف لمن يشاء﴾ ولم يقيد المضاعفة بعشرة أمثال؟","answer":"المثل يذكر سبعمئة ثم يفتح الفضل لما وراءها بحسب الإخلاص والحاجة؛ فسعة الله لا يحصرها حد أدنى للجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص203، تحت البقرة: 261.","url":""}]},{"id":"s2-1336","number":1336,"surah":2,"verses":[160],"verseLabel":"البقرة: 261، الأنعام: 160","question":"لماذا جعل جزاء الحسنة في الأنعام عشر أمثالها، بينما بلغ جزاء النفقة في البقرة سبعمائة ضعف؟","answer":"آية الأنعام قاعدة عامة في مطلق الحسنات، فذكرت الحد العام المضمون للحسنة وهو عشر أمثالها. أما آية البقرة فخاصة بالإنفاق في سبيل الله، وهو من أعظم القربات وأشدها نفعًا وتضحية، فمثلت مضاعفته الخاصة بسبع سنابل في كل سنبلة مائة حبة، مع بقاء باب الزيادة مفتوحًا بقوله: ﴿والله يضاعف لمن يشاء﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص620–621، تحت الأنعام: 160، في المقارنة بالبقرة: 261.","url":""}]},{"id":"s2-1337","number":1337,"surah":2,"verses":[43],"verseLabel":"البقرة: 261، يوسف: 43","question":"ما سرّ اختلاف التعبير بين قوله تعالى في مثل النفقة: ﴿أَنْبَتَتْ سَبْعَ سَنَابِلَ﴾ بجمع الكثرة، وقوله تعالى في رؤيا ملك مصر: ﴿وَسَبْعَ سُنْبُلَاتٍ خُضْرٍ﴾ بجمع القلة؟","answer":"مقام البقرة مبني على التكثير والمضاعفة؛ فالحبة تنتهي إلى سبعمائة ضعف، ثم يفتح قوله ﴿والله يضاعف لمن يشاء﴾ باب الزيادة، فناسب جمع الكثرة ﴿سنابل﴾. أما يوسف فتحكي رؤيا محددة لسبع سنبلات، وما دون العشرة قليل، فناسب جمع القلة، كما شاكل قوله قبلها ﴿سبع بقرات﴾. فاختلاف الجمع يتبع مقصد التكثير أو نقل العدد المشاهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص198–200، تحت البقرة: 261، في المقارنة بيوسف: 43.","url":""}]},{"id":"s2-1338","number":1338,"surah":2,"verses":[261],"verseLabel":"البقرة: 261","question":"ما سرّ التعبير في قوله تعالى: ﴿مَثَلُ الَّذِينَ يُنْفِقُونَ أَمْوَالَهُمْ﴾ ثم شبّه بالحبة لا بالأشخاص؟","answer":"في التركيب إيجاز؛ فالمشبه هو حال نفقتهم أو ثوابها، وحذف المضاف يجعل المنفق ونفقته داخلين في صورة الزرع المثمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص194–200، تحت البقرة: 261، في بناء المثل.","url":""}]},{"id":"s2-1339","number":1339,"surah":2,"verses":[261],"verseLabel":"البقرة: 261","question":"لماذا ختم بـ﴿وَاللَّهُ وَاسِعٌ عَلِيمٌ﴾؟","answer":"واسع الفضل فلا تقف المضاعفة عند العدد المذكور، وعليم بالنية ومحل النفقة؛ فالكثرة ليست آلية بل فضل موزون بعلمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص200–205، تحت البقرة: 261، في الفاصلة.","url":""}]},{"id":"s2-1340","number":1340,"surah":2,"verses":[262],"verseLabel":"البقرة: 262","question":"لماذا جمع بين المنّ والأذى بعد الصدقة؟ وما الفرق بينهما؟","answer":"المن تذكير المعطى بالفضل واستعلاء عليه، والأذى أوسع من قول أو فعل يجرحه؛ وقد يقع أحدهما دون الآخر فجمعهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص206–212، تحت البقرة: 262.","url":""}]},{"id":"s2-1341","number":1341,"surah":2,"verses":[262,274],"verseLabel":"البقرة: 262 و274","question":"ما سرّ التعبير في قوله تعالى في الآية 262: ﴿لَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ﴾ بلا فاء، ثم قال في الآية 274: ﴿فَلَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ﴾ بالفاء؟","answer":"آية 262 ليست في صورة شرط وجزاء، بل في بيان من يستحق الأجر: المنفق لله الذي لا يتبع إنفاقه منًّا ولا أذى؛ فكان ترتب الأجر عليه بيّنًا ولم يحتج إلى فاء السببية. أما آية 274 فعممت أوقات الإنفاق وأحواله: ليلًا ونهارًا، سرًّا وعلانية؛ فدخلت الفاء لتقرر أن الإنفاق متى وُجد وعلى أي حال كان فهو سبب للأجر، وتحض المنفق على ألا ينتظر وقتًا أو حالًا أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص216–217، تحت البقرة: 262، في بيان المتشابه اللفظي مع البقرة: 274.","url":""}]},{"id":"s2-1342","number":1342,"surah":2,"verses":[262],"verseLabel":"البقرة: 262","question":"لماذا اشترط بعد الإنفاق ألا يتبعه ﴿مَنًّا وَلَا أَذًى﴾؟","answer":"لأن العطاء قد يبني حاجة الجسد ثم يهدم كرامة النفس؛ فاعتبر سلامة ما بعد الصدقة جزءًا من قبولها، وقدم المن لأنه أذى ينشأ غالبًا من تذكير المعطى بالفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص206–212، تحت البقرة: 262، في الشرط والترتيب.","url":""}]},{"id":"s2-1343","number":1343,"surah":2,"verses":[262],"verseLabel":"البقرة: 262","question":"ما سرّ التعبير في قوله تعالى: ﴿ثُمَّ لَا يُتْبِعُونَ﴾ لا «ولا يتبعون»؟","answer":"﴿ثم﴾ تستوعب الزمن المتراخي؛ فالمطلوب ألا يظهر المن بعد أيام أو سنين، لا أن يخلو مجلس العطاء منه فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص209–214، تحت البقرة: 262، في دلالة ﴿ثم﴾.","url":""}]},{"id":"s2-1344","number":1344,"surah":2,"verses":[262],"verseLabel":"البقرة: 262","question":"لماذا جمع لهم: ﴿لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ﴾؟","answer":"نفى خوف المستقبل وحزن الماضي، فاستوعب اضطراب الزمن كله جزاء لمن صان قلب المحتاج من الاضطراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص212–216، تحت البقرة: 262، في النفي والمقابلة.","url":""}]},{"id":"s2-1345","number":1345,"surah":2,"verses":[263],"verseLabel":"البقرة: 263","question":"ما سرّ التعبير في قوله تعالى: ﴿قول معروف ومغفرة خير من صدقة يتبعها أذى﴾؟","answer":"الكلمة الطيبة والعفو يحفظان كرامة المحتاج، أما المال المصحوب بالإهانة فيسد حاجة ويصنع جرحًا؛ فكان الإحسان المعنوي الخالص خيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص206–225، تحت البقرة: 263.","url":""}]},{"id":"s2-1346","number":1346,"surah":2,"verses":[263],"verseLabel":"البقرة: 263","question":"ما سرّ التعبير في قوله تعالى: ﴿لا خوف عليهم﴾، دون أن يقال: لا يخافون؟","answer":"الجملة الاسمية أرسخ، وتنفي جنس الخوف الواقع عليهم لا مجرد فعل يصدر منهم في لحظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص220، تحت البقرة: 263.","url":""}]},{"id":"s2-1347","number":1347,"surah":2,"verses":[263],"verseLabel":"البقرة: 263","question":"لماذا نكّر ﴿قَوْلٌ﴾ و﴿مَغْفِرَةٌ﴾ و﴿صَدَقَةٌ﴾؟","answer":"ليعم أقل كلمة معروفة وأدنى عفو، ويقرر أنهما مع قلتهما خير من أي صدقة خالطها الأذى؛ فالعبرة بالنوع والصفاء لا بالحجم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص218–223، تحت البقرة: 263، في التنكير.","url":""}]},{"id":"s2-1348","number":1348,"surah":2,"verses":[263],"verseLabel":"البقرة: 263","question":"لماذا ختم بـ﴿وَاللَّهُ غَنِيٌّ حَلِيمٌ﴾؟","answer":"غني عن صدقة يمن بها صاحبها، وحليم لا يعاجله مع سوء أدبه؛ والاسمان يربيان المنفق أن يتخلق بالغنى عن المن والحلم على السائل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص221–225، تحت البقرة: 263، في الفاصلة.","url":""}]},{"id":"s2-1349","number":1349,"surah":2,"verses":[264],"verseLabel":"البقرة: 264","question":"لماذا شبّه المرائي بصفوان عليه تراب فأصابه وابل؟","answer":"يبدو التراب تربة صالحة كما يبدو الرياء عملًا صالحًا، ثم يكشف الوابل صخرة لا تمسك شيئًا؛ فيسقط القناع ويبطل الأجر.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص226–242، تحت البقرة: 264.","url":""}]},{"id":"s2-1350","number":1350,"surah":2,"verses":[264],"verseLabel":"البقرة: 264","question":"لماذا اختار ﴿صفوان﴾ لا حجرًا أملس؟","answer":"صفوان لفظ يدل بذاته على الصخرة الملساء الصلبة، فيكثف الصورة ويستحضر سطحًا لا ينبت ولا يحتفظ بالتراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص236، تحت البقرة: 264.","url":""}]},{"id":"s2-1351","number":1351,"surah":2,"verses":[264],"verseLabel":"البقرة: 264","question":"لماذا ذكر طبقة ﴿تراب﴾ فوق الصخرة؟","answer":"لأن الطبقة تخدع الناظر بصورة خصوبة مؤقتة، مثل ظاهر الصدقة الذي يغطي قلبًا قاسيًا حتى يكشفه الابتلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص237، تحت البقرة: 264.","url":""}]},{"id":"s2-1352","number":1352,"surah":2,"verses":[264],"verseLabel":"البقرة: 264","question":"لماذا اختار الوابل لا المطر أو الغيث؟","answer":"الوابل مطر غزير شديد يزيل التراب بسرعة، فناسب لحظة الاختبار التي تكشف أصل العمل وتستأصله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص238، تحت البقرة: 264.","url":""}]},{"id":"s2-1353","number":1353,"surah":2,"verses":[264],"verseLabel":"البقرة: 264","question":"ما سرّ التعبير في قوله تعالى: ﴿فَتَرَكَهُ صَلْدًا﴾؟","answer":"الفاء تصور سرعة انكشاف الحقيقة، و﴿صلدًا﴾ يرسم سطحًا أملس لا أثر فيه لما كان عليه؛ فلا يبقى للمرائي من نفقته ما ينتفع به.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص231–236، تحت البقرة: 264، في الصورة والنتيجة.","url":""}]},{"id":"s2-1354","number":1354,"surah":2,"verses":[264],"verseLabel":"البقرة: 264","question":"لماذا ختم بـ﴿وَاللَّهُ لَا يَهْدِي الْقَوْمَ الْكَافِرِينَ﴾؟","answer":"لأن الرياء والمن يكشفان تعلق القلب بنظر الناس وإنكار ميزان الآخرة؛ والخاتمة تحذر من مسار يشبه الكفر في إبطال الصلة بالله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص236–241، تحت البقرة: 264، في الخاتمة.","url":""}]},{"id":"s2-1355","number":1355,"surah":2,"verses":[265],"verseLabel":"البقرة: 265","question":"ما سرّ التعبير في قوله تعالى عن الجنة ﴿آتت أكلها ضعفين﴾ لا: ثمارها؟","answer":"الأكل هو الثمر من حيث الانتفاع والتناول، فيبرز وفرة العائد الحقيقي لا مجرد منظر الثمرة على الشجر.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص251، تحت البقرة: 265.","url":""}]},{"id":"s2-1356","number":1356,"surah":2,"verses":[265],"verseLabel":"البقرة: 265","question":"ما سرّ التعبير في قوله تعالى: ﴿فإن لم يصبها وابل فطل﴾ بـ﴿إن﴾ لا ﴿إذا﴾؟","answer":"عدم الوابل احتمال عارض، ومع ذلك يكفي الطل لخصوبة الجنة؛ فالأداة تخدم معنى أنها تثمر في الحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص252، تحت البقرة: 265.","url":""}]},{"id":"s2-1357","number":1357,"surah":2,"verses":[265],"verseLabel":"البقرة: 265","question":"لماذا شبّه المخلصين بجنة بربوة؟","answer":"الجنة أرض خصبة والربوة أبعد عن الركود وأحسن تعرضًا للماء والهواء؛ فصورت نفسًا طيبة وعملًا ثابتًا يثمر في أحسن موضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص242–247، تحت البقرة: 265، في التمثيل.","url":""}]},{"id":"s2-1358","number":1358,"surah":2,"verses":[265],"verseLabel":"البقرة: 265","question":"ما سرّ التعبير في قوله تعالى: ﴿أَصَابَهَا وَابِلٌ فَآتَتْ أُكُلَهَا ضِعْفَيْنِ فَإِنْ لَمْ يُصِبْهَا وَابِلٌ فَطَلٌّ﴾؟","answer":"المخلص يثمر مع النفقة الكثيرة كالوابل والقليلة كالطل؛ لأن خصوبة القلب تعوض قلة المورد، بخلاف الصخرة التي لا ينفعها المطر.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص246–251، تحت البقرة: 265، في المقابلة.","url":""}]},{"id":"s2-1359","number":1359,"surah":2,"verses":[265],"verseLabel":"البقرة: 265","question":"لماذا ختم بـ﴿وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ﴾؟","answer":"يرى هيئة العطاء ونيته الخفية كما يرى اختلاف الأرضين تحت المطر؛ فلا يستوي عملان تشابه ظاهرهما واختلف منبتهما الداخلي.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص250–253، تحت البقرة: 265، في الفاصلة.","url":""}]},{"id":"s2-1360","number":1360,"surah":2,"verses":[266],"verseLabel":"البقرة: 266","question":"لماذا خُص النخيل بالشجر، وذُكرت الأعناب بالثمر؟","answer":"النخيل والأعناب أشهر أصول الجنات وأعظمها نفعًا عند العرب؛ وذكرهما يختصر أنواع الشجر والثمر النفيس.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص262، تحت البقرة: 266.","url":""}]},{"id":"s2-1361","number":1361,"surah":2,"verses":[266],"verseLabel":"البقرة: 266","question":"لماذا جمع الأعناب والأنهار والثمرات؟","answer":"تراكمها يصور جنة مكتملة الأصول والري والنواتج، حتى يكون احتراقها أقصى صورة للخسارة بعد تمام الغنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص263–264، تحت البقرة: 266.","url":""}]},{"id":"s2-1362","number":1362,"surah":2,"verses":[266],"verseLabel":"البقرة: 266","question":"لماذا كان صاحب الجنة كبيرًا وله ذرية ضعفاء حين أصابها الإعصار؟","answer":"جمع أشد الحاجة مع انعدام القدرة على التعويض؛ فالكبر والذرية الضعيفة يجعلان ضياع الجنة صورة للعمل المحبط يوم لا يمكن استدراكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص254–269، تحت البقرة: 266.","url":""}]},{"id":"s2-1363","number":1363,"surah":2,"verses":[266],"verseLabel":"البقرة: 266","question":"لماذا ختم المثل بـ﴿لعلكم تتفكرون﴾ لا تذكرون؟","answer":"المطلوب تحليل الصورة وإسقاطها على مصير العمل، لا مجرد استرجاع معلومة؛ فالتفكر يعبر من الجنة المحترقة إلى مراجعة النية.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص268، تحت البقرة: 266.","url":""}]},{"id":"s2-1364","number":1364,"surah":2,"verses":[266],"verseLabel":"البقرة: 266","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَهُ ذُرِّيَّةٌ ضُعَفَاءُ﴾، دون أن يقال: «وله أولاد ضعفاء»؟","answer":"لفظ ﴿الذرية﴾ ينظر إلى الأولاد بوصفهم امتدادًا يتكاثر منه النسل، لا مجرد أبناء حاضرين؛ ولذلك يوحي بمستقبل الأسرة كله المعلّق بهذه الجنة. فإذا احترقت وهو كبير وله ذرية عاجزة، لم يفقد قوت يومه وحده، بل ضاع المورد الذي كان يرجو أن يحفظ به بقاء نسله وتكاثره؛ فصار مشهد الخسارة أعمق من لفظ «الأولاد».","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص264، تحت البقرة: 266، في مبحث إيثار لفظ ﴿الذرية﴾.","url":""}]},{"id":"s2-1365","number":1365,"surah":2,"verses":[266],"verseLabel":"البقرة: 266","question":"ما سرّ التعبير في قوله تعالى: ﴿إِعْصَارٌ فِيهِ نَارٌ﴾؟","answer":"جمع قوة الريح وإحراق النار ليصور سرعة الاستئصال وشموله؛ فالعمل الذي ظنه صاحبه جنة قد يزيله الرياء في لحظة الحاجة القصوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص259–264، تحت البقرة: 266، في التصوير.","url":""}]},{"id":"s2-1366","number":1366,"surah":2,"verses":[267],"verseLabel":"البقرة: 267","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تيمموا الخبيث منه تنفقون﴾، دون أن يقال: لا تنفقوا الخبيث؟","answer":"قدم تعمد القصد إلى الرديء ليذم اختيارَه قبل فعل الإنفاق؛ فالمشكلة أن ينتقي الإنسان لنفسه الحسن ولغيره الخبيث.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص269–280، تحت البقرة: 267.","url":""}]},{"id":"s2-1367","number":1367,"surah":2,"verses":[267],"verseLabel":"البقرة: 267","question":"ما سرّ التعبير في قوله تعالى: ﴿ولستم بآخذيه إلا أن تغمضوا فيه﴾؟","answer":"احتج عليهم بميزان نفوسهم: لا تعطوا ما لا تقبلونه لأنفسكم إلا مع التغاضي عن عيبه؛ وهو اختبار عدل قريب لا يحتاج تنظيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص269–280، تحت البقرة: 267.","url":""}]},{"id":"s2-1368","number":1368,"surah":2,"verses":[267],"verseLabel":"البقرة: 267","question":"ما سرّ التعبير في قوله تعالى: ﴿أَنْفِقُوا مِنْ طَيِّبَاتِ مَا كَسَبْتُمْ﴾؟","answer":"ربط جودة الصدقة بجودة مصدرها ومحلها؛ فالمال المكتسب حلالًا والجيد المحبوب أليق أن يقدم لله، و﴿من﴾ تبقي للإنسان حاجته ولا تطلب الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص269–273، تحت البقرة: 267، في اختيار الطيبات.","url":""}]},{"id":"s2-1369","number":1369,"surah":2,"verses":[268],"verseLabel":"البقرة: 268","question":"لماذا قابل وعد الشيطان بالفقر بوعد الله بالمغفرة والفضل؟","answer":"الشيطان يخوفهم بخسارة المال ويقودهم إلى البخل، والله يعد بإزالة الذنب وزيادة الخير؛ فمغفرة الماضي وفضل المستقبل يقابلان خوف النقص.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص280–287، تحت البقرة: 268.","url":""}]},{"id":"s2-1370","number":1370,"surah":2,"verses":[268],"verseLabel":"البقرة: 268","question":"لماذا قدّم الله المغفرة على الفضل في قوله: ﴿وَاللَّهُ يَعِدُكُمْ مَغْفِرَةً مِنْهُ وَفَضْلًا﴾؟","answer":"لأن تطهير النفس من الذنب مقدم على تحصيل الزيادة؛ فالمؤمن أحوج أولًا إلى المغفرة التي تزيل أثر المعصية، ثم يكون أهلًا لوعد الفضل في الدنيا والآخرة. وجاء الترتيب على قاعدة التخلية قبل التحلية: إزالة المانع قبل تحصيل الكمال، كما أنه يقابل وعد الشيطان بالفقر بوعد أوسع يجمع ستر الذنب وزيادة الرزق والثواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص284–285، تحت البقرة: 268، في مبحث تقديم المغفرة على الفضل.","url":""}]},{"id":"s2-1371","number":1371,"surah":2,"verses":[268],"verseLabel":"البقرة: 268","question":"ما سرّ التعبير في قوله تعالى: ﴿الشَّيْطَانُ يَعِدُكُمُ الْفَقْرَ﴾ وسمى التخويف وعدًا؟","answer":"سخر من إغراء الشيطان؛ فهو يقدم الفقر المتوقع كأنه وعد محقق، بينما وعد الله الحقيقي مغفرة وفضل. والمقابلة تكشف أي الوعدين أحق بالثقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص280–283، تحت البقرة: 268، في المشاكلة والمقابلة.","url":""}]},{"id":"s2-1372","number":1372,"surah":2,"verses":[268],"verseLabel":"البقرة: 268","question":"لماذا قرن الشيطان الفقر بالأمر بالفحشاء؟","answer":"الخوف من النقص يدفع إلى البخل والرديء والمن وسائر القبائح؛ فبيّن أن الوسوسة الاقتصادية ليست محايدة بل باب لسلوك فاحش.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص282–285، تحت البقرة: 268، في الاقتران.","url":""}]},{"id":"s2-1373","number":1373,"surah":2,"verses":[268],"verseLabel":"البقرة: 268","question":"لماذا ختم بـ﴿وَاللَّهُ وَاسِعٌ عَلِيمٌ﴾؟","answer":"واسع الفضل فيقدر أن يخلف المنفق، وعليم بحاجته ونيته؛ فالفاصلة تواجه خوف الفقر بسعة لا عشوائية فيها بل علم ورعاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص284–286، تحت البقرة: 268، في الفاصلة.","url":""}]},{"id":"s2-1374","number":1374,"surah":2,"verses":[269],"verseLabel":"البقرة: 269","question":"ما سرّ التعبير في قوله تعالى: ﴿وما يذكر إلا أولو الألباب﴾ لا يتفكر أو يعقل؟","answer":"التذكر استحضار الحقيقة التي تعرفها الفطرة بعد أن تحجبها الشهوة، وأصحاب الألباب هم من تحول الحكمة عندهم إلى عبرة حاضرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص287–294، تحت البقرة: 269.","url":""}]},{"id":"s2-1375","number":1375,"surah":2,"verses":[269],"verseLabel":"البقرة: 269","question":"ما سرّ التعبير في قوله تعالى: ﴿يُؤْتِي الْحِكْمَةَ مَنْ يَشَاءُ﴾ بعد الحديث عن الإنفاق؟","answer":"لأن حسن الموازنة بين المال والعاقبة، وتمييز وعد الله من وسوسة الشيطان، ثمرة حكمة؛ فالسياق يوسعها من معرفة الحكم إلى وضعه في موضعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص287–290، تحت البقرة: 269، في المناسبة.","url":""}]},{"id":"s2-1376","number":1376,"surah":2,"verses":[269],"verseLabel":"البقرة: 269","question":"لماذا وصف الحكمة بأنها ﴿خَيْرًا كَثِيرًا﴾؟","answer":"نكّر الخير ووصفه بالكثرة لأن ثمرة الحكمة تمتد إلى الاعتقاد والقول والعمل، ولأنها تحسن الانتفاع بكل نعمة أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص289–292، تحت البقرة: 269، في التنكير والوصف.","url":""}]},{"id":"s2-1377","number":1377,"surah":2,"verses":[270],"verseLabel":"البقرة: 270","question":"لماذا وحّد الضمير في ﴿فإن الله يعلمه﴾ مع ذكر النفقة والنذر؟","answer":"يعود إلى ﴿ما﴾ الموصولة في كل من الفعلين أو إلى المذكور باعتباره عملًا واحدًا؛ فالإفراد يجمع كل فرد من الإنفاق والنذر تحت العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص294–301، تحت البقرة: 270.","url":""}]},{"id":"s2-1378","number":1378,"surah":2,"verses":[270],"verseLabel":"البقرة: 270","question":"لماذا جمع بين ﴿مَا أَنْفَقْتُمْ مِنْ نَفَقَةٍ﴾ و﴿نَذَرْتُمْ مِنْ نَذْرٍ﴾؟","answer":"جمع بذل المال التطوعي والالتزام الذي أوجبه الإنسان على نفسه، ليقرر أن كل خروج للمال أو عهد به معلوم لله لا يضيع.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص294–297، تحت البقرة: 270، في الجمع والعموم.","url":""}]},{"id":"s2-1379","number":1379,"surah":2,"verses":[270],"verseLabel":"البقرة: 270","question":"لماذا كرر ﴿مِنْ﴾ مع النفقة والنذر؟","answer":"زادت أدوات العموم لتشمل أي نفقة وأي نذر مهما صغر، فلا يحتقر المحسن قليلًا ولا يظن المخالف أن شيئًا خفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص296–299، تحت البقرة: 270، في صيغ العموم.","url":""}]},{"id":"s2-1380","number":1380,"surah":2,"verses":[270],"verseLabel":"البقرة: 270","question":"لماذا ختم بـ﴿وَمَا لِلظَّالِمِينَ مِنْ أَنْصَارٍ﴾؟","answer":"من أنفق رياء أو منع حقًا ظلم نفسه وغيره، ولن تنقذه يوم الجزاء شبكة النصرة التي ربما طلب نظرها في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص298–300، تحت البقرة: 270، في النفي.","url":""}]},{"id":"s2-1381","number":1381,"surah":2,"verses":[271],"verseLabel":"البقرة: 271","question":"ما سرّ وصف إبداء الصدقات بقوله تعالى: ﴿فَنِعِمَّا هِيَ﴾، ثم تفضيل إخفائها؟","answer":"الإعلان حسن إذا أظهر الشعيرة وشجع الخير، والإخفاء للفقراء أفضل غالبًا للإخلاص وصون الكرامة؛ ففاضل بحسب المصلحة ولم يذم الأصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص301–312، تحت البقرة: 271.","url":""}]},{"id":"s2-1382","number":1382,"surah":2,"verses":[271],"verseLabel":"البقرة: 271","question":"لماذا قيد الإخفاء بقوله: ﴿وَتُؤْتُوهَا الْفُقَرَاءَ﴾؟","answer":"لأن صدقة التطوع على الفقير هي الأشد تعرضًا للرياء وكسر الخاطر، فإخفاؤها أصون للمنفق والآخذ؛ أما إعلان بعض الواجبات فقد يحقق مصلحة أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص304–308، تحت البقرة: 271، في القيد.","url":""}]},{"id":"s2-1383","number":1383,"surah":2,"verses":[271],"verseLabel":"البقرة: 271","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيُكَفِّرُ عَنْكُمْ مِنْ سَيِّئَاتِكُمْ﴾؟","answer":"جاء بـ﴿من﴾ ليبقي العبد بين الرجاء والخوف ولا يتوهم أن صدقة واحدة تمحو كل تبعة بلا توبة، مع وعد حقيقي بتكفير جانب من السيئات.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص307–311، تحت البقرة: 271، في التبعيض.","url":""}]},{"id":"s2-1384","number":1384,"surah":2,"verses":[272],"verseLabel":"البقرة: 272","question":"ما مناسبة توجيه الخطاب إلى النبي ﷺ بقوله تعالى: ﴿لَيْسَ عَلَيْكَ هُدَاهُمْ﴾ وسط أحكام الصدقة؟","answer":"رفع عنه مسؤولية إدخال الإيمان في القلوب، ومنع أن تستخدم الصدقة للضغط على المحتاج حتى يغير دينه؛ الهداية لله والعطاء للخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص312–322، تحت البقرة: 272.","url":""}]},{"id":"s2-1385","number":1385,"surah":2,"verses":[272],"verseLabel":"البقرة: 272","question":"لماذا كرر ﴿وما تنفقوا من خير﴾ بصيغ متقاربة؟","answer":"ثبت من جهات متعددة أن نفع النفقة يعود للمنفق، وأن الإخلاص شرط، وأن الجزاء كامل؛ فكل تكرار يبني قيدًا لا يعيد الكلام فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص312–322، تحت البقرة: 272.","url":""}]},{"id":"s2-1386","number":1386,"surah":2,"verses":[272],"verseLabel":"البقرة: 272","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا تُنْفِقُوا مِنْ خَيْرٍ فَلِأَنْفُسِكُمْ﴾؟","answer":"قلب تصور الخسارة: المال يصل إلى غيرك لكن ثوابه وبناء نفسك يعودان إليك، فلا تمن على الآخذ بما هو في حقيقته مصلحة لك.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص315–319، تحت البقرة: 272، في القصر والشرط.","url":""}]},{"id":"s2-1387","number":1387,"surah":2,"verses":[272],"verseLabel":"البقرة: 272","question":"لماذا قيد الإنفاق بقوله: ﴿إِلَّا ابْتِغَاءَ وَجْهِ اللَّهِ﴾؟","answer":"جعل الغاية القصوى رضا الله، فلا يكون العطاء لشراء الولاء أو السمعة أو تغيير عقيدة بالقسر؛ ولفظ الوجه كناية عن الذات والرضا مع معنى التوجه الكامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص318–321، تحت البقرة: 272، في القصر والكناية.","url":""}]},{"id":"s2-1388","number":1388,"surah":2,"verses":[273],"verseLabel":"البقرة: 273","question":"لماذا وصف الفقراء بأن الجاهل يحسبهم أغنياء من التعفف؟","answer":"عفتهم تستر حاجتهم حتى يخطئ من لا يتفقدهم، فدعت الآية إلى البحث خلف المظهر بدل انتظار سؤال يجرح المحتاج.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص322–331، تحت البقرة: 273.","url":""}]},{"id":"s2-1389","number":1389,"surah":2,"verses":[273],"verseLabel":"البقرة: 273","question":"ما سرّ التعبير في قوله تعالى: ﴿تعرفهم بسيماهم﴾ ثم قال ﴿لا يسألون الناس إلحافًا﴾؟","answer":"الأولى تعلم المعطي أن يقرأ العلامات، والثانية تبين سبب خفائها وهو ترك الإلحاح؛ فاجتمعت فراسة الرحمة وتعفف الفقير.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص322–331، تحت البقرة: 273.","url":""}]},{"id":"s2-1390","number":1390,"surah":2,"verses":[273],"verseLabel":"البقرة: 273","question":"لماذا وصف الفقراء بأنهم ﴿أُحْصِرُوا فِي سَبِيلِ اللَّهِ﴾؟","answer":"حبسهم الجهاد أو طلب العلم والطاعة عن التوسع في الكسب، فقدم سبب حاجتهم ليزيل عنهم وصمة الكسل ويجعل إعانتهم مشاركة في سبيل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص322–325، تحت البقرة: 273، في اختيار الفعل.","url":""}]},{"id":"s2-1391","number":1391,"surah":2,"verses":[274],"verseLabel":"البقرة: 274","question":"لماذا جمع أزمنة الإنفاق الأربعة: الليل والنهار والسر والعلانية؟","answer":"استوعب الزمن والكيفية ليصف إنفاقًا لا تحبسه ساعة ولا صورة؛ يسر حيث الإخفاء أصلح ويعلن حيث القدوة أنفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص331–339، تحت البقرة: 274.","url":""}]},{"id":"s2-1392","number":1392,"surah":2,"verses":[274],"verseLabel":"البقرة: 274","question":"ما سرّ تقديم الليل على النهار والسر على العلانية؟","answer":"قدم ما هو أليق بالإخفاء وأبعد عن الرياء، مع عدم إلغاء الإعلان النافع؛ فالترتيب يلمح إلى منزلة الإخلاص في باب الصدقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص333–336، تحت البقرة: 274، في التقديم.","url":""}]},{"id":"s2-1393","number":1393,"surah":2,"verses":[274],"verseLabel":"البقرة: 274","question":"لماذا كرر وعد ﴿لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ﴾؟","answer":"بعد تنوع طرق الإنفاق وحالاته ثبت لهم أمن شامل في المستقبل والماضي، وجعل تكرار اللازمة علامة على وحدة جزاء المخلصين.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص335–338، تحت البقرة: 274، في التكرار.","url":""}]},{"id":"s2-1394","number":1394,"surah":2,"verses":[275],"verseLabel":"البقرة: 275","question":"لماذا شبّه آكل الربا بمن يتخبطه الشيطان من المس؟","answer":"صور اضطراب قيامه واختلال ميزانه الذي يرى الاستغلال بيعًا طبيعيًا؛ فالربا يفسد توازنه النفسي والاجتماعي قبل الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص339–352، تحت البقرة: 275.","url":""}]},{"id":"s2-1395","number":1395,"surah":2,"verses":[275],"verseLabel":"البقرة: 275","question":"ما دلالة قولهم: ﴿إِنَّمَا الْبَيْعُ مِثْلُ الرِّبَا﴾ دون أن يجعلوا الربا هو المشبَّه بالبيع؟","answer":"جعلوا الربا أصلًا يقيسون عليه البيع مبالغة في قلب الفطرة، كأن الزيادة الربوية هي المعيار والمعاملة المشروعة فرعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص339–352، تحت البقرة: 275.","url":""}]},{"id":"s2-1396","number":1396,"surah":2,"verses":[275],"verseLabel":"البقرة: 275","question":"لماذا رد على قولهم ﴿إِنَّمَا الْبَيْعُ مِثْلُ الرِّبَا﴾ بقوله: ﴿وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا﴾؟","answer":"لم يدخل في قياسهم المقلوب، بل أعاد الفصل إلى حكم الله الذي يعلم الفرق بين تبادل المنافع وزيادة الدين المستغلة؛ فالتشابه الشكلي لا يلغي اختلاف الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص342–347، تحت البقرة: 275، في المقابلة والرد.","url":""}]},{"id":"s2-1397","number":1397,"surah":2,"verses":[275],"verseLabel":"البقرة: 275","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلَهُ مَا سَلَفَ وَأَمْرُهُ إِلَى اللَّهِ﴾ لمن انتهى؟","answer":"فتح باب التوبة من غير تكليف برد معاملات ماضية قبل بلوغ الموعظة، ثم فوض باطن توبته ومصيره إلى الله؛ فجمع التيسير مع عدم تزكية النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص346–351، تحت البقرة: 275، في الشرط والخاتمة.","url":""}]},{"id":"s2-1398","number":1398,"surah":2,"verses":[276],"verseLabel":"البقرة: 276","question":"كيف يُفهم قوله تعالى: ﴿يَمْحَقُ اللَّهُ الرِّبَا وَيُرْبِي الصَّدَقَاتِ﴾ مع أن الربا يزيد في الظاهر والصدقة تنقص؟","answer":"ميزان العاقبة يعكس الصورة: الربا يمحق البركة والعدل وإن نما الرقم، والصدقة تنمو أجرًا وتكافلًا وإن نقصت اليد.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص352–358، تحت البقرة: 276.","url":""}]},{"id":"s2-1399","number":1399,"surah":2,"verses":[276,283],"verseLabel":"البقرة: 276 و283","question":"ما سرّ التعبير في قوله تعالى عن آكل الربا: ﴿كُلَّ كَفَّارٍ أَثِيمٍ﴾، وقال عن كاتم الشهادة: ﴿فَإِنَّهُ آثِمٌ قَلْبُهُ﴾؛ لماذا ﴿أثيم﴾ هنا و﴿آثم﴾ هناك؟","answer":"﴿أثيم﴾ صيغة أشد من ﴿آثم﴾؛ فهي تدل على التمادي في الإثم والإقامة عليه والإصرار بلا مبالاة، ولذلك جاءت في الربا والكفر ونحوهما من الجرائم العامة الشديدة التي يتأذى بها المجتمع. أما ﴿آثم﴾ فتعني فاعل الإثم، وجاءت في كتمان الشهادة الذي يتعلق أثره المباشر غالبًا بالأفراد. فاختلاف الصيغتين يرسم تفاوت الجريمة ورسوخ صاحبها فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص440–441، تحت البقرة: 283، في توجيه اختلاف الصيغتين ﴿آثم﴾ و﴿أثيم﴾.","url":""}]},{"id":"s2-1400","number":1400,"surah":2,"verses":[276],"verseLabel":"البقرة: 276","question":"لماذا اختار ﴿يُرْبِي الصَّدَقَاتِ﴾ من المادة نفسها التي اشتق منها الربا؟","answer":"ليبين أن النماء الحقيقي في العطاء المشروع لا في الزيادة المحرمة؛ فالتقارب اللفظي يضاعف المفارقة بين اسم الربا وعاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص353–356، تحت البقرة: 276، في الاشتقاق والمشاكلة.","url":""}]},{"id":"s2-1401","number":1401,"surah":2,"verses":[276],"verseLabel":"البقرة: 276","question":"لماذا ختم بـ﴿وَاللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ﴾؟","answer":"المصر على الربا يجمع كفران النعمة وتكرر الإثم، وصيغتا المبالغة تصوران رسوخ الجحود والعمل الفاسد لا زلة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص355–357، تحت البقرة: 276، في صيغ المبالغة.","url":""}]},{"id":"s2-1402","number":1402,"surah":2,"verses":[277],"verseLabel":"البقرة: 277","question":"لماذا أعاد صفات الإيمان والصلاة والزكاة بين آيات الربا؟","answer":"وضع النموذج المضاد لآكل الربا: قلب مؤمن وعبادة قائمة ومال يطهر بالزكاة، فالتوسط ترغيب وباب نجاة بين الوعيدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص358–371، تحت البقرة: 277.","url":""}]},{"id":"s2-1403","number":1403,"surah":2,"verses":[277],"verseLabel":"البقرة: 277","question":"ما سرّ التعبير في قوله تعالى: ﴿وَأَقَامُوا الصَّلَاةَ وَآتَوُا الزَّكَاةَ﴾ بعد ﴿عَمِلُوا الصَّالِحَاتِ﴾؟","answer":"خص عمودي العبادة والمال بعد العموم؛ فالصلاة تصلح الصلة بالله والزكاة تطهر علاقة المال، وهي المقابل العملي للربا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص359–362، تحت البقرة: 277، في عطف الخاص.","url":""}]},{"id":"s2-1404","number":1404,"surah":2,"verses":[277],"verseLabel":"البقرة: 277","question":"ما سرّ التعبير في قوله تعالى: ﴿أَجْرُهُمْ عِنْدَ رَبِّهِمْ﴾؟","answer":"﴿عند﴾ تفيد الحفظ والقرب، وإضافة الرب إليهم تشعر بالرعاية؛ فما أخرجوه زكاة لم يضع بل صار أجرًا مصونًا عند مربيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص361–363، تحت البقرة: 277، في الظرف والإضافة.","url":""}]},{"id":"s2-1405","number":1405,"surah":2,"verses":[278,279],"verseLabel":"البقرة: 278–279","question":"لماذا سمّى الإصرار على الربا حربًا من الله ورسوله؟","answer":"لأنه تمرد على نظام العدل واستغلال يهدد المجتمع، فصور الإصرار مواجهةً لله ورسوله ليظهر فداحة الجريمة لا معاملة شخصية بسيطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص358–376، تحت البقرة: 278–279.","url":""}]},{"id":"s2-1406","number":1406,"surah":2,"verses":[278],"verseLabel":"البقرة: 278","question":"لماذا افتتح تحريم ما بقي من الربا بقوله: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ﴾؟","answer":"جعل ترك الربا اختبارًا مباشرًا لصدق الإيمان والتقوى؛ فالنداء يستنهض الهوية قبل أمر يمس مصلحة مالية راسخة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص364–366، تحت البقرة: 278، في النداء.","url":""}]},{"id":"s2-1407","number":1407,"surah":2,"verses":[278],"verseLabel":"البقرة: 278","question":"ما سرّ التعبير في قوله تعالى: ﴿وَذَرُوا مَا بَقِيَ مِنَ الرِّبَا﴾؟","answer":"أمر بترك الزيادات التي لم تقبض، فلم يكتف بمنع عقود جديدة؛ و﴿ذروا﴾ أشد في الإلقاء والقطع من مجرد «لا تأخذوا».","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص365–368، تحت البقرة: 278، في اختيار الفعل.","url":""}]},{"id":"s2-1408","number":1408,"surah":2,"verses":[278],"verseLabel":"البقرة: 278","question":"لماذا ختم الشرط بقوله: ﴿إِنْ كُنْتُمْ مُؤْمِنِينَ﴾؟","answer":"ليس المراد الشك في خطابهم، بل إلهاب ضميرهم: إن كان الإيمان هو الحقيقة الحاكمة فليظهر أثره عند تعارض الأمر مع الربح.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص367–370، تحت البقرة: 278، في الشرط.","url":""}]},{"id":"s2-1409","number":1409,"surah":2,"verses":[279],"verseLabel":"البقرة: 279","question":"ما سرّ التعبير في قوله تعالى: ﴿فَأْذَنُوا بِحَرْبٍ مِنَ اللَّهِ وَرَسُولِهِ﴾؟","answer":"جعل الإصرار على الربا مواجهة لنظام العدل الإلهي كله، فاختار الحرب لتصوير جسامة الجريمة وآثارها التي تسحق الضعفاء والمجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص364–367، تحت البقرة: 279، في التهديد.","url":""}]},{"id":"s2-1410","number":1410,"surah":2,"verses":[279],"verseLabel":"البقرة: 279","question":"ما سرّ التعبير للتائبين بقوله تعالى: ﴿فَلَكُمْ رُءُوسُ أَمْوَالِكُمْ﴾؟","answer":"حفظ أصل المال كما منع الزيادة، فالتوبة لا تعني ظلم الدائن بإسقاط حقه ولا ظلم المدين بالربا؛ وهذا يفسره قوله بعدها: لا تظلمون ولا تظلمون.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص366–369، تحت البقرة: 279، في التفريع.","url":""}]},{"id":"s2-1411","number":1411,"surah":2,"verses":[279],"verseLabel":"البقرة: 279","question":"لماذا جاء: ﴿لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ﴾ بالبناءين المختلفين؟","answer":"جمع منع الظلم الصادر منهم بأخذ الزيادة، ومنع الظلم الواقع عليهم بنقص رأس المال؛ فالتوازن اللفظي يلخص عدالة الحكم للطرفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص368–370، تحت البقرة: 279، في المقابلة.","url":""}]},{"id":"s2-1412","number":1412,"surah":2,"verses":[280],"verseLabel":"البقرة: 280","question":"ما سرّ التعبير في قوله تعالى: ﴿فنظرة إلى ميسرة﴾ بالمصدر لا: فأنظروه؟","answer":"المصدر المرفوع يجعل الإنظار حكمًا ثابتًا واجبًا لا منحة مزاجية من الدائن، ويحذف الفاعل ليعم كل صاحب حق.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص371–376، تحت البقرة: 280.","url":""}]},{"id":"s2-1413","number":1413,"surah":2,"verses":[280],"verseLabel":"البقرة: 280","question":"ما سرّ التعبير في قوله تعالى: ﴿وأن تصدقوا خير لكم﴾ فسمّى إسقاط الدين صدقة؟","answer":"لأن الدائن يهب حقًا ثابتًا للمعسر، فكان إسقاط بعضه أو كله عطاءً حقيقيًا يتقرب به إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص371–376، تحت البقرة: 280.","url":""}]},{"id":"s2-1414","number":1414,"surah":2,"verses":[280],"verseLabel":"البقرة: 280","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنْ كَانَ ذُو عُسْرَةٍ﴾، دون أن يقال «وإن كان معسرًا»؟","answer":"التعبير بصاحب العسرة يصور الضيق حالةً لابسته لا هوية دائمة، وفيه رفق يحفظ كرامته ويترك باب تغير الحال مفتوحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص371–373، تحت البقرة: 280، في اختيار التركيب.","url":""}]},{"id":"s2-1415","number":1415,"surah":2,"verses":[280],"verseLabel":"البقرة: 280","question":"ما سرّ التعبير في قوله تعالى: ﴿وَأَنْ تَصَدَّقُوا خَيْرٌ لَكُمْ﴾ بعد وجوب الإنظار؟","answer":"نقل الدائن من حد العدل إلى فضل إسقاط بعض الدين أو كله، وسماه صدقة ليعيد تعريف الخسارة الظاهرة مكسبًا أخرويًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص374–375، تحت البقرة: 280، في التفضيل.","url":""}]},{"id":"s2-1416","number":1416,"surah":2,"verses":[281],"verseLabel":"البقرة: 281","question":"لماذا ختمت أحكام الأموال بقوله ﴿واتقوا يومًا ترجعون فيه إلى الله﴾؟","answer":"الوثائق والقوانين لا تمنع كل تحايل، فختم برقابة الحساب الذي توفى فيه كل نفس ما كسبت ولا يضيع فيه حق.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص376–381، تحت البقرة: 281.","url":""}]},{"id":"s2-1417","number":1417,"surah":2,"verses":[281],"verseLabel":"البقرة: 281","question":"ما سرّ التعبير في قوله تعالى: ﴿تُرْجَعُونَ فِيهِ إِلَى اللَّهِ﴾ مع أن الخلق إليه دائمًا؟","answer":"الرجوع يومئذ رجوع للحكم والجزاء بلا تصرف موهوم، و﴿فيه﴾ تجعل اليوم ظرفًا يحيط بهم وتنهار فيه كل ملكية دنيوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص377–379، تحت البقرة: 281، في القيد.","url":""}]},{"id":"s2-1418","number":1418,"surah":2,"verses":[281],"verseLabel":"البقرة: 281","question":"ما سرّ التعبير في قوله تعالى: ﴿ثُمَّ تُوَفَّى كُلُّ نَفْسٍ مَا كَسَبَتْ﴾؟","answer":"﴿توفى﴾ تدل على إعطاء الجزاء كاملًا، و﴿كل نفس﴾ تمنع الاستثناء، ثم نفى الظلم ليجمع تمام الحساب وعدله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص379–380، تحت البقرة: 281، في العموم والخاتمة.","url":""}]},{"id":"s2-1419","number":1419,"surah":2,"verses":[282],"verseLabel":"البقرة: 282","question":"لماذا جاءت أطول آية في القرآن في توثيق الدَّين؟","answer":"لأن الدين تتشعب فيه الأطراف والآجال والكتابة والشهادة واحتمالات النسيان والنزاع، فناسب حفظ الحقوق تفصيل لا إجمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص381–430، تحت البقرة: 282.","url":""}]},{"id":"s2-1420","number":1420,"surah":2,"verses":[282],"verseLabel":"البقرة: 282","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا يبخس منه شيئًا﴾ لا: ولا ينقص؟","answer":"البخس نقص مع ظلم وازدراء للحق، فهو يكشف القصد الأخلاقي المحرم لا مجرد خطأ حسابي في المقدار.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص385، تحت البقرة: 282.","url":""}]},{"id":"s2-1421","number":1421,"surah":2,"verses":[282],"verseLabel":"البقرة: 282","question":"لماذا نكّر ﴿كاتب﴾ في ﴿وليكتب بينكم كاتب بالعدل﴾؟","answer":"ليعم أي كاتب مؤهل ولا يحتكر التوثيق شخص أو طبقة، ثم قيده بالعدل لأنه مناط الثقة لا الشهرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص400، تحت البقرة: 282.","url":""}]},{"id":"s2-1422","number":1422,"surah":2,"verses":[282],"verseLabel":"البقرة: 282","question":"ما سرّ التعبير في قوله تعالى: ﴿فليكتب﴾ بالفاء بعد الأمر بإملاء المدين؟","answer":"الفاء تجعل الكتابة نتيجة فورية للإملاء الصحيح، فتربط قول صاحب الحق بما يثبته الكاتب بلا فجوة تعرضه للتغيير.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص403، تحت البقرة: 282.","url":""}]},{"id":"s2-1423","number":1423,"surah":2,"verses":[282],"verseLabel":"البقرة: 282","question":"لماذا جُعلت شهادة امرأتين مكان رجل واحد في هذا السياق؟","answer":"الحكم خاص بتوثيق الديون في واقع كانت خبرة المعاملات فيه للرجال أغلب، وجعل المرأتين للتذاكر عند النسيان لا لنقص القيمة الإنسانية.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص381–430، تحت البقرة: 282.","url":""}]},{"id":"s2-1424","number":1424,"surah":2,"verses":[282],"verseLabel":"البقرة: 282","question":"ما سرّ التعبير في قوله تعالى: ﴿أن تضل إحداهما فتذكر إحداهما الأخرى﴾ وكرر ﴿إحداهما﴾؟","answer":"ليبقي الاحتمال متبادلًا؛ لا يعين واحدة للنسيان وأخرى للتذكير، فقد تكون كل منهما معينة لصاحبتها بحسب الواقعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص381–430، تحت البقرة: 282.","url":""}]},{"id":"s2-1425","number":1425,"surah":2,"verses":[282],"verseLabel":"البقرة: 282","question":"لماذا نفى الجناح بـ﴿فليس عليكم جناح﴾ لا: فلا جناح؟","answer":"﴿ليس عليكم﴾ تلصق رفع الحرج بالمخاطبين مباشرة وتؤكده بعد طول الأمر بالكتابة، فيظهر استثناء التجارة الحاضرة بوضوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص422، تحت البقرة: 282.","url":""}]},{"id":"s2-1426","number":1426,"surah":2,"verses":[282],"verseLabel":"البقرة: 282","question":"ما سرّ التعبير في قوله تعالى: ﴿إِذَا تَدَايَنْتُمْ﴾، دون أن يقال: «إذا استدنتم» أو «أدنتم»؟","answer":"صيغة ﴿تداينتم﴾ تشمل طرفي المعاملة معًا: الدائن الذي يعطي، والمدين الذي يأخذ؛ فكلاهما داخل في حفظ العقد وكتابته. أما «استدنتم» فتتجه إلى المدينين وحدهم، و«أدنتم» إلى الدائنين. فاختيرت صيغة المشاركة لتجعل صيانة الحق مسؤولية مشتركة، لا عبئًا على أحد الطرفين فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص388–389، تحت البقرة: 282، في مبحث صيغة المفاعلة في ﴿تداينتم﴾.","url":""}]},{"id":"s2-1427","number":1427,"surah":2,"verses":[282],"verseLabel":"البقرة: 282","question":"ما سرّ التعبير في قوله تعالى: ﴿إِذَا تَدَايَنْتُمْ بِدَيْنٍ﴾؛ أليس ذكر ﴿بِدَيْنٍ﴾ زائدًا لأن التداين يدل عليه؟","answer":"جاءت الزيادة الظاهرة لفوائد: تؤكد أن الدين نفسه هو سبب وجوب الكتابة، وتدفع احتمال حمل التداين مجازًا على الوعد، ثم تهيئ اسمًا ظاهرًا يعود إليه الضمير في ﴿فاكتبوه﴾؛ فلو حُذف لقيل: «فاكتبوا الدين»، وهو أطول وأثقل. وبذلك صار ذكر ﴿بدين﴾ توكيدًا في المعنى وإيجازًا في امتداد العبارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص389–390، تحت البقرة: 282، في مبحث ذكر قيد ﴿بدين﴾ بعد ﴿تداينتم﴾.","url":""}]},{"id":"s2-1428","number":1428,"surah":2,"verses":[282],"verseLabel":"البقرة: 282","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تَسْأَمُوا أَنْ تَكْتُبُوهُ صَغِيرًا أَوْ كَبِيرًا﴾ فقدم الدين الصغير على الكبير؟","answer":"لأن مظنة التهاون بالكتابة تقع في الدين الصغير أكثر؛ فقد يقول صاحبه: هذا مبلغ قليل لا يحتاج إلى توثيق. فقدم الصغير لدفع هذا الوهم من بدايته، ثم عطف عليه الكبير لاستيعاب الجميع. والتقديم هنا لا يتبع حجم المال، بل يتجه أولًا إلى الموضع الأشد حاجةً إلى التنبيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص413–414، تحت البقرة: 282، في مبحث تقديم ﴿صغيرًا﴾ على ﴿كبيرًا﴾.","url":""}]},{"id":"s2-1429","number":1429,"surah":2,"verses":[282],"verseLabel":"البقرة: 282","question":"لماذا كلف المدين بالإملاء: ﴿وَلْيُمْلِلِ الَّذِي عَلَيْهِ الْحَقُّ﴾؟","answer":"لأنه المقر بما في ذمته، فإملاؤه أقوى في الحجة وأبعد عن زيادة الدائن، ثم أحاطه بالأمر بالتقوى والنهي عن بخس شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص396–406، تحت البقرة: 282، في إسناد الإملاء.","url":""}]},{"id":"s2-1430","number":1430,"surah":2,"verses":[282],"verseLabel":"البقرة: 282","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا يَأْبَ كَاتِبٌ أَنْ يَكْتُبَ كَمَا عَلَّمَهُ اللَّهُ﴾؟","answer":"جعل المعرفة بالكتابة نعمة يقابلها خدمة العدل، فلا يحتكرها صاحبها عند حاجة الناس. و﴿كما علمه الله﴾ تربط المهارة بالشكر والأمانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص415–429، تحت البقرة: 282، في النهي والتعليل.","url":""}]},{"id":"s2-1431","number":1431,"surah":2,"verses":[283],"verseLabel":"البقرة: 283","question":"لماذا انتقل من الكتابة في الحضر إلى ﴿وإن كنتم على سفر﴾؟","answer":"السفر مظنة فقد الكاتب وأدوات التوثيق، فانتقل إلى بديل محسوس هو الرهن المقبوض، لتبقى الحقوق محفوظة مع تغير الحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص430–446، تحت البقرة: 283.","url":""}]},{"id":"s2-1432","number":1432,"surah":2,"verses":[283],"verseLabel":"البقرة: 283","question":"لماذا عطف السفر بالواو لا بالفاء؟","answer":"لأنه حالة أخرى موازية لأحكام الدين وليست نتيجة زمنية حتمية لما قبلها؛ فالواو تجمع الأحوال بلا تعقيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص435، تحت البقرة: 283.","url":""}]},{"id":"s2-1433","number":1433,"surah":2,"verses":[283],"verseLabel":"البقرة: 283","question":"لماذا ذكر فقد الكاتب ولم يذكر فقد الشاهد؟","answer":"الكاتب هو محور الوثيقة، وإذا فقد انتقل الحكم إلى الرهن الذي يغني عن الكتابة وشهادتها، فذكر السبب الأبرز وأغنى عن تفصيل اللوازم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص435، تحت البقرة: 283.","url":""}]},{"id":"s2-1434","number":1434,"surah":2,"verses":[283],"verseLabel":"البقرة: 283","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تكتموا الشهادة... فإنه آثم قلبه﴾ فنسب الإثم إلى القلب؟","answer":"لأن الكتمان قرار باطن متعمد قبل أن يكون صمت اللسان، ولأن فساد موضع الأمانة هو أصل الجريمة وإن خفيت عن الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص430–446، تحت البقرة: 283.","url":""}]},{"id":"s2-1435","number":1435,"surah":2,"verses":[283],"verseLabel":"البقرة: 283","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنْ كُنْتُمْ عَلَى سَفَرٍ وَلَمْ تَجِدُوا كَاتِبًا فَرِهَانٌ مَقْبُوضَةٌ﴾؟","answer":"لما تعذر التوثيق بالكتابة انتقل إلى توثيق محسوس يناسب السفر، واشتراط القبض يجعل الرهن ضمانًا فعليًا لا وعدًا لفظيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص430–435، تحت البقرة: 283، في الشرط والبديل.","url":""}]},{"id":"s2-1436","number":1436,"surah":2,"verses":[283],"verseLabel":"البقرة: 283","question":"لماذا انتقل من الوثائق إلى قوله: ﴿فَإِنْ أَمِنَ بَعْضُكُمْ بَعْضًا﴾؟","answer":"اعترف بأن الثقة قد تغني عن الرهن، لكنه لم يتركها بلا وازع؛ نقل الضمان من اليد إلى أمانة القلب وتقوى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص434–440، تحت البقرة: 283، في الانتقال.","url":""}]},{"id":"s2-1437","number":1437,"surah":2,"verses":[284],"verseLabel":"البقرة: 284","question":"ما سرّ التعبير في قوله تعالى: ﴿لله ما في السماوات وما في الأرض﴾ بـ﴿ما﴾ لا ﴿من﴾؟","answer":"﴿ما﴾ تستوعب العقلاء وغيرهم والأموال والخواطر وكل الموجودات، فتمهد لشمول الحساب لما تخفيه الأنفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص449، تحت البقرة: 284.","url":""}]},{"id":"s2-1438","number":1438,"surah":2,"verses":[284],"verseLabel":"البقرة: 284","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن تبدوا ما في أنفسكم أو تخفوه يحاسبكم به الله﴾ فأثار خوف الصحابة؟","answer":"فهموا عموم الخواطر، فشق عليهم، ثم بين الختام رفع ما لا يطاق؛ والحساب على ما استقر واختير لا الوسواس العابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص446–454، تحت البقرة: 284.","url":""}]},{"id":"s2-1439","number":1439,"surah":2,"verses":[40],"verseLabel":"البقرة: 284، العنكبوت: 21، المائدة: 40","question":"لماذا قدَّم في البقرة المغفرة: ﴿فَيَغْفِرُ لِمَنْ يَشَاءُ وَيُعَذِّبُ مَنْ يَشَاءُ﴾، بينما قدَّم العذاب في العنكبوت والمائدة؟","answer":"جاءت خاتمة البقرة في خطاب المؤمنين الذين أعلنوا السمع والطاعة وطلبوا المغفرة، فناسب مقام الرجاء والرحمة أن تتقدم المغفرة. أما العنكبوت ففي إنذار منكري البعث وقوم إبراهيم، والمائدة بعد أحكام الحرابة والسرقة؛ فناسب مقام الزجر والتهديد أن يتقدم العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص222–223، تحت العنكبوت: 21، في المقارنة بالبقرة: 284 والمائدة: 40.","url":""}]},{"id":"s2-1440","number":1440,"surah":2,"verses":[284],"verseLabel":"البقرة: 284","question":"ما سرّ التعبير في قوله تعالى: ﴿لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ﴾ بعد أحكام الأموال؟","answer":"ذكّر أن كل مال وذمة وشاهد مملوك لله، فلا معنى للتحايل على حق داخل ملكه. والعموم يمهد لعلمه بما في الأنفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص446–448، تحت البقرة: 284، في المناسبة.","url":""}]},{"id":"s2-1441","number":1441,"surah":2,"verses":[284],"verseLabel":"البقرة: 284","question":"لماذا يحاسب الله على ما في الأنفس، مع أن الخاطر قد لا يملكه الإنسان؟","answer":"الآية تقرر إحاطة العلم والحساب بما استقر واختير، لا الوساوس العابرة التي تبين النصوص العفو عنها؛ وخواتيم السورة تبين الرحمة ورفع التكليف بما لا يطاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص448–451، تحت البقرة: 284، في دلالة الإبداء والإخفاء.","url":""}]},{"id":"s2-1442","number":1442,"surah":2,"verses":[284],"verseLabel":"البقرة: 284","question":"لماذا ختم بـ﴿وَاللَّهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ﴾ بعد المغفرة والعذاب؟","answer":"لأن تنفيذ الحساب والمغفرة والعقوبة جميعًا فرع القدرة الشاملة، فلا يعجزه باطن خفي ولا كثرة الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص451–453، تحت البقرة: 284، في الفاصلة.","url":""}]},{"id":"s2-1443","number":1443,"surah":2,"verses":[285],"verseLabel":"البقرة: 285","question":"ما سرّ التعبير في قوله تعالى: ﴿آمن الرسول﴾ بالماضي لا يؤمن؟","answer":"الماضي يحقق ثبوت الإيمان واستقراره كحقيقة منجزة عند نزول الوحي، لا حالة منتظرة أو متقلبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص462، تحت البقرة: 285.","url":""}]},{"id":"s2-1444","number":1444,"surah":2,"verses":[285],"verseLabel":"البقرة: 285","question":"لماذا أفرد الرسول أولًا ثم جمع المؤمنين في ﴿والمؤمنون كل آمن﴾؟","answer":"قدم أول متلق ومصدق ثم ألحق به الجماعة، لتظهر وحدة العقيدة مع تميز موقع الرسول في تلقي التنزيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص454–468، تحت البقرة: 285.","url":""}]},{"id":"s2-1445","number":1445,"surah":2,"verses":[285],"verseLabel":"البقرة: 285","question":"ما دلالة قول المؤمنين: ﴿سَمِعْنَا وَأَطَعْنَا﴾ بهذا الترتيب؟","answer":"السماع تلقي وفهم، والطاعة ثمرة عملية؛ فرتبوا الاستجابة من ورود الأمر إلى تنفيذه، خلاف من قالوا سمعنا وعصينا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص454–468، تحت البقرة: 285.","url":""}]},{"id":"s2-1446","number":1446,"surah":2,"verses":[285],"verseLabel":"البقرة: 285","question":"لماذا ختموا بـ﴿غفرانك ربنا وإليك المصير﴾ بعد الإيمان والطاعة؟","answer":"لم يغتروا بالطاعة بل اعترفوا بالتقصير وطلبوا المغفرة، واستحضار المصير يجعل الامتثال خاضعًا للرجاء والخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص454–468، تحت البقرة: 285.","url":""}]},{"id":"s2-1447","number":1447,"surah":2,"verses":[285],"verseLabel":"البقرة: 285","question":"ما دلالة قول المؤمنين: ﴿سَمِعْنَا وَأَطَعْنَا﴾ بهذا الترتيب، ثم طلب المغفرة بعدهما؟","answer":"السماع طريق التكليف، والطاعة أثره؛ فلا طاعة قبل بلوغ الأمر وفهمه، لذلك تقدم ﴿سمعنا﴾. ثم قدّم المؤمنون إقرارهم بالقبول والعمل على سؤال المغفرة؛ لأن تقديم وسيلة القبول بين يدي الدعاء أقرب إلى الإجابة، فكأنهم قالوا: تلقينا أمرك وانقدنا له، ومع ذلك نحن مفتقرون إلى مغفرتك عن التقصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص459–461، تحت البقرة: 285، في مبحث السماع وتقديمه على الطاعة والمغفرة.","url":""}]},{"id":"s2-1448","number":1448,"surah":2,"verses":[285],"verseLabel":"البقرة: 285","question":"ما سرّ التعبير في قوله تعالى: ﴿كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ﴾؟","answer":"﴿كل﴾ تجمع الرسول والمؤمنين وتفصل عقيدة كل فرد، ثم ترتب أصول الغيب والوحي وحملته في نسق واحد متكامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص457–461، تحت البقرة: 285، في العموم والترتيب.","url":""}]},{"id":"s2-1449","number":1449,"surah":2,"verses":[285],"verseLabel":"البقرة: 285","question":"ما دلالة قولهم: ﴿لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ﴾ بعد ذكر تفضيل بعض الرسل؟","answer":"لا نفرق في أصل التصديق والقبول، وإن تفاوتت منازلهم التي فضلهم الله بها؛ فالتفضيل الإلهي لا يبرر إيمانًا ببعض وكفرًا ببعض.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص460–464، تحت البقرة: 285، في دفع التعارض.","url":""}]},{"id":"s2-1450","number":1450,"surah":2,"verses":[286],"verseLabel":"البقرة: 286","question":"ما سرّ التعبير في قوله تعالى: ﴿لا يكلف الله نفسًا إلا وسعها﴾ لا طاقتها؟","answer":"الوسع ما يمكن فعله بلا حرج بالغ، أما الطاقة فقد تعني أقصى قدرة مع مشقة؛ فاختير اللفظ الأرفق في خاتمة التكاليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص468–481، تحت البقرة: 286.","url":""}]},{"id":"s2-1451","number":1451,"surah":2,"verses":[286],"verseLabel":"البقرة: 286","question":"ما سرّ التعبير في قوله تعالى في الخير ﴿لها ما كسبت﴾، وفي الشر ﴿عليها ما اكتسبت﴾ بزيادة التاء؟","answer":"الكسب أخف فناسب الخير الموافق للفطرة، والاكتساب ذو زيادة وتكلف فناسب الشر الذي تتحمله النفس؛ كما قابلت اللام النافعة ﴿على﴾ الضارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص468–481، تحت البقرة: 286.","url":""}]},{"id":"s2-1452","number":1452,"surah":2,"verses":[286],"verseLabel":"البقرة: 286","question":"لماذا كرر المؤمنون ﴿ربنا﴾ في كل دعاء من ختام السورة؟","answer":"جددوا الافتقار عند كل مطلب وجعلوا كل رجاء مستقلًا بالعناية، واستدعوا اسم الرب بما فيه من التربية والرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص468–481، تحت البقرة: 286.","url":""}]},{"id":"s2-1453","number":1453,"surah":2,"verses":[286],"verseLabel":"البقرة: 286","question":"ما سرّ التعبير في قوله تعالى: ﴿لا تؤاخذنا إن نسينا أو أخطأنا﴾ مع أن النسيان والخطأ غير متعمدين؟","answer":"دعاء برفع آثار الخطأ وتبعاته وتعليم دائم للافتقار، وقد استجاب الله برفع المؤاخذة التي لا اختيار فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص468–481، تحت البقرة: 286.","url":""}]},{"id":"s2-1454","number":1454,"surah":2,"verses":[286],"verseLabel":"البقرة: 286","question":"لماذا شبّه التكاليف الشاقة بـ﴿الإصر﴾ المحمول؟","answer":"الإصر حمل ثقيل يقيد صاحبه، فصورت به العهود والأحكام الشاقة التي حملتها أمم سابقة وطلب المؤمنون تخفيفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص468–481، تحت البقرة: 286.","url":""}]},{"id":"s2-1455","number":1455,"surah":2,"verses":[286],"verseLabel":"البقرة: 286","question":"لماذا تدرج الدعاء: ﴿واعف عنا واغفر لنا وارحمنا﴾؟","answer":"العفو يمحو أثر الذنب، والمغفرة تستره وتقي تبعته، والرحمة تمنح الخير فوق مجرد النجاة؛ فترقى من الإزالة إلى الفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص468–481، تحت البقرة: 286.","url":""}]},{"id":"s2-1456","number":1456,"surah":2,"verses":[286],"verseLabel":"البقرة: 286","question":"لماذا ختمت أطول سور القرآن بالدعاء ﴿أنت مولانا فانصرنا على القوم الكافرين﴾؟","answer":"بعد بناء الأمة بالعقيدة والشريعة أعلن افتقارها إلى وليها لتنفيذ الرسالة ومواجهة الباطل؛ فالنصر ثمرة الولاية لا قوة الذات.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص468–486، تحت البقرة: 286.","url":""}]},{"id":"s2-1457","number":1457,"surah":2,"verses":[7],"verseLabel":"البقرة: 286، الطلاق: 7","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا﴾، وقوله تعالى في الطلاق: ﴿لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا مَا آتَاهَا﴾؟","answer":"جاءت آية البقرة بعد إقرار المؤمنين بالسمع والطاعة ودعائهم برفع الآصار، فقررت القاعدة العامة: لا تكليف فوق الطاقة. أما آية الطلاق ففي نفقة المطلقة، وقد سبقها تقسيم الناس إلى موسر ومقدور عليه رزقه؛ فناسب أن يربط التكليف بمقدار ما آتى الله كلَّ شخص من الرزق.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص419–420، تحت الطلاق: 7، في المقارنة بالبقرة: 286.","url":""}]},{"id":"s2-1458","number":1458,"surah":2,"verses":[286],"verseLabel":"البقرة: 286","question":"لماذا تكرر النداء ﴿رَبَّنَا﴾ في الدعوات السابقة، ثم لم يتكرر قبل قوله: ﴿وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا﴾؟","answer":"لأن الدعوات الثلاث الأخيرة نتائج جامعة لما سبق: العفو يقابل عدم المؤاخذة، والمغفرة تناسب رفع الإصر، والرحمة تناسب عدم تحميل ما لا طاقة به؛ فكأن الجميع دعاء واحد متصل لم يحتج إلى نداء جديد. وفي حذف النداء بعد دوام التضرع إشعار بالقرب: النداء يطلب للبعيد، أما من استمر في المناجاة فقد صار في مقام القرب والاتصال.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص477–478، تحت البقرة: 286، في مبحث عدم تكرار نداء الربوبية.","url":""}]},{"id":"s2-1459","number":1459,"surah":2,"verses":[286],"verseLabel":"البقرة: 286","question":"لماذا ختم الدعاء بقوله: ﴿فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ﴾، ولم يقل: «فانصرنا على الكافرين»؟","answer":"طلب النصر هنا ليس على كل فرد منفرد، فقد يغلب مؤمنٌ كافرًا في موقف خاص؛ وإنما هو على الكافرين بوصفهم جماعةً مجتمعة ذات قوة وشوكة قائمة على الباطل. لذلك أضاف ﴿القوم﴾ لتحدد المطلوب: نصر الأمة المؤمنة على القوة المنظمة المعادية، لا مجرد الغلبة الفردية المتفرقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص479، تحت البقرة: 286، في مبحث التعبير بـ﴿القوم الكافرين﴾.","url":""}]},{"id":"s2-1460","number":1460,"surah":2,"verses":[286],"verseLabel":"البقرة: 286","question":"ما مناسبة ختم السورة بقوله تعالى: ﴿لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا﴾ بعد كثرة الأحكام؟","answer":"جاء الختام ضمانًا أن المنهج الطويل كله داخل الطاقة التي يعلمها الخالق؛ فالتكاليف ليست لإعنات الإنسان بل لبنائه في حدود وسعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص468–472، تحت البقرة: 286، في مناسبة الختام.","url":""}]},{"id":"s3-1","number":1,"surah":3,"verses":[1],"verseLabel":"آل عمران: 1","question":"لماذا افتُتحت سورة آل عمران بـ﴿الم﴾ كما افتتحت البقرة، مع اختلاف موضوع السورتين؟","answer":"تشترك السورة مع البقرة في استهلال السامع بالحروف المقطعة والتنبيه إلى مادة الكتاب المعجز، ثم تفترق عنها بما يلي المطلع: فآل عمران تبادر إلى تقرير التوحيد والقيومية وتنزيل الكتب، وهو مدخل حجاجها مع أهل الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص495–496.","url":""}]},{"id":"s3-2","number":2,"surah":3,"verses":[2],"verseLabel":"آل عمران: 2","question":"لماذا جاء بعد الحروف المقطعة مباشرة ﴿الله لا إله إلا هو الحي القيوم﴾؟","answer":"جاء هذا التقرير عقب المطلع ليجعل أصل السورة توحيد الله وكمال حياته وقيوميته؛ ومن كان حيًّا قيومًا هو وحده مصدر الوحي والحاكم في شأن عيسى والكتب المنزلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص497–500.","url":""}]},{"id":"s3-3","number":3,"surah":3,"verses":[2],"verseLabel":"آل عمران: 2","question":"لماذا جُمع الاسمان ﴿الحي القيوم﴾ في افتتاح السورة؟","answer":"﴿الحي﴾ يدل على كمال الذات والحياة التي لا يلحقها نقص، و﴿القيوم﴾ على قيامه بنفسه وإقامته أمر خلقه؛ فاجتماعهما يجمع كمال الذات وكمال التدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص497–500.","url":""}]},{"id":"s3-4","number":4,"surah":3,"verses":[255],"verseLabel":"آل عمران: 2؛ البقرة: 255","question":"لماذا وردت جملة ﴿الله لا إله إلا هو الحي القيوم﴾ في افتتاح آل عمران، بينما جاءت في وسط سورة البقرة في آية الكرسي؟","answer":"في آل عمران تؤسس الجملة من أول السورة قضية التوحيد والقيومية في مواجهة جدل أهل الكتاب في عيسى والوحي، أما في البقرة فجاءت ذروةً لآيات التشريع والإيمان لتقرر سلطان الله الذي تقوم عليه الأحكام؛ فاتحد الأصل واختلف موقعه ووظيفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص497–500، مع ج3، ص556–574.","url":""}]},{"id":"s3-5","number":5,"surah":3,"verses":[3],"verseLabel":"آل عمران: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿نزّل عليك الكتاب﴾ بالتشديد، ثم قال ﴿وأنزل التوراة والإنجيل﴾؟","answer":"التنزيل بالتشديد يلائم نزول القرآن منجّمًا متتابعًا، أما الإنزال في التوراة والإنجيل فيلحظ أصل إيتائهما وإنزالهما؛ فاختلاف الصيغة يراعي كيفية التنزيل ومقامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص501–512.","url":""}]},{"id":"s3-6","number":6,"surah":3,"verses":[3],"verseLabel":"آل عمران: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿عليك﴾ في نزول القرآن، دون أن يقال: إليك؟","answer":"حرف ﴿على﴾ يصوّر الوحي نازلاً من علو، ويحمل معنى التكليف والثقل الذي تحمّله الرسول، وهو معنى لا تؤديه ﴿إلى﴾ وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص501–507.","url":""}]}]);
